window.__D("text/torat-shmuel/c011",{"p":[[2000510292,"ג\"כ ארי', וכן הארי' שבאצי' הוא בחי' החסד דאצי' הוא רק כמו משל לגבי בחי' החכמה שנק' ג\"כ ארי' כמ\"ש וירא ראשית לו, שראשית הוא בחי' ראשית חכ', וארי' הוא אותיות ראי', וכן בחי' ארי' דחכמה הוא רק כמו משל לבחי' הכתר שנק' ג\"כ ארי' כמ\"ש ארי' שאג מי לא יירא ה' אלקי' דיבר מי לא ינבא ואיתא בספרים שזהו בחי' הדבור דאנכי הוי' אלקיך<sup data-n=\"893\">7</sup> שהוא בחי' הכתר. וכן עד\"ז בכל שארי הנבראים דבי\"ע הנה כל בחי' הוא רק משל לגבי שלמעלה הימנו, ועז\"נ וידבר שלמה שלשת אלפים משל, פי' שלשת אלפים מדרגות שכל בחי' לגבי שלמעלה הימנו הוא רק כמו בחי' המשל לגבי השכל, ושלשת אלפים מדרגות הם כנגד ג' עולמות בי\"ע<sup data-n=\"894\">8</sup>, ושלמה שהי' בחי' מל' דאצי' השיג שלשת אלפים מדרגות שכל א' הוא משל לחבירו, להיותו המקור לג' עולמות בי\"ע כו', לכן השיג ג' אלפים מדרגות שכל א' הוא משל לגבי שלמעלה הימנו.\n<b>וזהו</b> שארז\"ל במד\"ר פ' תרומה כל מה שברא הקב\"ה למעלה ברא למטה, למעלן שרפים עומדים ולמטה עצי שטים עומדים<sup data-n=\"895\">9</sup>, שנמשלו המלאכים לעצי שטים וכן כתיב אז ירננו עצי היער שקאי על המלאכים שנק' בשם עצי היער<sup data-n=\"896\">10</sup>, וכן כתי' כי האדם עץ השדה, שנמשלו המלאכים והאדם לעצי השדה, והיינו שכמו עצי השדה הם בחי' צומח שצומח מקטנות לגדלות, שתחלה הוא קטן עד שמתגדל ונעשה אילן גדול, ועד\"ז יובן במלאכי מעלה שהגם שמלאך מיכאל עד\"מ הוא מבחי' החסד והאהבה מ\"מ קודם שאומר שירה או קודם השליחות ששולחין אותו המדה אצלו בקטנות, וכששולחין אותו או בשעה שאומר שירה מתגדל האהבה בתוקף עוז, ולכן המלאך בעת השליחות יכול לקרות עצמו בשם שולחו כמ\"ש בי נשבעתי נאום הוי', וכתי' ותקרא שם הוי'<sup data-n=\"897\">11</sup> הדובר אלי', והיינו שבשעת השליחות הוא בטל כ\"כ לגבי המשלח עד שנקרא כל מהותו ע\"ש המשלח הרי נגדל בחי' המדות שלו מכמו שהיו, וה\"ז כמשל הצומח<sup data-n=\"898\">12</sup>. ועד\"ז הוא מה שנמשל האדם לעץ השדה, היינו שבחי' המדות שבאדם נמשלו לצומח, שכמו עץ הצומח הנה הוא צומח מקטנות",[["893","7","<b>ארי' שאג. . ואיתא בספרים שזהו בחי' הדבור דאנכי הוי' אלקיך</b>: ראה שמו\"ר פכ\"ט, ט: אנכי ה\"א הה\"ד ארי' שאג מי לא יירא. הובא ונת' ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600447\" data-slug=\"or-hatorah-hb\" data-id=\"8316600447\">אוה\"ת</a> דרושים לחגה\"ש ע' רכא. דרושים לר\"ה ע' א'תכח. נ\"ך עה\"פ ע' תמז. וראה אוה\"ת יתרו ע' תתקלא [ושם מביא גם מהמאו\"א שארי' בחי' כתר]."],["894","8","<b>וידבר שלמה שלשת אלפים משל. . ג' עולמות בי\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. מג\"א צח, ב. מאמרי אדה\"ז עה\"ת ח\"א ע' שנ [ובהמ\"מ שם]. סה\"מ מלוקט ח\"ג ע' לז. סה\"ש תשמ\"ט ח\"א ע' 151 הע' 31. ובכ\"מ."],["895","9","<b>שארז\"ל. . למעלן שרפים עומדים ולמטה עצי שטים עומדים</b>: ראה גם סה\"מ תר\"ל ע' צד. ובארוכה ד\"ה באתי לגני (ומאמרים שלאח\"ז) תשל\"ט (סה\"מ תשל\"ט (הוצאת תשס\"ב) ע' 95 ואילך. ובסה\"מ באתי לגני ח\"ב ס\"ע קנט ואילך)."],["896","10","<b>המלאכים שנק' עצי היער</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381258\" data-slug=\"likkutei-torah\" data-id=\"4001381258\">לקו\"ת שה\"ש לב, ב</a>. סה\"מ תרל\"ג ח\"א ע' קט."],["897","11","<b>המלאך בעת השליחות. . ותקרא שם הוי'</b>: ראה אגה\"ק סי' כה (קמא, סע\"א). ובקו\"א לתניא קנט, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380352\" data-slug=\"likkutei-torah\" data-id=\"4001380352\">לקו\"ת במדבר יא, א</a>-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381211\" data-slug=\"likkutei-torah\" data-id=\"4001381211\">ב. שה\"ש כ, ג</a>. מאמרי אדהאמ\"צ במדבר ח\"ב ע' תח ואילך. דרמ\"צ כז, א. אוה\"ת תשא ע' ב'לא. סה\"מ תרכ\"ט ע' ריב ואילך. תרל\"ב ח\"א ע' מ. וש\"נ. תרל\"ג ח\"א ס\"ע נב-ג. ועוד."],["898","12","<b>בחי' המדות. . כמשל הצומח</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א בראשית ד, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380545\" data-slug=\"likkutei-torah\" data-id=\"4001380545\">לקו\"ת חוקת נז, ב</a>. נח, א. תו\"ח בראשית יט, ד."]]],[2000510293,"לגדלות, כמו\"כ מדות שבאדם קודם התבוננותו בגדולת הבורא הם קטנים, וכשמתבונן ומעמיק דעת בגדולת הבורא מתגדל המדה בתוקף עוז האהבה ביתר שאת ויתר עז מכמו שהיתה כו'. אמנם העץ הגשמי שנמשל למדות שבאדם ומדות שבמלאכים, הנה הוא רק משל לבחי' האהבה שבמלאכים ונשמות, אבל אינו בערך כלל, כ\"א כמו ערך המשל לגבי השכל כו'.\n<b>ועד\"ז</b> בכל פרטי הנבראים שכל בחי' היא רק משל לגבי שלמעלה הימנה, ואפי' בתורה כתי' כאשר יאמר משל הקדמוני<sup data-n=\"899\">13</sup> שיש בזה ב' פי', הא' שהתורה שלמטה שנתלבשה בעניני' גשמי' כמו ציצית בצמר גשמי ותפילין בקלף גשמי וכדומה, הנה הם רק משל לגבי התורה כמו שהיא למעלה במתיבתא דרקיע, שאין שייך שם בחי' גשם צמר הציצית או קלף התפילין, כ\"א בחי' הרוחניות שבמדרגות אלו שענין הציצית הוא כמ\"ש ויקחני בציצית ראשי שרומז לבחי' הקוצי דשערי דז\"א<sup data-n=\"900\">14</sup> שמכה ברישא דנוק', או רוחניות התפילין הו\"ע המשכת מוחין לז\"א<sup data-n=\"901\">15</sup>, שהציצית והתפילין הגשמי' הם רק כמו משל לגבי השכל. או י\"ל פ\"א<sup data-n=\"902\">16</sup> בענין משל הקדמוני שגם התורה כמו שהיא למעלה היא ג\"כ רק משל להבין בחי' אוא\"ס קדמונו של עולם, אך מ\"מ אינו דומה בחי' המשלים דתורה לבחי' המשלים שבעש\"ן, שע\"י המשלים דתורה מבינים הנמשל כו', וה\"ז כמו השכל שאומרים אותו במשל, שהגם שהמשל מלביש את השכל מ\"מ ע\"י המשל מבינים את השכל, ונמצא כי אינו מסתיר כ\"כ שהרי יכולים להבין הנמשל ממשל זה, אבל ענין המשלים דעש\"ן מה שכל א' הוא משל לגבי שלמעלה הימנו הנה ע\"י משל שלמטה היינו בחי' הארי' שלמטה עד\"מ אינם מבינים כלל בחי' הארי' שלמעלה שאומר קדוש וברוך, שאינו בערך כלל שיהי' מובן הארי' שלמעלה מגשמיות הארי' שלמטה, רק שמ\"מ הוא משל אליו, שהרי עכ\"פ חיותו נמשך מבחי' הארי' שלמעלה כו' כמ\"ש במ\"א<sup data-n=\"903\">17</sup>. אבל הנה משל זה מסתיר לגמרי ומכסה מאד את הנמשל שהרי אינו מובן כלל ממנו כו', ושרש ההעלמות והסתרים אלו שבבחי' עש\"ן דבי\"ע זהו נמשך מבחי' שם שדי שאמר לעולמו די בבחי' הגבלה.\n<b>אך</b> עדיין צ\"ל מ\"ש באברהם<sup data-n=\"904\">18</sup> גבי מילה אני אל שדי התהלך לפני והי' תמים משמע ששם שדי נגלה לאברהם ע\"י מצות מילה ולפמשנ\"ל שם שדי הוא",[["899","13","<b>בתורה כתיב כאשר יאמר המשל הקדמוני</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370439\" data-slug=\"torah-or\" data-id=\"3901370439\">תו\"א מג\"א צח, ב</a>. מאמרי אדה\"ז תקס\"ב ח\"ב ס\"ע תקנה [ובהמ\"מ שם]. מאמרי אדהאמ\"צ במדבר ח\"א ע' לז. ח\"ב ע' תקנג. דברים ח\"ב ע' תב [וש\"נ למקומות נוספים]. וראה אוה\"ת וארא ע' קנב."],["900","14","<b>שענין הציצית. . הקוצי דשערי דז\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380496\" data-slug=\"likkutei-torah\" data-id=\"4001380496\">לקו\"ת שלח מו, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">תזריע כג, סע\"א</a>-ב. ובכ\"מ."],["901","15","<b>התפילין הו\"ע המשכת מוחין לז\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370162\" data-slug=\"torah-or\" data-id=\"3901370162\">תו\"א מקץ לה, ב</a>. ובכ\"מ."],["902","16","<b>פ\"א</b>: פי' אחר."],["903","17","<b>הארי' שלמטה. . מבחי' הארי' שלמעלה כו' כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370119\" data-slug=\"torah-or\" data-id=\"3901370119\">תו\"א וישלח כה, ג</a>. ביאוה\"ז לאדהאמ\"צ נ, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' סא ואילך. אוה\"ת וארא ע' קסד. לקמן ד\"ה לא תבערו. וש\"נ."],["904","18","<b>אך עדיין צ\"ל מ\"ש באברהם</b>: בהבא להלן ראה ד\"ה ויצוום שבסה\"מ תרכ\"ז שם ע' פט. וד\"ה והר סיני שבסה\"מ תרכ\"ח שם ע' קמח-ט. סה\"מ תר\"ל ע' סא ואילך. תרל\"ה ח\"א ע' מג ואילך. סה\"מ מלוקט ח\"ה ע' קלז ואילך."]]],[2000510294,"מברה\"ע. אך הענין הוא דהנה רש\"י ז\"ל פי' ע\"פ אני אל שדי, שדי באלקותי לכל ברי' והוא מהמד\"ר על פסוק הנ\"ל, ונמצא לפ\"ז יחלק פי' לשון די לשני אופנים<sup data-n=\"905\">19</sup>, הא' די ל' שאמר לעולמו די, שהוא פי' לא יותר, וכמו עד פה תבוא ולא יותר, אבל יש פי' בתיבת די כמו די מחסורו הנאמר גבי צדקה שארז\"ל אפי' סוס לרכוב עליו, או כמ\"ש והריקותי לכם ברכה עד בלי די שארז\"ל עד שיבלו שפתותיכם מלומר די, שפי' שיהי' השפעה בריבוי כ\"כ עד שיבלו שפתותיהם מלומר די שפי' שיהי' בריבוי מאד, ונמצא פי' שיהי' כ\"כ בריבוי עד שכ\"א יאמר שההשפעה היא די. ועפ\"ז יש לפרש ששם שדי שהי' בברה\"ע פי' די שאמר לעולמו די כמו עד פה תבוא, וכמארז\"ל על הרקיעים שהיו מתפשטים עד שגער בהם ואמר להם די, אבל ש' שדי שנגלה לאברהם ע\"י מצות מילה הוא ג\"כ די, אבל פי' די עד שיבלו שפתותיכם מלומר די על ריבוי ההשפעה, שיהי' כ\"כ בריבוי עד שכ\"א יאמר די והותר, וזהו מלשון שנא' במלאכת המשכן והמלאכה היתה דים לכל המלאכה לעשות אותה והותר (בפ' ויקהל ל\"ו ז'). וביאור הענין דהנה הנהגת העולמות מתנהג ע\"פ דרכי הטבע שנמשך מבחי' ש' אלקים שהוא בגימ' הטבע<sup data-n=\"906\">20</sup>, וזהו ג\"כ ענין ש' שדי שאמר לעולמו די בחי' ההגבלה עד פה תבוא כו' כנ\"ל. אבל להאבות נתגלה לאברהם ע\"י המילה בבחי' שם שדי שדי באלקותי לכל ברי', פי' שמבחי' זו נמשך גם ענין הנס. וזהו שדי באלקותי לכל ברי' שיכול להיות נמשך מבחי' זו גם נס, אך היינו בחי' הניסים שמתלבשים בדרכי הטבע, כמו נס דאסתר שמלובש בדרכי הטבע שמחמת אהבת אסתר הרג את המן.\n<b>אמנם</b> כדי להיות בחי' ניסים שיוצאים מדרכי הטבע<sup data-n=\"907\">21</sup> לגמרי, כמו נס דקי\"ס שהוא יוצא מדרכי הטבע לגמרי זהו נמשך מבחי' שם הוי', כי שם הוי' הוא בחי' הי' הוה ויהי' כא' שזהו למעלה מבחי' ההגבלה שנמשך מבחי' ש' אלקים ושם שדי, שמשני שמות אלו נמשך בחי' מספר שהוא בחי' ההגבלה, אבל בחי' שם הוי' הוא בלי מספר שהוא למעלה מבחי' הגבלת הטבע כו'. דהנה כתי' גדול אדונינו ורב כח ולתבונתו אין מספר, פי' ורב כח כי שיעור קומה של יוצר בראשית<sup data-n=\"908\">22</sup> הם רל\"ו אלפים רבבות פרסאות, והפרסאות הם פרסאות של מעלה, והרי זהו מספר גדול, אמנם מ\"מ הוא מספר, אבל לתבונתו אין מספר. ולכאו' צ\"ל מה שייך לשון מספר בתבונה והל\"ל ולתבונתו אין חקר. אך הענין דמ\"ש ולתבונתו אין מספר הכוונה על בחי' ההשגות שבג\"ע, שהגם שלא נז' בספרים רק שני בחי' ג\"ע היינו בחי' ג\"ע התחתון וגעה\"ע, אבל באמת יש כמה בחי' בג\"ע, וכמ\"ש ילכו מחיל אל חיל וארז\"ל",[["905","19","<b>פי' לשון די לשני אופנים</b>: בכ\"ז ראה אוה\"ת וארא ע' קלד ואילך. שם ע' קנד ואילך, ובהנסמן בהע' שלפנ\"ז."],["906","20","<b>שם אלקים שהוא בגימ' הטבע</b>: ראה שעהיוה\"א רפ\"ו (פ, סע\"א) [ובהנסמן בהמ\"מ לשם]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380805\" data-slug=\"likkutei-torah\" data-id=\"4001380805\">לקו\"ת ראה כב, סע\"ב</a>-ג. ובכ\"מ."],["907","21","<b>אמנם. . ניסים שיוצאים מדרכי הטבע</b>: בהבא להלן ראה ד\"ה ויצוום תקס\"ח באוה\"ת וארא שם ס\"ע קצט ואילך."],["908","22","<b>גדול אדונינו ורב כח. . שיעור קומה של יוצר בראשית</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380309\" data-slug=\"likkutei-torah\" data-id=\"4001380309\">לקו\"ת ויקרא נד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380514\" data-slug=\"likkutei-torah\" data-id=\"4001380514\">שלח נ, ג</a>. אוה\"ת וארא שם ע' קצז. ובהנסמן ע\"ז בארוכה ב”מילואים להמ\"מ\" בס' מאמרי אדהאמ\"צ במדבר ח\"א ר\"ע דש. ובסה\"מ תרל\"ח שם ע' ז."]]],[2000510295,"צדיקים אין להם מנוחה לא בעוה\"ז ולא בעוה\"ב שגם בעוה\"ב הם הולכים מחיל אל חיל בהשגות שונות זמ\"ז, ולכן יש נהר דינור שצריכים נשמות הצדיקים לטבול<sup data-n=\"909\">23</sup> בהם בין עליות מגעה\"ת לשלמעלה הימנו, בכדי שישכח על ההשגה שהשיג בג\"ע התחתון שלא יבלבל אותו בג\"ע שלמעלה הימנו, וכמו ר\"ז שצם מאה תעניתא<sup data-n=\"910\">24</sup> כי היכא דלישכח תלמוד בבלי כדי שלא יבלבל אותו בלימוד תורת ירושלמי שמעלת לימוד הירושלמי<sup data-n=\"911\">25</sup> ארז\"ל במד\"ר ע\"פ וזהב הארץ ההיא טוב שאין תורה כתורת א\"י ואין חכמה כחכמת א\"י, וזהו ג\"כ שארז\"ל כל רב מבבל וכל רבי מא\"י<sup data-n=\"912\">26</sup>, ששם מאיר בחי' היו\"ד שהוא בחי' חכמה, אשר ע\"כ היו סמוכים כו', ולכן כדי שלא יבלבל אותו הלימוד מתלמוד בבלי צם מאה תעניתא כי היכא דלישכח ההשגה שהשיג בחו\"ל. ועד\"ז כשצריכה הנשמה להתעלות מבחי' השגתה בג\"ע התחתון להשיג השגה זו עצמה בג\"ע שלמעלה הימנה, אשר שם הלכה זו עצמה היא נעלה יותר באין ערוך, צריך לטבול בנהר דינור בכדי שישכח מה שהשיג בג\"ע שלמטה הימנה בכדי שלא יבלבלנה כו'. ועד\"ז יש רבבות מדרגות בג\"ע בלי מספר השגות עד אין קץ, והיינו מפני שבג\"ע נאמר שם מלא הוי' אלקים כמ\"ש ויטע ה' אלקים גן בעדן מקדם, לכן ולתבונתו הוא בחי' ההשגות שבג\"ע הוא בלי מספר להיותו מבחי' שם הוי' שהוא בלי מספר כו'.\n<b>ועפ\"ז</b> יובן ענין יצ\"מ שפי' לצאת מהמצרים וגבולים<sup data-n=\"913\">27</sup>, דכמו שיש מצרים בקלי' כמו\"כ יש בחי' מצרים בקדושה, והיינו בחי' המצרים וגבולים והעלמות שנמשכים מבחי' שם אלקים ושם שדי שאמר לעולמו די, היינו שיהי' די, שיהי' מהארץ לרקיע מהלך ת\"ק שנה, ובין כל רקיע מהלך ת\"ק שנה ועובי כל רקיע מהלך ת\"ק שנה שזהו הגבלה לכן נק' זה בשם מיצר, וענין יצ\"מ היינו לצאת מהמצרים וגבולים. וז\"ע התפלה בחי' ק\"ש פסוק ראשון שמע ישראל, שמע הוא ר\"ת שאו מרום עיניכם, והיינו להתבונן איך שהוי' אלקינו ה' אחד וארז\"ל אין כיוצא בו, שפי' שאין ערוך לך לפי שכולא קמי' כלא חשיבי, שלכאורה אינו מובן איך נאמר שכלא חשיבי הלא נתהוו העולמות בבחי' מציאות זמן ומקום. אך הענין הוא דהנה בבחי' שבגדר מספר והגבלה הנה א' לגבי אלף אלפים וריבוי רבבות יש לו ערך, ואפי' טיפה נגד הים הגדול יש לו ערך וכמו שאמר ר\"י יכולני לשער כמה",[["909","23","<b>נהר דינור שצריכים נשמות הצדיקים לטבול</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370145\" data-slug=\"torah-or\" data-id=\"3901370145\">תו\"א מקץ לא, א</a>-<a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">ב. לב, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">יתרו סט, ג</a>. מג\"א צו, א. מאמרי אדה\"ז אתהלך-לאזניא ע' קכו. קסח. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תרעה וע' תתכא-ב [ובהמ\"מ שם]. דברים ח\"א ע' נט [ובהמ\"מ שם]."],["910","24","<b>וכמו ר\"ז שצם מאה תעניתא</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">תו\"א יתרו סט, ג</a> שם. מאמרי אדה\"ז תקס\"ו ע' רטו. מאמרי אדהאמ\"צ במדבר ח\"ב ע' תמא. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תכא. ועוד."],["911","25","<b>תלמוד בבלי. . שמעלת לימוד הירושלמי</b>: ראה בארוכה סה\"מ תרל\"ב ח\"א ע' כה. וש\"נ. וע' לב. תרל\"ג ח\"ב ע' תכז. וש\"נ."],["912","26","<b>כל רב מבבל וכל רבי מא\"י</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370525\" data-slug=\"torah-or\" data-id=\"3901370525\">תו\"א קיז, ג</a>. ואילך. מאמרי אדה\"ז תקס\"ח ח\"א ע' צד ואילך."],["913","27","<b>ועפ\"ז יובן ענין יצ\"מ. . לצאת מהמצרים וגבולים</b>: בהבא להלן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370286\" data-slug=\"torah-or\" data-id=\"3901370286\">תו\"א בשלח סד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380227\" data-slug=\"likkutei-torah\" data-id=\"4001380227\">לקו\"ת אמור לה, סע\"ב</a>-ג. ועוד."]]],[2000510296,"טיפות יש בים<sup data-n=\"914\">28</sup>, והיינו כי יכולים לספור כמה טפות יש ברביעית וכמה רביעית יש בהין וכמה הין יהי' במדה גדולה וכמה מדות יהי' בים, ונמצא שיכולים לשער. אבל לגבי בלי מספר שוה מספר אחד כמו מספר רבוא רבבות כי מספר לגבי בלי מספר אינו בערך כלל, ולכן הגם כי נתהוו העולמות לבחי' עולמות מוגבלים, מ\"מ לגבי אוא\"ס ב\"ה בחי' חד ולא בחושבן כולא קמי' כלא חשיבי, כי מספר והגבלה לגבי בלי גבול ומספר אין ערוך לך וכלא חשיבי כו'. וע\"י העמקת הדעת היטב בבחי' התבוננות זו, עי\"ז יבוא לבחי' ואהבת שיהי' לו אהבה ותשוקה ליכלל בבחי' אוא\"ס ב\"ה. וז\"ע יצ\"מ לצאת מהמצרים וגבולים שבבחי' ההגבלה בחי' מספר ליכלל וליבטל באוא\"ס שבלי גבול כו'.\n<b>אך</b> אם רץ לבך שוב לאחד<sup data-n=\"915\">29</sup> הוא בחי' תומ\"צ כי שם תמצאנו, וכמ\"ש בק\"ש והיו הדברים האלה אשר אנכי מצוך וארז\"ל בדברי תורה הכתוב מדבר, והיינו שאם ע\"י ההתבוננות רץ לבך בבחי' אהבה ורצוא ליכלל באוא\"ס ב\"ה, שוב לאחד היינו בחי' התלבשות אוא\"ס בתומ\"צ שהם מצות הוי' ותורת הוי', וכמ\"ש למען תהי' תורת הוי' בפיך, והמצות הם מצותיו ב\"ה שהוא עצמו מקיימם כמארז\"ל הקב\"ה מניח תפילין הקב\"ה מתעטף בציצית וכמארז\"ל במד\"ר ר\"פ משפטים פ\"ל ע\"פ מגיד דבריו ליעקב חוקיו ומשפטיו, לא כמלך ב\"ו שמצוה לאחרים לעשות והוא אינו עושה, אבל הקב\"ה מה שהוא עושה אומר לישראל<sup data-n=\"916\">30</sup> לעשות, שזש\"ה מגיד דבריו כו' חוקיו ומשפטיו, פי' החוקים והמשפטים שעושה בעצמו כו'. ולהיות כי המצות והתורה הם תורת הוי' ומצותיו כו' לכן א\"א להתגלות למטה כ\"א בדברים גשמי' דוקא, וכידוע שכל הגבוה ביותר א\"א להיות נגלה כ\"א בדבר היותר גשמי<sup data-n=\"917\">31</sup>, וכמשל אותיות החותם שהם חקוקים על האבן טוב הנה מחמת רוב בהירות האבן טוב א\"א לקרות האותיות, משא\"כ כשחותמין אותם על השעוה או טיט אז יכולים לקרות האותיות. ועד\"מ זה יובן שהמצות להיותם בחי' רצון העליון ב\"ה א\"א להם להתלבש כ\"א בדברים גשמי' דוקא, ציצית בצמר הגשמי ותפילין בקלף גשמי וכן כל המצות. ולכן כשביקשו המלאכים שיותן להם התורה כמ\"ש תנה הודך על השמים לא ניתן להם להיות כי א\"א שיקיימו התורה כמו שניתנה למטה מפני שאין יצה\"ר ביניהם, ושיקיימו אותה ברוחניות א\"א לבחי' גבוה כזה להתלבש ברוחניות, כמשל האותיות שבהיותם חקוקים על האבן טוב מחמת בהירותם א\"א לקרוא",[["914","28","<b>שאמר ר\"י יכולני לשער כמה טיפות יש בים. . כמה טיפות יש ברביעית</b>: נת' בארוכה בסה\"מ תרפ\"א ע' שג. תרפ\"ד ע' שלח. תרצ\"ט ע' 244. שיחת חה\"פ תרצ\"ג (נקרא גם בשם ”מאמר הטבע\", ”קונטרס טבע ולמע' מן הטבע\") בתחילתו. רשימות חוב' קסו ע' 4 ואילך."],["915","29","<b>אם רץ לבך שוב לאחד</b>: ראה הערת כ\"ק אדמו\"ר בסה\"מ תרנ\"ט ע' ריג. וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460166\" data-slug=\"or-hatorah-hb\" data-id=\"8316460166\">אוה\"ת יתרו ע' תתקפא</a>. — בהבא להלן ראה גם לקו\"ת חוקת נז, א."],["916","30","<b>מגיד דבריו ליעקב. . מה שהוא עושה אומר לישראל</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370162\" data-slug=\"torah-or\" data-id=\"3901370162\">תו\"א מקץ לה, ב</a>-ג. סה\"מ תרכ\"ח ע' פז ואילך. תרכ\"ט ע' רכג. תרל\"ד ע' נג."],["917","31","<b>וכידוע שכל הגבוה ביותר. . נגלה. . בדבר היותר גשמי</b>: בהבא להלן ראה בארוכה אוה\"ת וארא ע' קסב ואילך (ושם ה' משלים לענין זה). שם ע' ריד. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381221\" data-slug=\"likkutei-torah\" data-id=\"4001381221\">לקו\"ת שה\"ש כג, א</a>. מאמרי אדה\"ז תקס\"ד ע' קכו. סידור עם דא\"ח עא, ד. שא, ג. תו\"ח ויצא כג, ד. שערי אורה שער הפורים נח, א-ב. שם פה, א ואילך. ועוד."]]],[2000510297,"אותם, או כמו שאין הראי' יכולה לתפוס הקול שהוא רוחני כ\"א מתלבש לראות דבר הגשמי דוקא<sup data-n=\"918\">32</sup> כנודע, והיינו מפני כי הראי' היא בחי' חכמה אינה יכולה להתגלות כ\"א שתתפוס דבר גשמי דוקא, משא\"כ בחי' השמיעה להיותה נמוך מן הראי' יכולה לתפוס גם הקול שהוא רוחני. ועד\"ז יובן בענין המצות שלהיותם גבוהים במדריגה שהם מצותיו ב\"ה לכן אינם יכולים להתלבש כ\"א בדבר גשמי דוקא.\n<b>וזהו</b> וארא אל אברהם כו' ושמי הוי' לא נודעתי להם, כי הגם שהאבות קיימו כל התורה כולה כמארז\"ל קיים אברהם כל התורה כולה אפי' עירוב תבשילין עד שלא ניתנה, אך הנה הם קיימו אותם ברוחניות לבד<sup data-n=\"919\">33</sup>, ולכן ארז\"ל במד\"ר שה\"ש ע\"פ לריח שמניך כל המצות שעשו האבות ריחות היו, אבל אנו שמן תורק שמך דבר שמריקין מכלי אל כלי, פי' ריחות שכמו הריח אינו עצם הדבר כ\"א הארה וריח מהדבר, כך קיום האבות שקיימו רק ברוחניות הוא הארה מהמצוה, כי עצם המצוה לעוצם רוממותה א\"א לה להתלבש כ\"א בגשמיות דוקא וכנ\"ל, אבל הם מאחר שקיימו את המצות ברוחניות זהו הוראה שאינה עצם המצוה כ\"א רק ריח המצוה לבד. וזהו שנגלה אליהם בש' שדי לבד ושמי הוי' לא נודעתי להם. וכדי שיהי' מ\"ת בקיום המצות בגשמיות הי' צריך להיות גילוי שם הוי' דוקא שהמצות הם מצות הוי' ותורה היא תורת הוי', וע\"י יצ\"מ הי' גילוי ש' הוי' כמ\"ש לכן אמור לבנ\"י אני הוי' והוצאתי אתכם כו' ואז אח\"כ הי' מ\"ת שניתנו המצות כמו שהם דבר שמריקין מכלי אל כלי פי' עצם המצוה ולכן נתלבשו מעשה המצות בגשמיות דוקא כו'.\n<b>ועפ\"ז</b> יובן ענין חוקת הפסח<sup data-n=\"920\">34</sup> כי הנה פסח הוא ל' דילוג כמ\"ש ופסח ה' על הפתח, והיינו שכדי שיתלבשו בחי' מצותיו ב\"ה במעשה גשמי' זהו בחי' דילוג שאינו בהדרגה, וחוקת הפסח היינו שהעבודה שיעשה חקיקה בנפשו שיוכל לקבל בחי' מצות הוי', וכמ\"ש באר חפרוה כו' במחקק כו' במחקק גימ' רמ\"ח<sup data-n=\"921\">35</sup> היינו בחי' רמ\"ח מ\"ע, וצריך לעשות חקיקה בנפשו שיהי' לו אהבה ורצוא ותשוקה שיהי' גילוי שם הוי' ע\"י עשיית המצות, ורוח אייתי רוח ואמשיך רוח להיות נמשך בחי' ש' הוי' ע\"י עשיית המצות שהם מצות הוי' כו'. וז\"ע שמברכין על כל מצוה ברוך אתה הוי', פי' ברוך שיתגלה בחי' ש' הוי' שציוה לנו לעשות מצוה זו, וזהו בחי' הכוונה של גשמיות עשיית המצוה כו'.",[["918","32","<b>הראי'. . מתלבש לראות דבר הגשמי דוקא</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370070\" data-slug=\"torah-or\" data-id=\"3901370070\">תו\"א וירא טו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380310\" data-slug=\"likkutei-torah\" data-id=\"4001380310\">לקו\"ת</a> הוספות לס' ויקרא נד, ג. סה\"מ תרכ\"ח ע' יב ואילך. תרכ\"ט ע' קפג. וע' ריד. המשך וככה תרל\"ז פל\"ג, פנ\"ז. לעיל ד\"ה וכל העם ע' קסז-ח."],["919","33","<b>שהאבות קיימו כל התורה כולה. . ברוחניות לבד</b>: ראה גם תו\"א ר\"פ יתרו סו, סע\"ב ואילך. סז, ד ואילך. עג, סע\"ג ואילך. מג\"א צו, ג ואילך. ובארוכה לעיל ד\"ה וכל העם ע' קסג. וש\"נ."],["920","34","<b>ועפי\"ז יובן ענין חוקת הפסח. . פסח הוא ל' דילוג</b>: בהבא להלן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830093\" data-slug=\"or-hatorah-hb\" data-id=\"8158830093\">אוה\"ת חקת ס\"ע תשעט</a>-פ."],["921","35","<b>וכמ\"ש באר חפרוה. . במחקק גימ' רמ\"ח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830105\" data-slug=\"or-hatorah-hb\" data-id=\"8158830105\">אוה\"ת חקת ע' תשצא</a>. לקמן ד\"ה כי ישאלך פ\"ב. ועוד."]]],[2000510298,"<b>ומעתה</b> יובן ענין חוקת הפרה<sup data-n=\"922\">36</sup> שבד\"כ ענין הפרה בעבודה היא כנגד בחי' בעלי תשובה<sup data-n=\"923\">37</sup>, שענין שריפת הפרה הוא בהיות ידוע שכל דבר מפרטי הנבראים הוא מורכב מד' יסודות איש רוח מים עפר, וכששורפין איזה דבר הנה ג' יסודות אש מים רוח יוצאים בעשן, ולא נשאר רק יסוד העפר<sup data-n=\"924\">38</sup> שנעשה ממנו אפר, וכמ\"ש בזהר דאפר הוא מאי דאשתייר מן נורא, וכך יובן בענין שריפת הפרה שבחי' ג' יסודות אש מים רוח שהיו בהפרה יוצאים בעשן ע\"י שריפתה ואפר הפרה הוא בחי' יסוד העפר שהי' בפרה, ונעשה מהעפר אפר מה דאשתאר מן נורא.\n<b>ולכאורה</b> צ\"ל מה\"ע שריפת הפרה ומהו המכוון במה שנעשה ממנה אפר. והענין הוא דהנה איתא בזהר פ' חוקת דק\"פ ע\"ב פרה דקבילת משמאלא<sup data-n=\"925\">39</sup>, מאן הוא לשמאלא פני שור כמד\"א ופני שור מהשמאל. והנה נודע שענין בחי' שור שבמרכבה הוא בחי' הרשפי אש והתשוקה בתגבורת גדול ליכלל וליבטל באוא\"ס ב\"ה, אמנם הנה בהשתלשלות מה שנשתלשל מבחי' פני שור בריבוי ההשתל' נשתלשל הנה\"ב שבאדם<sup data-n=\"926\">40</sup> שהוא כח המתאוה לעניני העוה\"ז בדברים המותרים, ובהשתלשלות עוד יוכל להתאוות גם דברים האסורים ח\"ו. והנה כשהאדם חושק לאיזה דבר מתענוגי עוה\"ז הנה החשק הוא רק כלי להרצון והכח המתאוה, וכן המח' והדבור שמדבר ומהרהר איך למלאות תאוות לבו הוא רק כלי ולבוש לעצם כח המתאוה, וכ\"ש המעשה היא הכלי וגמר התאוה, אך הנה עצם כח המתאוה אינו רע עדיין כלל<sup data-n=\"927\">41</sup> רק שמתלבש בלבושים רעים שההרהור והדבור והמעשה של תאוות היתר הוא בחי' הרע דק\"נ, ושל תאוות איסור ח\"ו הוא מגקה\"ט, אבל עצם כח המתאוה אינו רע עדיין כלל שהרי בחי' התאוה זו עצמה יוכל להפכה לטוב, היינו שיתאוה לקיים ציווי הקב\"ה במעשה המצות בבחי' רצון וחפץ גמור כמו שהוא מתאוה תאוות היתר או איסור ח\"ו רק שהוא בשוגג, או בזדון לבו ח\"ו מלבישו להתאוות תאוות היתר או איסור ח\"ו, שהוא מלבישו בלבושים צואים, או שזהו כמו צורה לחומר, שעצם כח המתאוה הוא בחי' חומר עדיין ויכולים לציירה בציור טוב שיתאוה לקיים רצון העליון ב\"ה ולדבקה בו ית', וכמ\"ש נפשי אויתיך כו' שכמו",[["922","36","<b>ומעתה יובן ענין חקת הפרה</b>: בהבא להלן [עד פיסקא ”וע\"י העלאה זו\"] ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חקת נו, ג</a>-ד. אוה\"ת חקת ס\"ע תשפא. — בהבא להלן עד סוף המאמר ראה בארוכה ד\"ה זאת חוקת בסה\"מ תרכ\"ט ע' רס ואילך."],["923","37","<b>ענין הפרה. . כנגד בחי' בעלי תשובה</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830111\" data-slug=\"or-hatorah-hb\" data-id=\"8158830111\">אוה\"ת חקת ס\"ע תשצז</a> ואילך. שם בהוספות (הוצאת תשנ\"ח) ס\"ע 14 ואילך. וראה גם לקו\"ת חקת סא, רע\"ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830014\" data-slug=\"or-hatorah-hb\" data-id=\"8158830014\">אוה\"ת חקת שם ע' תשעג</a>. לקו\"ש חל\"ו ע' 209 ואילך."],["924","38","<b>ג' יסודות. . יוצאים בעשן ולא נשאר רק יסוד העפר</b>: ראה בכ\"ז אגה\"ק סי' טו (קכא, ב). ובכ\"מ."],["925","39","<b>פרה דקבילת משמאלא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חקת שם נו, ג</a>. ביאוה\"ז לאדהאמ\"צ צו, ד ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830094\" data-slug=\"or-hatorah-hb\" data-id=\"8158830094\">אוה\"ת חקת ע' תשפ</a>. ובכ\"מ."],["926","40","<b>מבחי' פני שור. . נשתלשל הנה\"ב שבאדם</b>: ראה מאמרי אדה\"ז תקע\"א ע' קעח. סה\"מ תרל\"ב ח\"א ע' רפה. וש\"נ."],["927","41","<b>עצם כח המתאוה אינו רע עדיין כלל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380964\" data-slug=\"likkutei-torah\" data-id=\"4001380964\">לקו\"ת</a> חקת שם. וראה גם לקו\"ת דרושים לר\"ה סא, ב. לקמן ע' רל-לא. וראה קונ' העבודה פ\"ג (ע' 32): מ\"ש בכ\"ד שהכח המתאווה בעצם אינו רע זהו רק שאין בו ציור רע בעצם, אבל מ\"מ אינו טוב, ואדרבא בטבעו הוא נמשך לענינים חומריים."]]],[2000510299,"שהאדם אוהב חיי נפשו<sup data-n=\"928\">42</sup> כמו\"כ יהי' בבחי' אהבה לה' כו', כי באמת כח המתאוה מצד עצמו יסודתו בהררי קדש בחי' פני שור שבמרכבה כו', אבל אם בשגיאתו או בזדון ח\"ו מצייר בה צורה להתאוות בבחי' כח המתאוה הטבעי איזה דברים מתאוות היתר שבעוה\"ז, וכ\"ש בתאוות איסור ח\"ו שצייר בחומר צורה רעה עד שמתאווה לדבר רע שנמשך מגקה\"ט כו', ולכן כשישוב אל ה' באמת יכול להפוך מן הקצה אל הקצה שגם כח המתאוה שהי' מלובש בתאוה רעה ישוב לאהבה את ה' כמו שהוא בשרש שרשה בחי' פני שור שבמרכבה. אבל בחי' לבושי כח המתאוה או הציור של כח המתאוה מאחר שהוא בעצם רע דנוגה או רע גמור דגקה\"ט א\"א להעלותה שיוכלל בקדושה ואין להם תקנה אלא ביטולם והעברתם מן העולם ושבירתם זהו תקנתם.\n<b>וזה\"ע</b> שריפת הפרה ששרפו עורה ובשרה ופרשה ויצא בחי' ג' יסודות אש מים רוח שהי' בה בעשן, ולא נשאר רק האפר והיינו בחי' יסוד העפר, והיינו כי הכל הי' מן העפר<sup data-n=\"929\">43</sup> אפי' גלגל חמה, וכמו\"כ יובן בהפרה שהעיקר שבה הוא יסוד העפר רק שהי' מורכבת עוד בג' יסודות אש מים רוח, והם עשו צורה בבחי' העפר אשר בפרה שתהי' צורתה בבחי' בע\"ח בציור פרה, וכששורפין אותה מבטלים בחי' הצורה או הלבושים שלה ולא נשאר רק העצם שהוא העפר ונעשה ממנה אפר והוא בחי' העצם של הפרה. ובעבודה ענין שריפת הפרה הוא בחי' ביטול לבושי כח המתאוה דנה\"ב או ציור כח המתאוה של הנה\"ב, שלא ישאר רק עצם המדות דנה\"ב שהוא כח המתאוה בעצם, שהוא אינו רע כלל ויכולים להפכו שיהי' מתאוה לדבקה בו ית' ובמצותיו, וכמ\"ש ואהבת כו' בכל לבבך וארז\"ל בשני יצריך ביצ\"ט וביצה\"ר שגם היצה\"ר ישוב לאהבת ה', והיינו שמבחי' אתכפי' יבוא לבחי' אתהפכא מחשוכא לנהורא להיות אהבת ה' תקוע בלבו בכל לבבך בשני יצריך, וזהו שמע שם ע', שם הוא בחי' ב\"ן ורפ\"ח, כמ\"ש בפע\"ח ב\"ן ורפ\"ח בגימ' שם שמתעלין לשרשן בחי' עי\"ן ז\"ת דס\"ג<sup data-n=\"930\">44</sup>, והיינו ע\"י אתכפייא ואתהפכא.\n<b>וע\"י</b> העלאה זו נמשך<sup data-n=\"931\">45</sup> אח\"כ בחי' מים חיים כמ\"ש ונתן עליו מים חיים אל כלי, והיינו שהמים חיים הם שנובעים מתחת לארץ וע\"י שחופרין מוציאין מהעלם אל הגילוי בחי' מים חיים. ועד\"ז יובן שהוא ית' הוא מקור מים חיים כמ\"ש אותי עזבו מקור מים חיים את הוי', וע\"י העלאת הפרה שהיא בחי' תשובה נמשך מבחי' מקור מים חיים שזהו למעלה מבחי' חוקת הפסח כו'. שהגם שנת' לעיל שבחי' המצות הם בחי' מצות הוי' ששם הוי' הוא בחי' הי' הוה ויהי' כו' שלמעלה מבחי' מספר וכנ\"ל, מ\"מ גם על ש' הוי' נאמר אני הוי' הוא שמי שגם שם הוי' הוא רק שם והארה בעלמא, וכמו שאין השם נוגע לעצמותו כלל ואינו נצרך לעצמו כ\"א לזולתו שיקראנו בשמו כו', כמו\"כ בענין ש' הוי' שהוא רק שם והארה בעלמא, ולכן כתי' אנכי הוי' אלקיך שבכדי שיהי' נמשך מבחי' אנכי מי שאנכי להיות ש'",[["928","42","<b>וכמ\"ש נפשי אויתיך. . שכמו שהאדם אוהב חיי נפשו</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ\"ד (סג, א</a>)."],["929","43","<b>ולא נשאר רק האפר. . הכל הי' מן העפר</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חקת נו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380550\" data-slug=\"likkutei-torah\" data-id=\"4001380550\">נח, סע\"ג</a>."],["930","44","<b>שמע שם ע'. . עי\"ן ז\"ת דס\"ג</b>: ראה גם לקו\"ת חקת שם נו, סע\"ד. ד\"ה אם בחוקותי תרכ\"ו ותר\"ל. ועוד."],["931","45","<b>וע\"י העלאה זו נמשך</b>: בהבא להלן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380544\" data-slug=\"likkutei-torah\" data-id=\"4001380544\">לקו\"ת חקת שם נז, א</a>."]]],[2000510300,"הוי' זהו ע\"י אלקיך בחי' צמצום וגבורה כו', ולכן שם הוי' מתחיל ביו\"ד בחי' צמצום כו'. וע\"י העלאת חוקת הפרה נמשך מבחי' מקור מים חיים היינו בחי' מקור ושרש ש' הוי', והיינו כמארז\"ל בפרדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד והיינו בחי' ש' הוי' כמו שהוא כלול בעצמותו שזהו בחי' ש' הוי' דלעילא, שמשם יומשך למלאות כל הפגמי'<sup data-n=\"932\">46</sup> שפגמו בשם הוי', דהנה רמ\"ח מ\"ע הם מבחי' ו\"ה ושס\"ה מל\"ת הם מבחי' י\"ה כמארז\"ל שמי עם י\"ה שס\"ה<sup data-n=\"933\">47</sup> וזכרי עם ו\"ה רמ\"ח, גם מצוה הוא בחי' אותיות הוי' כי מ\"צ בא\"ת ב\"ש י\"ה<sup data-n=\"934\">48</sup>, ולכן בפגם המצות אומרים בק\"ש שעל המטה אם פגמתי באות יו\"ד של שמך הגדול בביטול ק\"ש כו', שפגם המצות הוא בשם הוי'<sup data-n=\"935\">49</sup>, וע\"י התשובה שהוא בחי' אפר הפרה עי\"ז נמשך בחי' מים חיים שהוא בחי' מקור מים חיים מקור ושרש ש' הוי' בחי' ש' הוי' דלעילא להיות ממעמקים בחי' עומקא דכולא קראתיך להיות נמשך ש' הוי' מחדש כו'. ולכן נא' ב\"פ ש' הוי' בחקת הפרה, א' נגד ש' הוי' שבבחי' מצות הוי', והב' בחי' ש' הוי' דלעילא בחי' מקור ושרש בחי' ש' הוי' שבכל מעשה המצות כו'.\n<b>ועפ\"ז</b> יובן ל' המד\"ר משל לשתי מטרונות דומות וא\"י איזה מהם גדולה, פי' ל' גדולה דהנה כתי' גדול הוי' כו' ולגדולתו אין חקר<sup data-n=\"936\">50</sup>, ונת' לעיל שענין חוקת הפסח שנמשך גילוי ש' הוי' שנק' גדול כמ\"ש גדול ה' כו' לפי שהוא בחי' בלי מספר כו'. ולגדולתו אין חקר קאי על חוקת הפרה שלגדולתו העצמי' אין חקר והיינו בחי' ש' הוי' דלעילא. אך לפ\"ז אינו מובן מהו שאמרו וא\"י איזה מהם גדולה. הענין הוא שמטרונא היא בחי' מל' כנודע, ושתי מטרונות היינו בחי' מל' דאצי' ומל' דבינה וזהו שא' דומות היינו ששניהם הם בחי' מל', ומה שמסופק איזהו מהם גדולה היינו לפי שלע\"ל יתעלה בחי' מל' ה' עליות כמ\"ש ישכיל עבדי<sup data-n=\"937\">51</sup> ירום ונשא וגבה מאד, ולפ\"ז יתעלה המל' למעלה ממקום הבינה, ולכן לע\"ל כתי'<sup data-n=\"938\">52</sup> והי' ביום",[["932","46","<b>שם הוי' דלעילא. . למלאות כל הפגמים</b>: בהבא להלן (עד סוף הפיסקא) ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380955\" data-slug=\"likkutei-torah\" data-id=\"4001380955\">לקו\"ת</a> דרושים לר\"ה נט, א. ובכ\"מ."],["933","47","<b>רמ\"ח מ\"ע. . ו\"ה ושס\"ה מל\"ת. . י\"ה כמארז\"ל שמי עם י\"ה שס\"ה</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370311\" data-slug=\"torah-or\" data-id=\"3901370311\">תו\"א יתרו סט, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380053\" data-slug=\"likkutei-torah\" data-id=\"4001380053\">לקו\"ת פקודי ג, ב</a>. ואילך. סה\"מ תרכ\"ז ע' קכו. וע' קכט ואילך. ובכ\"מ."],["934","48","<b>מצוה. . אותיות הוי'. . מ\"צ בא\"ת ב\"ש י\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380220\" data-slug=\"likkutei-torah\" data-id=\"4001380220\">לקו\"ת אמור לג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380496\" data-slug=\"likkutei-torah\" data-id=\"4001380496\">שלח מו, א</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' כז. תקס\"ז ע' רכו. ועוד."],["935","49","<b>אומרים בק\"ש שעל המטה אם פגמתי באות יו\"ד. . שפגם המצות הוא בשם הוי'</b>: ראה בארוכה לקו\"ת דרושים לשבת שובה סד, ד. מאמרי אדהאמ\"צ דברים ח\"ג ע' א'פב ואילך. [ובהנסמן שם בס\"ע א'פא]. סה\"מ תרס\"ה ע' לג ואילך. תרפ\"ג ע' קטז ואילך. תש\"ז ע' 161 ואילך."],["936","50","<b>פי' ל' גדולה. . גדול הוי' כו' ולגדולתו אין חקר</b>: ראה בכ\"ז יהל אור להצ\"צ עה\"פ ע' תקמז ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370423\" data-slug=\"torah-or\" data-id=\"3901370423\">תו\"א מג\"א צד, ב</a>."],["937","51","<b>שלע\"ל יתעלה בחי' מל' ה' עליות. . ישכיל עבדי</b>: ראה ביאוה\"ז לאדהאמ\"צ כג, א ואילך. סה\"מ תרל\"ה ח\"א ס\"ע רסה ואילך [ובהמ\"מ שם]. ובכ\"מ."],["938","52","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830088\" data-slug=\"or-hatorah-hb\" data-id=\"8158830088\">ולכן לע\"ל</a> כתיב</b>: ראה אוה\"ת חקת ע' תשעד. בשולי הגליון בס' תרכ\"ט נרשם כאן בגוכי\"ק: לע\"ל כשיהי' ואת רוח הטומאה, אזי יהי' המל' גבוה יותר ויצאו מ\"ח מירושלים אל הים הקדמוני, ולא יצטרכו למי חטאת לטהר הטמאים כי את רוח הטומאה יעביר כו', אבל עכשיו אוכלי פסח צריכים לפרה בכדי לטהר את הטמאים שיוכלו לעשות הפסח. [וראה לקו\"ת חל\"ו שם ע' 211 הע' 64]."]]],[2000510301,"ההוא יצאו מים חיים מירושלים אל הים הקדמוני, פי' ים הקדמוני הוא בחי' חכ', ולע\"ל יצאו מים חיים מירושלים בחי' מל' אל החכמה או הבינה, ולכן יתכן שאלתו וא\"י איזהו מהם גדולה, אך מ\"מ חוקת הפרה גדולה הימנו שלע\"ע בחי' חוקת הפרה היא מל' דבינה שגבוה מחוקת הפסח מל' דאצי'.\n<b>ושורש</b> ההפרש בין פסח לפרה, דהנה הפסח הי' ביצ\"מ, ופרה הוא כנגד הגאולה דלע\"ל שבפרה מרומז ד' גליות כמארז\"ל אדומה זו בבל תמימה זו מדי כו'. והענין הוא דהנה גלות מצרים הי' הקדמה למ\"ת, שע\"י שנצרפו בכור הברזל במצרים זכו לקבל התורה שנק' תורת הוי' כו', אך מ\"מ זהו רק חיצוניות התורה שנמשך מבחי' ש' הוי' דלתתא. אבל ע\"י פרה שהיא בחי' תשובה עי\"ז יהי' הגאולה דלעתיד כמארז\"ל אם ישראל עושין תשובה נגאלים, שהגאולה דלעתיד תלוי בתשובה דוקא, ועי\"ז יהי' התגלות בחי' פנימיות התורה ששרשה מבחי' ש' הוי' דלעילא.\n<b>וזהו</b> יהי לבי תמים בחוקיך ב' חוקים חוקת הפסח וחוקת הפרה, כי באמת צ\"ל ב' הבחי' והיינו חוקת הפסח הוא בחי' תומ\"צ וחוקת הפרה היא בחי' תשובה, כי תשובה אינה על עבירות דוקא<sup data-n=\"939\">53</sup>, כ\"א תשובה הוא בחי' החזרת פנים בפנים, דהנה שני אנשים הגם שעומדים סמוכים זל\"ז אך הם עומדים אחור באחור הנה הם רחוקים זמ\"ז, אבל כשהם מחזירים פנים בפנים אז הם קרובים. ועד\"ז יובן בעבודת ה' דהגם שמקיים התומ\"צ שאז הוא קרוב, מ\"מ כשהוא בבחי' אחור באחור דהיינו שאין לו בחי' אהבה ותשוקה בקיום המצות רק שהוא עושה בבחי' מצות אנשים מלומדה אזי הוא רחוק באמת, וצ\"ל בחי' תשובה ע\"ז היינו החזרת פב\"פ, ולכן איתא בזהר שמשיח אתא לאתבא צדיקייא בתיובתא<sup data-n=\"940\">54</sup>, שגם הצדיקים שמקיימים התורה והמצות מ\"מ צריכים לבחי' תשובה<sup data-n=\"941\">55</sup>, והיינו להיות החזרת פב\"פ, שלפום גמלא שיחנא, שלפי ערך מדריגת הצדיק התשוקה עדיין אינה כדבעי לכן צריך תשובה ע\"ז, וזהו שאמר דוד יהי לבי תמים בחוקיך ב' החוקים דוקא כו'.\n<b>ועפ\"ז</b> יתורץ ג\"כ מה שהקשינו ממארז\"ל ע\"פ אורח חיים פן תפלס לא תהא יושב ושוקל מצוותי' של תורה, דשם הכוונה שלא יאמר אדם אעשה זו ששכרה גדול, לכן הודיע הקב\"ה ששכר מצוה קלה שוה לשכר מצוה חמורה. אבל כאן פי' שפרה גדולה להיותה במעלה ומדריגה גבוה לע\"ע, ואוכלי פסח צריכין לפרה כי גם הצדיקים צריכים לעשות תשובה כנ\"ל לכן אינו ענין לשיקול מצותי' של תורה כו'.",[["939","53","<b>תשובה אינה על עבירות דוקא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380962\" data-slug=\"likkutei-torah\" data-id=\"4001380962\">לקו\"ת</a> דרושים לר\"ה ס, ד ואילך. ובארוכה סה\"מ תרצ\"ז ע' 235. וש\"נ."],["940","54","<b>שמשיח אתא לאתבא צדיקייא בתיובתא</b>: ראה בארוכה ס' מאמרי אדה\"ז תקס\"ב ח\"ב ע' תקלד, וע' תקמב. מאמרי אדהאמ\"צ קונטרסים ע' רפא ואילך. ביאורי הזהר להצ\"צ ח\"ב ע' תתרמז. המשך תער\"ב ח\"ג ע' א'שו ואילך. סה\"מ תשי\"א-י\"ג ע' 46 ואילך."],["941","55","<b>באמת צ\"ל ב' הבחי'. . שגם הצדיקים. . צריכים לבחי' תשובה</b>: הבא לקמן נת' ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191223\" data-slug=\"likkutei-sichot\" data-id=\"1300191223\">לקו\"ש</a> חל\"ו שם ע' 210 ואילך."]]],[2000510302,"<h3>לא תבערו אש כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ ויק\"פ, ל\"א).</b>\nאש אוכלה ה\"פ\nויקהל פקודי\n<b>לא</b> תבערו אש<sup data-n=\"942\">1</sup> בכל מושבותיכם ביום השבת, וצ\"ל למה הזהיר בהבערת האש יותר מכל המלאכות, ופי' בשל\"ה<sup data-n=\"943\">2</sup> במס' שבת דקל\"ו ע\"ב, להיות כי מאמר הראשון של הבריאה הוא מאמר יהי אור, ובו נכללו כל המאמרות, והוא הראש והשורש להם, ועז\"נ כי ה' אלקיך אש אוכלה הוא בסוד השלהבת הקשורה בגחלת, ע\"כ אמרה תורה לא תבערו אש, והוא כאילו אמר לא תעשה מלאכה סתם כי בריאות אור האש כולל כל מע\"ב. ולהבין זה צ\"ל שורש ענין האש ומוצאו שהוא הצור שממנו יוצא האש, שהוא המקור לכל הדברים, שלכן משה כשהי' צריך להמשיך יגמה\"ר אמר לו הקב\"ה ושמתיך בנקרת הצור שהוא בבחי' תוכן פנימיות נקודת הצור שממנו מקור האש היוצא בפועל כו'.\n<b>וביאור</b> הענין יובן בהקדם שורש ענין ההפרש שבין צדיקים לבעלי תשובה<sup data-n=\"944\">3</sup> שארז\"ל במקום שבעלי תשובה עומדים צדיקים גמורים אין יכולים לעמוד שם. שלכאורה יפלא הלא צדיקים גמורים עובדים את ה' כל ימי חייהם, בדחילא ורחימא שכלי' וטבעים ומקיימים תומ\"צ כל ימיהם, ולמה יגרע מעלתם עד שבמקום הבע\"ת אין יכולים לעמוד שם, וכי יציבא בארעא וגיורא בשמי שמי'. אמנם הנה נודע התירוץ ע\"ז הוא להיות כי הבע\"ת משכין לי' בחילא יתיר<sup data-n=\"945\">4</sup>, והיינו",[["942","1","<b>לא תבערו אש</b>: הוא ד\"ה כי ביום הזה יכפר וד\"ה השיבנו ה' אליך מש\"פ האזינו תרל\"א בסה\"מ תר\"ל ע' שט ואילך. וע' שיד ואילך. [וראה גם ד\"ה כי ביום הזה יכפר בכת\"י 1063 שסא, א]. וכאן הוא בשינויים קלים ובשינוי ההתחלה וסיום.\nמאמר זה (מלבד ההתחלה והסיום) מיוסד על ד\"ה כי ביום הזה יכפר בס' מאמרי אדה\"ז תקס\"ב ח\"א ע' א ואילך. ונו\"א ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380186\" data-slug=\"likkutei-torah\" data-id=\"4001380186\">לקו\"ת אחרי כה, ג</a> ואילך. ובתוס' הגהות באוה\"ת דרושים ליוהכ\"פ (כרך ה) ע' ב'קכח ואילך. וראה תוכן המאמר בשינויים בד\"ה החודש הזה בסה\"מ תרל\"ה ח\"א ע' סד ואילך. תרע\"ח ס\"ע קנב ואילך.\nהתחלת וסיום המאמר מיוסד על ד\"ה לא תבערו אש (סעי' ו) באוה\"ת ויקהל ע' ב'קמח. [ושם כותב הצ\"צ: ואפשר להעיר ממ\"ש בד\"ה כי ביום הזה יכפר].\nמאמר זה נמצא גם בד\"ה זה בס' תרמ\"ב. ובשינויים והוספות בד\"ה בורא ניב שפתים בסה\"מ תרח\"צ ע' מז ואילך. ד\"ה כי חלק ה' עמו בסה\"מ תרצ\"ט ע' 40 ואילך. ד\"ה זאת חוקת בסה\"מ תשכ\"א ע' 296 ואילך. ד\"ה כי תשא בסה\"מ תשכ\"ב ע' קסה ואילך. וראה גם ד\"ה בורא ניב שפתים בסה\"מ תשמ\"ח (הוצאת תשס\"ב) ע' 254. שם ע' 485-484."],["943","2","<b>ופי' בשל\"ה</b>: הובא ונת' באוה\"ת ויקהל שם ע' ב'קמח. ובד\"ה זאת חוקת תשכ\"א שם. עיי\"ש. וראה אוה\"ת ויקהל שם ע' ב'קנ: בבחיי פ' ויקהל (קכ\"ו א') הזהיר לדורות לא תבערו אש כו' כאילו אמר לא תעשו כל מלאכה כו' שרוב המלאכות כו' אינם אלא ע\"י האש כו', שהאש תחילת המלאכות במעשה בראשית וכענין שכתוב ביום ראשון ויהי אור עכ\"ל [הבחיי], ודבריו כעין מ\"ש בשל\"ה דלעיל, ונראה שהשל\"ה הוציא דברים הנ\"ל ממנו, והרחיבם בביאור נכון."],["944","3","<b>וביאור הענין יובן בהקדם שורש ענין ההפרש שבין צדיקים לבעלי תשובה</b>: בהבא לקמן ראה בהדרושים ד\"ה כי ביום הזה יכפר במאמרי אדה\"ז תקס\"ב שם, לקו\"ת אחרי שם ואוה\"ת דרושים ליוהכ\"פ שם. בכ\"ז ראה גם לעיל ד\"ה מי יתנך ע' קטו ואילך."],["945","4","<b>נודע התירוץ ע\"ז. . כי הבע\"ת משכין לי' בחילא יתיר</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ה ח\"א ע' תצד ואילך. תקב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770289\" data-slug=\"or-hatorah-hb\" data-id=\"8316770289\">אוה\"ת שה\"ש (כרך ב) ע' תרנז</a> ואילך. תרפה ואילך. תרפח. תרחצ ואילך. סה\"מ תרכ\"ו ס\"ע קט ואילך."]]],[2000510303,"כי ענין הילוך הצדיקים הוא מדרגא לדרגא כמ\"ש באברהם הלוך ונסוע הנגבה, אמנם הבע\"ת להיות אשר נתרחקו מאלקותו ית' ע\"י מעשיהם אשר לא טובים צ\"ל תשובתם בחילא יתיר. עכ\"ז עדיין אינו מתורץ שהרי זהו טעם למה הבע\"ת צריכים להיות בחילא יתיר, אבל מפני מה נגרע כח הצדיקים שלא נתרחקו כלל.\n<b>ויובן</b> בהקדם ענין התשובה, דהנה ענין תשובה להשיב הנפש למקורה ושרשה למקום אשר נלקחה משם, כי שרש הנשמה נלקחה מבחי' גבוה מאד נעלה כמ\"ש בזהר ע\"פ ויפח באפיו נשמת חיים מאן דנפח מתוכו נפח<sup data-n=\"946\">5</sup>, פי' מתוכו ומפנימיותו כמו עד\"מ אדם שמנפח הוא מוציא ההבל מפנימיות הלב שפנימיות החיות של האדם מוציא בשפתיו בנפחו בכח מהבל הלב, אלא שאח\"כ נעשה ההבל בחי' נפרד לעצמו, וכמ\"כ שרש הנשמה נלקחה מפנימיות הארת אא\"ס, ואח\"כ נשתלשלו וירדו במדריגה אחר מדריגה עד שנעשו בחי' יש ודבר נפרד ע\"י התלבשותה בגוף ונה\"ב. וזהו בחי' תשובה להשיב הנפש למקורה ושרשה אל עצמות אא\"ס כו'.\nב) <b>והנה</b> להבין זה צ\"ל מקודם בחי' ומדרגת הצדיקים, הנה כתיב כל הנק' בשמי ולכבודי בראתיו יצרתיו אף עשיתיו, והגם כי נודע שיש ריבוי רבבות עולמות וכנודע ממארז\"ל ע\"פ ילכו מחיל אל חיל כו', אך כללות העולמות נכללים בג' עולמות אלו והם כנגד ג' בחי' מחשבה ודבור ומעשה<sup data-n=\"947\">6</sup>. והנה באדם שנעשה בצלם ודמות יש בו ג\"כ כל ג' בחי' אלו מחדומ\"ע, כי בריאה היא בחי' מחשבה כי אותיות המחשבה הוא יש מאין, כמו\"כ הבריאה היא בחי' יש מאין, כי אצי' נק' אין לגבי בריאה. ויצי' נק' בחי' דבור שהוא בחי' העלם וגילוי שהוא יש מיש, כי מה שהוא מחשב הוא מדבר ואין כאן שום התחדשות, רק שבמחשבה הוא בהעלם ובדבור הוא בא מהעלם אל הגילוי, וזהו יוצר אור ובורא חשך כי יצי' נק' אור שהוא גילוי ההעלם עלמין דאתגליין, ובריאה נק' חשך<sup data-n=\"948\">7</sup> שהוא ההעלם בחי' מח' עלמין סתימין דלא אתגליין. ועולם העשי' כנגדה באדם הוא בחי' המעשה. וכדי שיהי' ג' עולמות אלו בי\"ע עז\"נ כל הנק' בשמי ולכבודי, ואין כבוד אלא תורה שע\"י התורה הוא התחברות אא\"ס בג' עולמות בי\"ע. כי הנה כתיב כי הוי' אלקיך אש אוכלה הוא, וצ\"ל למה מדמין אותו לאש<sup data-n=\"949\">8</sup>, כי הנה יש ד' יסודות ארמ\"ע, והנה",[["946","5","<b>כמ\"ש בזהר ע\"פ ויפח באפיו. . מאן דנפח מתוכו נפח</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב (ו, א</a>). <a class=\"ft-cite\" href=\"#/read/tanya/3401310075\" data-slug=\"tanya\" data-id=\"3401310075\">אגה\"ת פ\"ד (צג, סע\"ב</a> ואילך). ובארוכה לעיל ד\"ה ויחי ע' קכג ואילך. וש\"נ."],["947","6","<b>בראתיו יצרתיו אף עשיתיו. . מחשבה ודבור ומעשה</b>: ראה בכ\"ז [נוסף להנסמן לעיל בתחילת המאמר] <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת בלק סז, א</a> ואילך. וראה גם סה\"מ תרפ\"ג ע' קעט. תש\"י ע' 122. ועוד."],["948","7","<b>וזהו יוצר אור ובורא חשך. . יצי' נק' אור. . ובריאה נק' חשך</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381147\" data-slug=\"likkutei-torah\" data-id=\"4001381147\">לקו\"ת</a> דרושים ליוהכ\"פ סט, ב. שה\"ש ד, סע\"ג. מב, ד. ובכ\"מ."],["949","8","<b>כי הוי' אלקיך אש אוכלה. . מדמין אותו לאש</b>: בהבא לקמן ראה [נוסף לדרושים שנסמנו לעיל בתחילת המאמר] <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א מג\"א צז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380897\" data-slug=\"likkutei-torah\" data-id=\"4001380897\">לקו\"ת נצבים מד, ג</a>. סה\"מ תרל\"ה ח\"א ע' סד ואילך. תרע\"ח ס\"ע קנב ואילך. — בהבא לקמן ראה בשינויים לקמן ד\"ה וסמך ידו."]]],[2000510304,"אנו רואים טבע האש חלוק מכל היסודות כי טבע המים לירד למטה, אבל טבע האש לעלות למעלה<sup data-n=\"950\">9</sup>, וגם בעצם אין לו התחברות עם היסודות כ\"א ע\"י דבר שנאחז בהם האש. ובזה יובן מה שנדמה הקב\"ה בכתוב לאש, כי הנה כתיב אין ערוך אליך שכל העולמות אין ערך לגבי הקב\"ה כלל וכלל, שכל העולמות הם נבראים ובע\"ג והוא בלתי בע\"ג, ואין ערך בע\"ג לבלתי בע\"ג, כי בבחי' גבול ומספר שייך ערך כמו למשל א' לגבי אלפים ורבוא רבבות<sup data-n=\"951\">10</sup>, והיינו לפי שהם בבחי' גבול ומספר לכן יש ערך ביניהם, אבל לגבי הקב\"ה אין ערוך אליו כי הוא בלתי בע\"ג ולפניו שוין א' ורבוא רבבות כי זה בחי' גבול והוא בחי' בלתי בע\"ג. ולכן אמרו בזהר על עשרה מאמרות שורש ומקור כל התהוות העולמות לאו אורחא דמלכא לאשתעי במילין דהדיוטא כי שרש ומקור כל התהוות העולמות נקראים מילין דהדיוטא לגבי אא\"ס כי כל שרש התהוותן הוא רק מבחי' זיו והארה בעלמא שאינו נוגע כלל כמ\"ש במ\"א<sup data-n=\"952\">11</sup>, ולכן אין ערוך לגבי הקב\"ה. וע\"כ לא נמצא משל אחר לדמות אותו לבריותיו ית' שברא אלא לבחי' אש והיינו שכמו האש אין לו התחברות עם הד' יסודות כמו\"כ אין לאא\"ס ערך עם העולמות כלל. וכדי שלא יסתלק למעלה ויהיו העולמות בטלים וכמ\"ש בת\"ז וכד אנת תסתלק מנייהו כו', לכן צריכים לעשות כלים שיומשך בהם המשכת אוא\"ס, וה\"ז ג\"כ כמשל האש שאע\"פ שטבעו לעלות למעלה מ\"מ אם יש כלי במה להיות נאחז בו האש כמו בפתילה או עצים מתאחז האש, כך ע\"י הכלים שאנו עושים עי\"ז נמשך ומתאחז בחי' אוא\"ס ב\"ה כו'. אך בתחלת הבריאה הי' זה מעצמו מחמת כי חפץ חסד הוא, אבל עתה באתדל\"ת תליא מילתא. וזהו כל הנק' בשמי ולכבודי בראתיו אין כבוד אלא תורה, שע\"י התורה בכלל נמשך המשכת אוא\"ס בג' עולמות בי\"ע.\n<b>ובדרך</b> פרט הם ג' מדרגות תורה ועבודה וגמ\"ח והוא כנגד בי\"ע מחשבה דבור ומעשה<sup data-n=\"953\">12</sup>, עבודה הוא בחי' עבודת הקרבנות היא בחי' מח', כי הרי מחשבה פוסל הקרבן, כמו מחשבת חוץ לזמנו וחוץ למקומו, וגם עבודת כהן הי' בחשאי וברעו\"ד. והנה גם עכשיו תפלה כנגד קרבנות, ועיקר התפלה היא מחשבה כי תפלה בלא כוונה כגוף בלא נשמה, והגם שצ\"ל בדבור זהו רק כדי לעורר הכוונה",[["950","9","<b>טבע האש חלוק מכל היסודות. . לעלות למעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט (כד, רע\"ב</a>). ובארוכה מאמרי אדה\"ז תקס\"ט ע' רכו ואילך. המשך מים רבים תרל\"ו ס\"ע קט-י. ועוד."],["951","10","<b>בבחי' גבול ומספר שייך ערך. . א' לגבי אלפים ורבוא רבבות</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח (סז, ב</a>). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380228\" data-slug=\"likkutei-torah\" data-id=\"4001380228\">לקו\"ת אמור לה, רע\"ג</a>. מאמרי אדהאמ\"צ דברים ח\"ג ע' תתצג. וש\"נ."],["952","11","<b>שרש ומקור כל התהוות העולמות נקראים מילין דהדיוטא. . זיו והארה שאינו נוגע כלל כמ\"ש במ\"א</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">לקו\"ת אחרי שם כה, ד</a>. אוה\"ת יתרו (כרך ז) ס\"ע ב'תרצ ואילך. סה\"מ תרל\"ה ח\"א ע' קיז ואילך. תרמ\"ג ס\"ע קא ואילך. לעיל ד\"ה ולקחתם אגודת אזוב ע' קמה ואילך."],["953","12","<b>ובדרך פרט הם ג' מדרגות תורה ועבודה וגמ\"ח. . בי\"ע מחשבה דבור ומעשה</b>: ראה ד\"ה זאת חוקת תשכ\"א שם: דכמו שההמשכה הוא בתלת עלמין בי\"ע, הנה כמו\"כ גם בישראל שבשבילם הו\"ע ההתהוות כו' ישנם ג\"כ ג' כוחות מחדומ\"ע כו', וגם בעבודה דתומ\"צ ישנם ג\"כ ג' קוין אלו תורה ועבודה וגמ\"ח. — בהבא לקמן ראה גם סה\"מ תר\"ל ע' רמא. תרל\"ה ח\"א שם ס\"ע סד ואילך. תרע\"ח ע' קנג ואילך."]]],[2000510305,"ע' בד\"ה ואהבת (למ\"ד) בסופו<sup data-n=\"954\">13</sup>, וגם בק\"ש אם כיון לבו יצא כי העיקר הוא הכוונה למס\"נ באחד כו', ולהתבונן איך דאנת הוא חד ולא בחושבן כו'. ותורה הוא בחי' דבור<sup data-n=\"955\">14</sup> כמ\"ש וידבר ה' אל משה לאמר ויאמר הוי' כו'. וגמ\"ח הוא בחי' מעשה המצות. והנה ע\"י העבודה ותורה וגמ\"ח ממשיכים אא\"ס בג' עולמות, ע\"י עבודה ממשיכים אוא\"ס ב\"ה בבריאה, וע\"י תורה ביצי', וע\"י מעשה המצות בעשי'. והנה לפ\"ז תפלה גדול מבחי' תורה, שתפלה היא בחי' מחשבה ותורה היא רק בחי' דבור, וא\"כ אינו מובן שהרי לפעמים מצינו שהתלמוד גדול שעיון תפלה הוא בכלל גמ\"ח כדפי' רש\"י בפ' מפנין ות\"ת היא כנגד כולם<sup data-n=\"956\">15</sup>. אך באמת שניהם אמת, כי לפי שהתורה היא ממקום גבוה יותר לכן נשפלה להתלבש גם בבחי' דבור, כי כל מה שהוא יותר נעלה יכול להשפיל ולירד למטה יותר<sup data-n=\"957\">16</sup> מאד וכענין מ\"ש במ\"א בענין ראי' ושמיעה<sup data-n=\"958\">17</sup> כו', ומ\"מ אין המשל דומה לנמשל שהרי ראי' אינו תופס הרוחני כו' ובתורה יש שניהם מחשבה ודבור, כי גם בתורה צ\"ל בחי' מח' בחי' עיון התורה וגם דבור התורה כו', ומעשה המצות ע\"י נמשך המשכת אוא\"ס ב\"ה בעשי' וכמשנ\"ת בד\"ה אך בעשור<sup data-n=\"959\">18</sup> שמצות הם מצות המלך ונודע שמל' מקננא בעשי' ולהיות כי שרש ומקור המצות הם בגלגלתא בחי' רצון העליון לכן יכולים להיות נשפל שיומשך ע\"י המשכת אוא\"ס גם בעשי' כו'.\nג) <b>אך</b> הנה כתיב כי הוי' אלקיך אש אוכלה הוא, שאין האור נאחז כ\"א במקום שהאש מכלה אותו כמו פתילה ועצים שהאש שורף ומכלה אותם, כך צ\"ל הג' בחי' אלו בבחי' ביטול, כי הנה בכלל הג' מדרגות הנ\"ל הם ג' מיני כלים פנימי' אמצעי' חיצוני' שהם חב\"ד חג\"ת נה\"י. והנה בחב\"ד שורה אוא\"ס יותר מבחג\"ת נה\"י לפי שהם בבחי' ביטול יותר, וכמו שאנו רואים שבאדם יש ג\"כ התחלקות ג' מדרגות אלו שהם ראש וגוף ורגל, והנה הראש הוא קטן מכולם ועכ\"ז עיקר חיות של האדם הוא הראש, ובראש שורים כל הכחות הנעלים, כמו כח השכל וכח הראי' וכח השמיעה, וכל החושים הדקים כמו הריח, וחיך אוכל יטעם. והגוף הוא יותר גדול מן הראש, ולכן החיות בו פחות יותר מבראש, הגם שבגוף הוא הלב, מ\"מ אין דומה בחי' הלב לגבי הראש<sup data-n=\"960\">19</sup>. והרגל הוא גדול אפי' מהגוף, לכך החיות נתצמצם",[["954","13","<b>בד\"ה ואהבת (למ\"ד) בסופו</b>: סה\"מ תר\"ל שם ע' רמא."],["955","14","<b>ותורה הוא בחי' דבור כמ\"ש וידבר ה'. . ויאמר ה'</b>: בד\"ה כי תשא תשכ\"ב מוסיף כאן: שהמשכת התורה מלמע' היא ע\"י דיבורו של הקב\"ה כמ\"ש וידבר ה' אל משה ויאמר ה' אל משה, וכמו\"כ צ\"ל לימוד התורה אצל האדם בדיבור דוקא וכמ\"ש חיים הם למוצאיהם ודרשו חז\"ל למוציאיהם בפה דוקא. [וראה גם ד\"ה בורא ניב תרח\"צ וד\"ה כי חלק תרצ\"ט שם]."],["956","15","<b>והנה לפ\"ז תפלה גדול. . לפעמים מצינו שהתלמוד גדול שעיון תפלה הוא בכלל גמ\"ח. . ות\"ת היא כנגד כולם</b>: בהבא לקמן ראה סה\"מ תרכ\"ז ע' רפא ואילך. [ובהנסמן שם]."],["957","16","<b>כל מה שהוא יותר נעלה יכול להשפיל ולירד למטה יותר</b>: ראה גם לעיל ד\"ה זאת חוקת. וש\"נ."],["958","17","<b>וכענין מ\"ש במ\"א בענין ראי' ושמיעה</b>: ראה בארוכה סה\"מ תרכ\"ח ע' יב ואילך. המשך וככה תרל\"ז פל\"ג (ע' מד-ה). פנ\"ז (ע' פו-ז). לעיל ד\"ה וכל העם ע' קסז-ח. וש\"נ. וד\"ה זאת חוקת."],["959","18","<b>וכמשנ\"ת בד\"ה אך בעשור</b>: תרל\"א בסוף סה\"מ תר\"ל ס\"ע שה."],["960","19","<b>הגם שבגוף הוא הלב מ\"מ אין דומה בחי' הלב לגבי הראש</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191168\" data-slug=\"likkutei-sichot\" data-id=\"1300191168\">לקו\"ש חי\"ט ע' 168</a> ואילך. [וראה באו\"א לקו\"ש חל\"א ע' 74. סה\"ש תשמ\"ח ח\"א ע' 222. וע' 348]. — בד\"ה כי ביום הזה יכפר בסה\"מ תר\"ל שם ע' שיא נרשם ע\"ז בגוכי\"ק בשולי הגליון: צ\"ע ממארז\"ל לב טוב וכן להיפך [לב רע], שאמר ריב\"ז רואה אני את דברי ר\"א בן ערך מדבריכם."]]],[2000510306,"בהם יותר שאין בהם רק כח ההילוך, לפי שכל שהכלי קטן יותר שורה שם יותר אור הנפש לפי שהוא בבחי' ביטול יותר, וע' בביאור ע\"פ אם בחוקתי (ך\"ו<sup data-n=\"961\">20</sup>). וככל המשל הזה יובן למעלה שבחב\"ד שורה אוא\"ס כמ\"ש הוי' בחכמה, ואין אוא\"ס שורה אלא בחכמה לפי שחכמה היא בחי' כח מ\"ה בחי' ביטול בחי' אחד האמת כמ\"ש בסש\"ב פל\"ה בהג\"ה, ולכן שורה שם אוא\"ס. ובחג\"ת אין שם כ\"כ הביטול ע' בת\"א ד\"ה ויאבק איש עמו<sup data-n=\"962\">21</sup>, לכן אין שם השראת אא\"ס כ\"כ כמו בחב\"ד, ובכלל זהו ההפרש בין איהו וחיוהי חד לבחי' איהו וגרמוהי חד, איהו וחיוהי הוא בחי' חכמה איהו וגרמוהי הוא בחי' מדות<sup data-n=\"963\">22</sup>. ולכן צ\"ל הג' מדרגות הנ\"ל עבודה ותורה וגמ\"ח בבחי' ביטול שעי\"ז אנו ממשיכים אוא\"ס ב\"ה בג' עולמות בי\"ע.\n<b>והכח</b> הזה ניתן לנש\"י וזהו שאנו מברכים ברכות השחר ברוך אתה ה' אלקינו מלך העולם, שמתחלה צריך להיות נמשך לנש\"י, ואח\"כ מלך העולם<sup data-n=\"964\">23</sup> שאח\"כ יוכל להיות מלך העולם שיומשך הביטול בעולמות, וע\"י מה ע\"י הוי' אלקינו כמ\"ש אלקי אברהם שהי' אברהם בחי' מרכבה וביטול לאלקות לכך נק' אלקי אברהם, וכמו\"כ בכלליות נש\"י ע\"י הביטול נק' אלקי ישראל כמארז\"ל במד\"ר יתרו פך\"ט אלקה אני לכל באי עולם אבל לא יחדתי שמי אלא עליכם, וכן לעתיד נא' ומאספכם אלקי ישראל וכמ\"ש מזה בד\"ה אני לדודי (למ\"ד<sup data-n=\"965\">24</sup>). וזהו הוי' אלקינו שע\"י בחי' ביטול לאא\"ס שיש בנש\"י עי\"ז נמשך לנש\"י בתחלה, ואח\"כ נמשך להיות מלך העולם שע\"י בחי' ביטול לאא\"ס שיש בנש\"י נמשך אח\"כ להיות המשכות אלקות בעולמות, וכמ\"ש באברהם ויקרא שם בשם ה' אל עולם שהודיע אלקותו ית' בעולם, ועי\"ז המשיך תוס' אורות למעלה. וכן ע\"י בחי' ביטול דנש\"י בכל הג' מדרגות, היינו להתפלל בבחי' ביטול עי\"ז ממשיך בבריאה, וע\"י תורה שלומד בבחי' ביטול ממשיך ביצי', וע\"י מעשה המצות שעושה בבחי' ביטול ממשיך בעשי', כי אם לא הי' בחי' ביטול לא הי' ממשיך כלום, כמו האש שאין שורה אלא בדבר שמכלה אותו, אבל בדבר שאין מכלה אותו אין האור נאחז בו יפה, כמו שמצינו פתילה שהאור מסכסכת בו, וכמו\"כ יובן שאם יש גאוה אין אא\"ס שורה שם כי אין אני והוא יכולים לדור, וה\"ז כמשל הפתילה שהאור מסכסכת בה, ובכל הג' מדרגות יש בחי' גאוה, לא מבעי במוחין ומדות שיש בהם גאוה, כ\"א אפי' בבחי' רגל יש ג\"כ גאוה וכמ\"ש אל תבואני רגל גאוה ולכן צריך ליזהר מזה מאד כו'. ועפ\"ז יובן מ\"ש והיתה נפש אדוני צרורה",[["961","20","<b>וע' בביאור ע\"פ אם בחוקתי (ך\"ו)</b>: נדפס עם הוספות בסה\"מ תר\"ל ע' קנ. [ראה סה\"מ תרכ\"ו ע' ]."],["962","21","<b>ע' בת\"א בד\"ה ויאבק איש עמו</b>: פ' וישלח כו, ב."],["963","22","<b>איהו וחיוהי. . חכמה, איהו וגרמוהי. . מדות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381286\" data-slug=\"likkutei-torah\" data-id=\"4001381286\">לקו\"ת שה\"ש לט, ג</a>. סה\"מ תרל\"ג ח\"ב ע' שמח. וש\"נ. המשך מים רבים תרל\"ו ע' קסה. ועוד."],["964","23","<b>אלקינו מלך העולם. . שמתחלה. . נמשך לנש\"י ואח\"כ מלך העולם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370023\" data-slug=\"torah-or\" data-id=\"3901370023\">תו\"א בראשית ו, ב</a>. לעיל ד\"ה ויהיו חיי שרה ס\"ע נח-ט. וש\"נ."],["965","24","<b>בד\"ה אני לדודי (למ\"ד)</b>: סה\"מ תר\"ל ע' רסה."]]],[2000510307,"בצרור החיים את הוי' אלקיך ואין צרור פחות משלשה, והיינו תורה ועבודה וגמ\"ח, וע\"י צרור הזה מתעלה הנשמה למקורה ושרשה להיות בבחי' את הוי' אלקיך ממש.\nד) <b>והנה</b> כמו שיש בקדושה אש הוי'<sup data-n=\"966\">25</sup>, כמו\"כ בלעו\"ז יש אש תאוות זרות, וגם כלים דקליפה שהאש נאחז בהם, מח' דבור ומעשה דקליפה כמ\"ש ואת נפש אויביך יקלענה בתוך כף הקלע כו'. והנה לזה צריך תשובה כמשארז\"ל על ר' אלעזר בן דורדיא געה בבכי' עד שיצתה נשמתו, בכה רבי וא' יש קונה עולמו בכמה שנים ויש קונה עולמו בשעה א'. וצ\"ל דהתינח מה שמוחלין לו עוונותיו מפני שעשה תשובה, אך הנה ע\"י תומ\"צ ממשיכים אוא\"ס בכלים, והוא לא המשיך כי אין לו תומ\"צ, ואיך הגיע למדרגת רבי, שהרי אמר שקנה עולמו בשעה א', משמע כמו הוא בכמה שנים. אך הנה במשה כתיב כשהי' צריך להמשיך י\"ג מדה\"ר כתיב ויאמר ה' הנה מקום אתי כו' והי' כו' ושמתיך בנקרת הצור, וצ\"ל הלא צור הוא מקור הגבורות שהרי ממנו מוציאים אש שהוא אבן הנק' בל\"א קרעמין, וי\"ג מדה\"ר הם מקור החסדים ורב חסד מטה כלפי חסד, נושא עון ועובר על פשע, ולמה היו צריכים לבחי' צור שהוא מקור הגבורות.\n<b>אך</b> הנה יש עוד פי' בצור ל' חוזק<sup data-n=\"967\">26</sup>, מלשון גבור כארי שהוא תגבורת החיות, וגם זאת אמת שארי' בגימ' גבורה שהוא בחי' דין וכשנופל למטה נעשה חי' הטורף ודורס<sup data-n=\"968\">27</sup>, אך בשרשו הוא תגבורת החיות, וכמו שמצינו שהשבטים נמשלים לבהמות וחיות גור ארי' יהודה<sup data-n=\"969\">28</sup>, יששכר חמור גרם, בנימין זאב יטרף. והחילוק שבין בהמות לחיות<sup data-n=\"970\">29</sup> הוא בזה שהבהמה יש לה כח רב לעשות מלאכה, כמו שור לעול וחמור למשא, אבל מ\"מ הילוכו הוא בעצלות שאין לו זריזות כ\"כ, אבל חיה הילוכה במהירות וזריזות מפני שיש בה תגבורת החיות, מפני שהחי' הוא מבחי' גבורות ושרש הבהמה הוא בחי' חסדים, ולכן נק' שם חי' ע\"ש תגבורת החיות, ולכך מי שיש בו ריבוי דם הוא בחיות יותר כמ\"ש בדוד והוא אדמוני עם יפה עינים, ולכך הי' גבור גדול ומלך לפי שהדם הוא בחי' גבורה יסוד האש. ועוד יש ראי' שהרי דברים היוצאין מן הלב נכנסים ללב<sup data-n=\"971\">30</sup> שאם אמר דבר זה גופא בקרירות",[["966","25","<b>והנה כמו שיש בקדושה אש הוי' כמו\"כ בלעו\"ז. ֿ. ואת נפש אויביך יקלענה</b>: בהבא לקמן ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380189\" data-slug=\"likkutei-torah\" data-id=\"4001380189\">לקו\"ת אחרי שם כו, ב</a>."],["967","26","<b>אך הנה יש עוד פי' בצור ל' חוזק</b>: בהבא לקמן בפיסקא זו ראה בארוכה מאמרי אדה\"ז תקס\"ב שם ע' ד ואילך. אוה\"ת דרושים ליוהכ\"פ שם ע' ב'קלא ואילך."],["968","27","<b>שארי'. . וכשנופל למטה נעשה חי' הטורף ודורס</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370119\" data-slug=\"torah-or\" data-id=\"3901370119\">תו\"א וישלח כה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370420\" data-slug=\"torah-or\" data-id=\"3901370420\">תו\"א מג\"א צג, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381168\" data-slug=\"likkutei-torah\" data-id=\"4001381168\">לקו\"ת שה\"ש ט, ד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600466\" data-slug=\"or-hatorah-hb\" data-id=\"8316600466\">אוה\"ת</a> וירא צג, ב. וארא ע' קסד. נ\"ך ע' תסו. סה\"מ תרכ\"ז ע' נ. וש\"נ. תרכ\"ט ע' קס. וש\"נ. [ובהנסמן בהע' שלאח\"ז]."],["969","28","<b>וכמו שמצינו שהשבטים נמשלים לבהמות וחיות גור ארי' יהודה</b>: ראה בכ\"ז בארוכה ביאוה\"ז לאדהאמ\"צ כז, ג ואילך. ולהצ\"צ ח\"א ע' קנט ואילך. אוה\"ת ויחי (כרך ו) תתשכא, א ואילך. סה\"מ תר\"ם ח\"א ד\"ה גור ארי' יהודה ע' כג ואילך. וש\"נ."],["970","29","<b>והחילוק שבין בהמות לחיות</b>: ראה בכ\"ז בארוכה מאמרי אדה\"ז תקס\"ב שם ע' ד. אוה\"ת דרושים ליוהכ\"פ שם ע' ב'קלא."],["971","30","<b>ועוד יש ראי' שהרי דברים היוצאין מן הלב נכנסים ללב</b>: ראה בכ\"ז המשך תער\"ב ח\"ג ס\"ע א'רפט. סה\"מ תרפ\"ט ע' 30. וש\"נ. תש\"ו ע' 26."]]],[2000510308,"לא הי' מכניס ללב השומע, אבל אם אומר זה בהתפעלות ברשפי אש נכנס בתוך לב השומע. וכן אנו רואים שבדבור ניתוסף לו שכל מה שלא הי' במוח החכמה, כי יסוד המים הוא במוח, אבל הדבור יוצא מהבל הלב שהוא בחי' אש, ולכך ניתוסף לו שכל חדש, וכענין ומתלמידי יותר מכולם. ועוד יש ראי' מגשמים שהם בחי' חסדים, ועכ\"ז נקראים גבורות גשמים<sup data-n=\"972\">31</sup> מפני שיורדין בגבורה, וענין הגבורות היינו מה שמתחלקין לטיפין טיפין, וה\"ז תכלית החסד שאם לא הי' ההתחלקות הי' למבול לשטוף את העולם. ונמצא שהגבורה הוא בחי' מקור החסדים שהוא מחלק ועושה טיפין טיפין כו', וכמ\"ש וארבה את זרעו ואתן לו את יצחק, ארבה בגימ' יצחק שהוא בחי' גבורות. נמצא שע\"י הגבורות יש ג' בחי', זריזות, ודברים היוצאים מהלב נכנסים ללב, והתחלקות וריבוי. אך למטה נתהווה ממנה גבורות קשות על ההיפוך, כמו שאנו רואים שהכעס הוא מריבוי הדם, שכל מי שיש לו ריבוי דם הוא יותר מתכעס על ההיפוך על מי שעובר רצונו, וכך למעלה בחיות שנק' חיות ע\"ש תגבורת החיות מהארת אא\"ס אשר בהם שלכן נק' חיות הקדש, מתהווה מזה אח\"כ כעס על מי שעובר רצון העליון, וכנודע מענין מזיעתם<sup data-n=\"973\">32</sup> של חיות הקדש נהר דינור יוצא כו' שהוא בחי' הכעס על ההיפך כו'.\n<b>וזהו</b> כי בי\"ה הוי' צור עולמים, ביו\"ד נברא עוה\"ב ובה' נברא עוה\"ז, כמו למשל באדם שיש ה' מוצאות הפה נתהווה מזה כמה צירופי אותיות, כך למעלה מעשרה מאמרות אלו נתהווה כמה צירופים עד אין שיעור, ושרשם הוא בחי' היו\"ד שבו נברא העוה\"ב והה' שבו נברא העוה\"ז, ושרש ההתחלקות הוא מבחי' גבורה, היינו בחי' גבורה דעת\"י בוצינא דקרדוניתא, וזהו כי בי\"ה הוי' צור עולמים ופי' בפרד\"ס<sup data-n=\"974\">33</sup> שער י\"ט פ\"ד כי בי\"ה היינו חכ', הוי' הוא הכתר, צור עולמים הוא ב' עולמים בינה ומל' שהם עוה\"ב ועוה\"ז, וכ\"כ במק\"מ ר\"פ וארא, וזהו שפי' צור זהו גבורה דעתיק שמלובש בח\"ס<sup data-n=\"975\">34</sup> ובו צור העולמים. ונמצא כי שרש כל עולמים הוא מבחי' צור ל' גבורה וחוזק תגבורת החיות בחי' בוצינא דקרדוניתא גבורה דעת\"י, ומבחי' צור זה הוא ג\"כ מקור בחי' האש דבחי' כי הוי' אלקיך אש אוכלה הוא, שהרי ג\"ז נמשך ע\"פ מדידת הקו המדה כו'. והנה עבודת הצדיקים הוא שממשיכים בחי' ה' אלקיך אש אוכלה ע\"י העבודה בג' בחי' עבודה ותורה וגמ\"ח כנ\"ל, אבל כשפגם ח\"ו הנה ארז\"ל עבירה מכבה מצוה שמכבים את האש, הגם שאין שייך למעלה שמכבים את הוי' אלקיך אש אוכלה הוא ח\"ו, מ\"מ מכבים את בחי' הוי' המאיר בנפש<sup data-n=\"976\">35</sup> כו', ולזה צריך תשובה להמשיך ממקור בחי' האש היינו מבחי' צור.",[["972","31","<b>ועוד יש ראי' מגשמים. . גבורות גשמים</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a>. לקו\"ת ואתחנן יג, רע\"ג. סידור עם דא\"ח סא, ד. סה\"מ תרכ\"ז ס\"ע רמט-נ. וע' רסג. תרכ\"ט ע' רכו-ז. המשך מים רבים תרל\"ו ס\"ע עה ואילך. ועוד."],["973","32","<b>וכנודע מענין מזיעתם. . נהר דינור יוצא. . הכעס על ההיפוך</b>: ראה תו\"א וישב ל, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380476\" data-slug=\"likkutei-torah\" data-id=\"4001380476\">לקו\"ת שלח מא, א</a>. סה\"מ תרל\"ג ח\"א ע' רלו. ועוד."],["974","33","<b>כי בי\"ה הוי' צור עולמים ופי' בפרד\"ס</b>: הובא ונת' באוה\"ת דרושים ליוהכ\"פ שם ע' ב'קלא."],["975","34","<b>שמלובש בח\"ס</b>: באוה\"ת דרושים ליוהכ\"פ שם: המלובש בי\"ס."],["976","35","<b>ארז\"ל עבירה מכבה מצוה. . מכבים את בחי' הוי' המאיר בנפש</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380796\" data-slug=\"likkutei-torah\" data-id=\"4001380796\">לקו\"ת ראה כ, א</a>. דרך חיים קי, ג. אוה\"ת בא (כרך ח) ע' ב'תתקלט. ראה ע' תרפא. סה\"מ תרל\"ט ח\"א ע' קכח. וע' קמד."]]],[2000510309,"ה) <b>וזהו</b> כשרצה להמשיך מבחי' יגמה\"ר, אמר הנה מקום אתי ושמתיך בנקרת הצור שהי' צריך להמשיך מבחי' המקור<sup data-n=\"977\">36</sup>, הנה מקום אתי, מקום הוא סדר השתל' שהוא צמצום מקום פנוי וחלל ריקן, אבל מקום אתי היינו איך שהמקום בטל אליו<sup data-n=\"978\">37</sup> שהוא מקומו של עולם ואין העולם מקומו, ושמתיך בנקרת הצור שהוא מקור הגבורות להיות השתלשלות העולמות, וזהו והי' בעבור כבודי אין כבוד אלא תורה, ובעבור כבודי שעוברים על התורה מלך שמחל על כבודו אין כבודו מחול, ושמתיך בנקרת הצור שצריך להמשיך מבחי' הצור שהוא מקור של כל העולמות. וע\"י מה יגיעו לזה ע\"י בחי' תשובה כי יש ב' מיני אהבה, אהבה הנמשכת כמים, וזהו אהבה של צדיקים, ויש עוד אהבה כרשפי אש שהוא בתגבורת יותר ובחילא יתיר, וזהו בחי' בע\"ת, ועי\"ז מגיעים לבחי' צור. וזהו והי' בעבור כבודי שצריך להעביר על כבודו למשוך מלמעלה מבחי' כבוד כמ\"ש ברוך כבוד הוי' ממקומו, פי' ממקורו ושרשו כמו ממקומו הוא מוכרע, ע' מזה בד\"ה ואולם חי אני בהביאור (ך\"ב)<sup data-n=\"979\">38</sup>, כי כבודו הוא מבחי' הוי', אבל למעלה מבחי' כבוד זה הוא בחי' מקומו שהוא מקומו של עולם ואין העולם מקומו. וזהו בחי' בע\"ת בחי' צור. וע\"כ בע\"ת גדולים מצדיקים מפני שהם ממשיכים ממקום גבוה יותר מבחי' מקור ושרש העולמות, ולכן גדלה מעלת הבע\"ת שהם ממשיכים ע\"י בחי' חילא יתיר שלהם מבחי' הצור מקור בחי' האש. ובזה יתורץ איך שקונה עולמו בשעה א' כמו הצ\"ג בכמה שנים, לפי שע\"י בחי' החילא יתיר שלו מגיע לבחי' הצור הוא בחי' מקור ושרש המשכת הצדיקים כו'. וזהו שהצדיקים שעבודתם הוא להמשיך בחי' ה' אלקיך אש ע\"י העבודה ותורה וגמ\"ח אין יכולים לעמוד במקום הבע\"ת, כי מקום הבע\"ת הוא גבוה ונעלה ביותר. אך הנה איתא שמשיח אתא לאתבא צדיקייא בתיובתא, פי' שגם הצדיקים יבואו למעלת ומדריגת התשובה<sup data-n=\"980\">39</sup>, כי ענין התשובה אינה על חטא ועון דוקא<sup data-n=\"981\">40</sup>, כ\"א שצ\"ל כל ימיו בתשובה על שהביטול בג' בחי' תורה ועבודה וגמ\"ח אינה כדבעי למהוי, וע\"י בחי' תשובה מעומקא דלבא על בחי' זו ע\"י",[["977","36","<b>כשרצה להמשיך מבחי' יגמה\"ר אמר. . ושמתיך בנקרת הצור שהי' צריך להמשיך מבחי' המקור</b>: בד\"ה זאת חוקת תשכ\"א שם מבאר זה: דכיון שחטאו בחטא העגל שהי' חטא חמור ביותר, לכן אח\"כ כאשר הי' צ\"ל ההמשכה (היינו לא רק הכפרה אלא גם ההמשכה) שיהי' פניך הולכים, הוצרך להיות מבחי' הצור דוקא דבבחי' זו לא הי' פגם כנ\"ל."],["978","37","<b>מקום. . סדר השתל'. . מקום אתי. . שהמקום בטל אליו</b>: ראה בכ\"ז אוה\"ת ויצא קפה, א-ב. ובארוכה ספר החקירה להצ\"צ עד, סע\"ב ואילך. סה\"מ תרל\"ה ח\"א ע' קו ואילך. תרמ\"ג ע' צד ואילך. פר\"ת ע' קפה ואילך. תרפ\"ז ע' פד ואילך. תש\"ל ע' 56 ואילך. 64 ואילך. 73 ואילך. ועוד."],["979","38","<b>ע' מזה בד\"ה ואולם חי אני בהביאור (ך\"ב)</b>: ראה ד\"ה ואולם חי אני וביאורו בדרמ\"צ קעט, א-ב. קפג, סע\"ב ואילך. המאמר בדרמ\"צ הוא משנת תקפ\"ח אך נאמר עוה\"פ בשנת תרכ\"א-כ\"ב. קיצורים על מאמר הדרמ\"צ משנת תרכ\"א-כ\"ב נמצאים בכת\"י 1056 (הכולל מאמרי אדמו\"ר הצ\"צ משנת תרכ\"א-כ\"ב) ונדפסו בהוספות לדרמ\"צ (הוצאת תנש\"א ואילך) ר, ב ואילך. מאמר זה נזכר גם בסה\"מ תרל\"ג ח\"א ע' טו: ”בד\"ה ואולם חי אני. . בספר ך\"א\"."],["980","39","<b>שמשיח אתא לאתבא צדיקייא בתיובתא. . הצדיקים יבואו למעלת ומדריגת התשובה</b>: ראה לעיל סד\"ה זאת חוקת. וש\"נ."],["981","40","<b>ענין התשובה אינה על חטא ועון דוקא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380962\" data-slug=\"likkutei-torah\" data-id=\"4001380962\">לקו\"ת</a> דרושים לר\"ה ס, ד ואילך. ובארוכה סה\"מ תרצ\"ז ע' 235. וש\"נ."]]],[2000510310,"מגיעים הצדיקים ג\"כ למעלת ומדריגת הבע\"ת הוא בחי' הצור כו' מקור מוצא האש כו'.\n<b>וכמו</b> שיהי' לע\"ל ליום שכולו שבת שמשיח יביא לאתבא צדיקיא בתיובתא, כן ביום השבת שהוא אותיות תשב אמר הכתוב לא תבערו אש שהיא בחי' פרטי' ההמשכה הנמשכת מן הצור, כ\"א שע\"י בחי' התשו' בא לבחי' הצור<sup data-n=\"982\">41</sup> מקור מוצא האש, והיינו ע\"י השביתה מכל המלאכות שמקורם מאור הראשון דיהי אור, ואמר לא תבערו אש שלא לתת כח ושליטה לאש זרה דלעו\"ז, כ\"א להיות בבחי' ביטול לבחי' כי ה' אלקיך אש אוכלה הוא, ועי\"ז ע\"י שבת אותיות תשב בא לבחי' הצור כו'.",[["982","41","<b>ביום השבת שהוא אותיות תשב אמר הכתוב לא תבערו אש. . כ\"א שע\"י בחי' התשו' בא לבחי' הצור</b>: בד\"ה זאת חוקת תשכ\"א שם מבאר זה: דבו' ימי החול הו\"ע ההתהוות מבחי' העש\"מ שבכללותם הוא מאמר יהי אור בחי' האש שהו\"ע עבודת הצדיקים, אבל בשבת אותיות תשב הו\"ע עבודת התשובה (אף שתשובה זו היא תשו\"ע ולא תשו\"ת), ומכיון שעבודת התשובה הוא בבחי' הצור שלמע' מבחי' האש כנ\"ל לכן כתי' לא תבערו אש גו' ביום השבת לפי שבשבת העבודה הוא בבחי' הצור שלמע' מבחי' האש, והוא בחי' האור שלמע' מהשתל' ואינו שייך לעולמות, דבחי' האש יהי אור הוא בחי' האור שנמשך ע\"י תומ\"צ בבחי' בראתיו יצרתיו ועשיתיו, אמנם בשבת שהו\"ע השביתה מהתהוות הנה אז הוא המשכת בחי' הצור שהוא אור שלמע' מהעולמות."]]],[2000510311,"<h3>וסמך ידו</h3>\n<b>בס\"ד. [פ' ויקרא].</b>\n<b>וסמך</b> ידו<sup data-n=\"983\">1</sup> על ראש העולה ונרצה לו לכפר עליו, משמע שע\"י הסמיכה שסומך על העולה עי\"ז ונרצה לו לכפר עליו, וצ\"ל מה\"ע הסמיכה שע\"י הסמיכה יתרצה הקרבן להיות לו לכפרת עון כו'. והנה בגמ' פב\"ת דערובין דצ\"ו ע\"ב דבר אל בני ישראל וסמך, בני ישראל סומכין ואין בנות ישראל סומכין, ולכאורה צ\"ל מפני מה בני ישראל דוקא ולא בנות ישראל. הנה ענין הסמיכה בידיו הוא כי עשר אצבעות הם ע\"ס כמ\"ש בס\"י עשר ספי' בלי מ\"ה כמספר עשר אצבעות, ולכן פי' בבחיי פ' ויחי<sup data-n=\"984\">2</sup> ע\"פ שכל את ידיו שז\"ע שאו ידיכם קדש הוא בחי' ח\"ע להמשיך",[["983","1","<b>וסמך ידו</b>: מיוסד על ד\"ה זה באוה\"ת ויקרא (כרך א) ע' רכא. וחלק מהמאמר מיוסד על ד\"ה זאת חנוכת המזבח ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380421\" data-slug=\"likkutei-torah\" data-id=\"4001380421\">לקו\"ת נשא כח, ב</a>-ג.\nהמאמר נמצא בשינויים ותוס' הגהות וכו' בד\"ה זה: בס' תרמ\"ב. ובסה\"מ תרנ\"ג ע' קפד ואילך. תרנ\"ח ע' רכז ואילך. וראה גם ד\"ה שאו ידיכם קדש בסה\"מ תרפ\"ז ס\"ע ריז ואילך. [המיוסד על חלק מהמאמר דתרנ\"ג]. — חלק ממאמר זה נמצא בשינויים לקמן בהמשך והחרים ד\"ה הים ראה וינוס."],["984","2","<b>ולכן פי' בבחיי פ' ויחי ע\"פ שכל את ידיו שז\"ע שאו ידיכם קדש</b>: ז\"ל הבחיי שם: וזהו ביאור שכל את ידיו כו' והיתה הברכה חלה עליהם בסמיכה זו כאשר כתוב ביהושע ויסמוך את ידיו עליו כדי שיאצל רוח הקדש על הנסמך, ומזה הענין היתה הסמיכה בזמן החכמים. גם ברכת כהנים בנשיאת כפים, כי לא יתכן לכהן הנושא את כפיו שיסמוך את ידיו על כאו\"א מישראל, וע\"ז הי' פורש כפיו למעלה כדי להאציל כח הברכה למטה ממקור הברכה העליונה, והוא שכל את ידיו מלשון שכל וחכ', כי נתכוון בעשר אצבעות להמשיך הברכה ממקור החכ' והשכל, כענין שאו ידיכם קדש וברכו את ה', קדש היא החכ' שהיא מקור הברכה. ע\"כ. — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381227\" data-slug=\"likkutei-torah\" data-id=\"4001381227\">לקו\"ת שה\"ש כד, סע\"ג</a>. יהל אור לתהלים (ע\"פ שאו ידיכם) ע' תקח."]]],[2000510312,"משם הברכה, ועד\"ז כתי' במשה ויסמוך את ידיו עליו, ועי\"ז נתהוה יהושע מלא רוח חכ' כמ\"ש ויהושע מלא רוח חכ' כי סמך משה את ידיו עליו. ועד\"ז יובן ענין הסמיכה בקרבנות שהו\"ע ההמשכה מבחי' אדם המסמיך שאדם בגימ' מ\"ה לבחי' בהמה בגימ' ב\"ן, והיינו כי רוח האדם העולה היא למעלה משא\"כ רוח הבהמה היא היורדת למטה לארץ ש' ב\"ן מקור לבי\"ע ומשתלשל עד נה\"ב, וכדי שיהי' העלאת נה\"ב צ\"ל המשכה מבחי' אדם<sup data-n=\"985\">3</sup> להעלותה וז\"ע וסמך את ידו המשכה מע\"ס דמ\"ה, להעלות ש' ב\"ן בחי' בהמה.\n<b>ולהבין</b> ביאור הענין צ\"ל שורש ענין העלאת הבהמה<sup data-n=\"986\">4</sup> הוא בחי' ש' ב\"ן שבאדם שהוא נה\"ב בהקרבתה בעבודה שבלב זו תפלה שכנגד תמידין תקנו, והוא כי שורש ענין התפלה הוא להעלות נה\"ב שבאדם בעבודה שבלב להפוך לבו מן הקצה אל הקצה, ממה שהי' שקוע וטרוד כל היום במחשבות אדם ותחבולתיו ויצרי מעללי איש, איש איש כפי שידוע לו בעצמו נגעי לבבו, לצעוק אל ה' בצר לו בכל לב ונפש וכמ\"ש צעק לבם אל כו', ולעורר את האהבה לה' בתשוקה וצמאון לדבקה בו ית' עד שתחפוץ להתפשט מלבושים צואים הן הן המח' והדבורים והמעשים אשר לא לה' המה, הן בהיתר שהן מלבושי נוגה<sup data-n=\"987\">5</sup> שלפעמים עולה ונכללת בקדושה כאשר יפלס מעגלי דרכיו שלא יהנה מעוה\"ז רק לשם שמים להרחיב דעתו לה' ולתורתו כו', משא\"כ כשנמשך האדם אחר גופו לצורך עצמו ולהנאת עצמו מכוון, אזי הוא יורד ונמשך למטה, ומן ההיתר יסיתנו כו', וז\"ע הנוגה כשהיא יורדת ונכללת למטה בקליפות הטמאות לגמרי כו'. וע\"ז נתקן סדר התפלה. ותחלה יסדר אדם שבחו של מקום בפסוקי דזמרה בגדולת ורוממות א\"ס ב\"ה, לעורר התשוקה והצמאון בנה\"ב לאסתכלא ביקרא דמלכא בסידור שבחיו, איך שברוך שאמר והי' העולם היינו באמירה אחת, ובמאמר א' יכול להבראות<sup data-n=\"988\">6</sup>, וכמ\"ש בזהר במחשבה אחת ברא את העולם, שהוא צופה ומביט עד סוף כל הדורות וקורא הדורות מראש וכולם נסקרים בסקירה א' כו'. והוא יחיד חי העולמים מלך פי' שהוא יחיד ומיוחד לבדו הוא כמו קודם שנבה\"ע וכמ\"ש אתה הוא עד שלא נברה\"ע, וכתי' אני ה' לא שניתי שגם לאחר שנבה\"ע אין עוד מלבדו",[["985","3","<b>הבהמה. . ש' ב\"ן. . העלאת נה\"ב צ\"ל המשכה מבחי' אדם</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380087\" data-slug=\"likkutei-torah\" data-id=\"4001380087\">לקו\"ת ויקרא ג, ב</a>-ג. ועוד."],["986","4","<b>ולהבין ביאור הענין צ\"ל שורש ענין העלאת הבהמה</b>: בהבא לקמן לקמן בפיסקא זו ראה ד\"ה זאת חנוכת המזבח ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380421\" data-slug=\"likkutei-torah\" data-id=\"4001380421\">לקו\"ת נשא שם כח, ב</a>-ג. [נזכר בד\"ה וסמך באוה\"ת ויקרא שם. — והבא לקמן הוא ע\"פ לשון הלקו\"ת שם בשינויים]."],["987","5","<b>מלבושי נוגה שלפעמים עולה ונכללת בקדושה. ֿ. שלא יהנה מעוה\"ז רק לש\"ש להרחיב דעתו לה' ולתורתו כו'</b>: בלקו\"ת נשא שם נוסף כאן: ”כמ\"ש במ\"א\". ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז (יא, ב</a>)."],["988","6","<b>שברוך שאמר. . היינו באמירה אחת ובמאמר א' יכול להבראות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380720\" data-slug=\"likkutei-torah\" data-id=\"4001380720\">לקו\"ת ואתחנן ב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380904\" data-slug=\"likkutei-torah\" data-id=\"4001380904\">נצבים מו, ב</a>. דרושים לר\"ה נה, ב. שה\"ש מא, ד. מאמרי אדה\"ז מארז\"ל ותפלה ע' תלה. ועוד."]]],[2000510313,"ואתה הוא ה' לבדך כמו קודם שנבה\"ע, כי העולם אינו תופס מקום כלל דכולא קמי' כלא ממש חשיבי, לפי שאתה עשית את השמי' ושמי כו' ואתה מחי' את כולם, וחי העולמים אינו אלא מבחי' מלך שאין זה אלא לפי שנק' שמו ומלכותו על המדינה<sup data-n=\"989\">7</sup>. משובח ומפואר עדי עד פי' למעלה עד אין קץ ולמטה עד אין תכלית<sup data-n=\"990\">8</sup> בעילוי אחר עילוי עד אין קץ ותכלית כמ\"ש הכל ירוממוך סלה, וקדושים בכל יום יהללוך סלה פי' סלה בלי הפסק עד רום המעלות, ונודע כי יש כמה מיני עליות<sup data-n=\"991\">9</sup> בג\"ע התחתון והעליון ונו\"ן אלפים יובלות ושמיטין שבהם, שהם הרבה מיני עילויים מעילויים שונים, והכל נמשך רק מבחי' שמו הגדול בחי' שמו ומלכותו, שאין זה רק בחי' זיו והארה בלבד כו', וכי נשגב שמו שאפי' שמו הוא בבחי' נשגב לבדו רק הודו וזיו של שמו על ארץ ושמים כו'. ואי לזאת תכלה ותכסוף אליו ית' נפש כל חי לדבקה בו ית', ובפרט בהזכירו כי שמו הגדול ומלכותו ית' עלינו וכמ\"ש וירם קרן לעמו וכתיב מגיד דבריו ליעקב, כי יעקב בחר לו י\"ה ישראל לסגולתו, ואומרים ברוך ה' אלקי ישראל, אזי תתעורר השמחה בלב כל איש ישמח ישראל בעושיו בשמחה גדולה שהשרה שכינתו בתוכינו, ויהיו כל ישראל אחרי ה'. ואח\"כ ברכת ק\"ש איך שהמלאכים מקדישים ומפארים ומעריצים כו', ואהבת עולם אהבתנו חמלה גדולה ויתירה פי' יתירה מהמלאכים, ע' בסש\"ב<sup data-n=\"992\">10</sup>. ומזה יעלה ויבא ויגיע למסור נפשו באחד ואהבת בכל לבבך בשני יצריך, דהיינו שגם כח המתאוה<sup data-n=\"993\">11</sup> שבנה\"ב שבאדם המתאוה לדברים גשמי' וצרכי גופו בתענוגות בני אדם ישוב לאהבת ה' ויחפוץ בקרבת אלקים כי טוב שהוא מקור כל התענוגים וחיי החיים ב\"ה ואזי יתענג על ה' ממש.\n<b>וביאור</b> הענין הוא שלא כאשר מדמים שנה\"ב בעצם הוא המתאוה תאות רבות ורעות, לא כן הוא, כ\"א נה\"ב הוא כח רוחני והוא עצם כח המתאוה, ובבחי' כח המתאוה הלזה ביכולתו להיות בבחי' אהבה עזה לאלקות, ומה שהוא מתאוה דברים גשמי' לצורכי גופו בתענוגות בני אדם, זהו מפני היותו מלבישו בלבושים צואים ורעים, והרי הוא הוא הפועל הדבר הרע, כי אין רע יורד מלמעלה כלל, כ\"א הוא בעצמו עושה במעשיו הרעים את הדבר הרע הזה, וברצונו הנה הוא כחומר ביד היוצר לעשות לבושים טובים בכח המתאוה הלזה עד שיהי' לו אהבה בכל לבבך בשני יצריך שגם היצה\"ר ישוב לאהבת ה', מפני כי בעצם הוא רק כח",[["989","7","<b>וחי העולמי' אינו אלא מבחי' מלך. . שנק' שמו ומלכותו על המדינה</b>: בד\"ה זאת חנוכת בלקו\"ת נשא שם נוסף כאן: ”כמ\"ש במ\"א\". ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370005\" data-slug=\"torah-or\" data-id=\"3901370005\">תו\"א בראשית א, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370151\" data-slug=\"torah-or\" data-id=\"3901370151\">מקץ לב, ג</a>. מג\"א צ, ג. לקו\"ת במדבר טו, א. ובכ\"מ."],["990","8","<b>משובח ומפואר עדי עד פי' למעלה עד אין קץ ולמטה עד אין תכלית</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370136\" data-slug=\"torah-or\" data-id=\"3901370136\">תו\"א וישב כט, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370151\" data-slug=\"torah-or\" data-id=\"3901370151\">מקץ לב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370221\" data-slug=\"torah-or\" data-id=\"3901370221\">שמות מט, סע\"א</a>. לקו\"ת חוקת סה, ב. ונת' בסה\"מ תרכ\"ז ע' פה."],["991","9","<b>וקדושים בכל יום יהללוך סלה פי' סלה בלי הפסק. . כמה מיני עליות</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380253\" data-slug=\"likkutei-torah\" data-id=\"4001380253\">לקו\"ת בהר מא, ב</a> ואילך."],["992","10","<b>חמלה גדולה ויתירה פי' יתירה מהמלאכים, ע' בסש\"ב</b>: פרק מט (סט, סע\"ב)."],["993","11","<b>וביאור הענין הוא שלא כאשר מדמים. . כח המתאוה</b>: בהבא לקמן עד סוף הפיסקא ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חוקת נו, ג</a>-ד. דרושים לר\"ה סא, ד. סה\"מ תרכ\"ט ע' קא ואילך. קונ' העבודה פ\"ג (ע' 32). לעיל ע' רטז. ועוד."]]],[2000510314,"המתאוה לבד כנ\"ל, וכמו היוצר שיכול לעשות מהחומר איזהו כלי שירצה, אם כד או כלי אחרת כמו קערה וכדומה, כן בנפשו הבהמית הוא בחי' כח המתאוה להיותו בבחי' התגברות המדה על השכל לכן התאוה בו העיקר<sup data-n=\"994\">12</sup> ומתגבר על שארי הכוחות, אך אם מלבישו או מציירו בצורה רעה כמו עניני התאות לצרכי גופו בתענוגי בני אדם הרי התאוה מכסה על השכל, ויוכל לעשות שטותים רבים ואיננו מרגיש כלל להיות כי התאוה מכסה לבלי יורגש כלל בעת עשיית המעשה את הדבר שטות שעושה, וזהו שארז\"ל אין אדם עובר עבירה אלא א\"כ נכנס בו רוח [שטות<sup data-n=\"995\">13</sup>], פי' ענין הכנסת רוח שטות בו הוא בחי' התאוה שמלבישה בלבוש צואה המכסה על השכל לגמרי ועושה שטותים נוראים, עד שפועל העבירה בגשמיות הוא גמר הלבוש רע ולבוש צואה שיוצא מכח אל הפועל (ובעודו במצפונות לבו ה\"ה במח' עדיין שמחשב איך לעשות הדבר הרע ההיא, ואז השטות הוא במח' עדיין) ומדמה כי לא יראני שום אדם ולא יודע מזה כלל, הגם שבאמת ע\"פ השכל מושג שבודאי יתודע הדבר ההיא, וגם הלא אפי' אם לא יתודע לבני אדם הרי גלוי וידוע הוא לפני ה' שחוקר לב ובוחן כליות כמ\"ש אני ה' חוקר לב ובוחן כליות, ונמצא כי הרוח שטות אשר בקרבו מכסה על השכל לגמרי, ועי\"ז הנה הוא מצייר צורה רעה או מלביש בלבוש רע וצואה את כח המתאוה שבנפשו הבהמי', והרי הוא הוא, הוא העושה מעשה הרע, משא\"כ קודם שפועל פעולת הרע, או גם קודם שמחשב עדיין במח' התאוה הזרה והרעה אז כח המתאוה שבנפשו הוא עדיין כח רוחני להיות תאב לדבר מהדברים שיפול עליהם התאווה, והרי הוא יכול לאהוב את הבורא ית' בכח המתאוה הלזה לקיים מצות ואהבת את ה' אלקיך בכל לבבך בשני יצריך או לאהוב ישראל שזהו מן המצות אהבת ישראל, וכאשר משמר א\"ע מכל דבר רע אז הוא מקיים כמארז\"ל בכל לבבך בשני יצריך שגם היצה\"ר ישוב לאהבת ה'. וזהו שורש ענין הקרבן ברוחניות.\n<b>ולכן</b> נאמר אדם כי יקריב מכם<sup data-n=\"996\">14</sup>, ולא נאמר אדם מכם כי יקריב, והיינו שאם הי' נאמר אדם מכם כי יקריב הי' פי' שאם ירצה איזה אדם מכם להקריב קרבן שתי' מכם הי' מפריש את האדם המקריב הקרבן מן כלל ישראל שבעת זה",[["994","12","<b>כח המתאוה להיותו בבחי' התגברות המדה על השכל לכן התאוה בו העיקר</b>: בד\"ה זה תרנ\"ג מבאר זה, וז\"ל: הנה\"ב בעצם הוא רק כח מתאווה חזק שלא ע\"פ השכל, דהנה ידוע דמדות הם מוגבלים ע\"פ השכל, וענין המדות בכלל הוא איזה תאווה והמשכה לאיזה פרט באיזה מדה שיהי' אם בחסד או בגבורה או בהתפארות כו', רק שהמדה והרצון הוא מוגבל ע\"פ השכל. והנה\"ב הוא כח מתאווה חזק שאינו מוגבל ע\"פ השכל כו'."],["995","13","<b>וזהו שארז\"ל אין אדם עובר עבירה. . רוח שטות</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא פכ\"ד (ל, א</a>). ובארוכה סה\"מ תר\"ל ע' צד ואילך. המשך וככה תרל\"ז פל\"ט ואילך (ע' נג ואילך). קונ' ומעין ע' 62 ואילך. סה\"מ תרנ\"ח ע' רט ואילך. תרפ\"ג ע' קעב ואילך. תרצ\"ט ע' 125 ואילך. תש\"י ע' 114 ואילך. סה\"מ מלוקט ח\"א ס\"ע כט ואילך. ועוד."],["996","14","<b>ולכן נאמר אדם כי יקריב מכם</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380083\" data-slug=\"likkutei-torah\" data-id=\"4001380083\">לקו\"ת ויקרא ב, ב</a>. ואילך. סה\"מ תרכ\"ט ע' קכז. תרל\"ב ח\"א ע' שט. וע' שיד. סה\"מ קונטרסים ח\"ב תנ, א ואילך. סה\"מ תש\"י ע' 113-112. סה\"מ מלוקט ח\"א ע' יט-כ. אג\"ק אדמו\"ר מהוריי\"צ ח\"ג ע' שנד. לקמן המשך והחרים ד\"ה הים ראה וינוס."]]],[2000510315,"אינן מקריבים קרבן, אבל מ\"ש אדם כי יקריב מכם הכוונה הוא על ההקרבה שמקריב אדם המקריב את הקרבן מכם היינו ממנו עצמו, ונמצא פי' הפסוק אדם כי יקריב קאי על כלליות מין האנושי שנק' בשם אדם, כי יקריב מכם פי' שיהי' ההקרבה מכם עצמו ע\"י הקרבת קרבן הבהמה שמקריב, ומלת כי מתפרשת כמו כאשר כו'.\n<b>אך</b> עדיין צ\"ל למה צריכין להקריב הבהמה הגשמיות ולא די במה שמקריב נפשו הבהמית לבד, שהי' צריך לבוא לבהמק\"ד ולהתודות על כל דבר פשע שעשה ולהפוך לבו מקצה אל הקצה ותמורת האהבה לדברים גשמי' יאהוב אלקותו ית', ולמה צריכין לקרבן הגשמי להקריבו ע\"ג המזבח וכל עבודת הכהנים שחיטה וזריקת הדם והקרבת החלב שהרי לפי הנ\"ל א\"צ להקרבת הבהמה בעצם כו'.\n<b>אך</b> הענין הוא דהנה כתיב כי ה' אלקיך אש אוכלה הוא<sup data-n=\"997\">15</sup>, ולכאורה יפלא למה אנו מדמים אותו ית' לאש, ומפני מה זכתה האש יותר מכל הנבראים ע\"פ כל הא[רץ] שיתדמה הבורא ית' באש. אך הענין הוא דהנה אנו רואים שטבע יסוד האש מובדל משארי יסודות, כמו מים ועפר שטבעם הוא להיות נמשכים מגבוה לנמוך כמו המים שיורדים מגבוה לנמוך וכן העפר<sup data-n=\"998\">16</sup>, אבל האש עולה למעלה<sup data-n=\"999\">17</sup> גם בהיותו נאחז באיזהו דבר מ\"מ הוא מתלהב למעלה, שזה יורה על שבעצם אינו מתערב עם דבר אחר ומצד עצמו הי' עולה למעלה כו'. וככל המשל הזה יובן מה שכ' בו אין ערוך לך פי' שאינו ערך כלל עם כל מה שנמצא ע\"פ הארץ, פי' אין ערוך ענין הערך נופל אפי' על א' נגד אלף אלפי'<sup data-n=\"1000\">18</sup> וריבוי רבבות, שאחד הוא חלק א' נגד אלף אלפי' וריבוי רבבות, וגם היותו שוה עמו בסוג המספר, אבל לגבי אלקות הוא אין ערוך ממש. וגם שכמו האש א\"א לאחוז בו כ\"א כשיש דבר הנאחז, כך א\"א להמשיך המשכת אלקות כ\"א ע\"י תומ\"צ שבהם וע\"י יתאחז האור, שבלעדם א\"א כלל להמשיך המשכת אלקותו ית', וע\"ז נאמר כי ה' אלקיך אש אוכלה הוא, וכשם שהאש אינו מתאחז כ\"א כשהדבר שבו נאחז האור מתעכל, כן אם עשיית המצות הוא בלא ביטול כ\"א כדרך מצות אנשים מלומדה אזי לא יש בהם וע\"י המשכה כלל. וכמו שהוא בהמשכת אלקות כן הוא בכל דבר רוחני שא\"א להמשיך הדבר",[["997","15","<b>אך הענין הוא דהנה כתי' כי ה' אלקיך אש אוכלה הוא</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380186\" data-slug=\"likkutei-torah\" data-id=\"4001380186\">לקו\"ת אחרי כה, ג</a>-ד. לעיל ד\"ה לא תבערו אש פ\"ב. וש\"נ."],["998","16","<b>המים שיורדים מגבוה לנמוך וכן העפר</b>: בד\"ה זה תרנ\"ג מוסיף: ואף גם הרוח יורד למטה מחמת כבדו באויר צח יותר."],["999","17","<b>שטבע יסוד האש מובדל משארי יסודות. . עולה למעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט (כד, רע\"ב</a>). ובארוכה מאמרי אדה\"ז תקס\"ט ע' רכו ואילך. המשך מים רבים תרל\"ו ס\"ע קט-י. ועוד."],["1000","18","<b>אין ערוך לך. . ענין הערך נופל אפי' על א' נגד אלף אלפי'</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח (סז, ב</a>). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380228\" data-slug=\"likkutei-torah\" data-id=\"4001380228\">לקו\"ת אמור לה, רע\"ג</a>. מאמרי אדהאמ\"צ דברים ח\"ג ע' תתצג. וש\"נ."]]],[2000510316,"הרוחני או להעלותו אם לא ע\"י איזהו דבר אשר בהם יתאחז הדבר ההוא, ובלתי זה א\"א כלל וכלל.\n<b>ולכן</b> כאשר אנו צריכים להעלות נה\"ב שהוא דבר רוחני היינו בחי' כח המתאוה בעצם שיש באדם, אזי בלתי דבר גשם א\"א להעלותה, ולזה נצטוינו בהקרבת הקרבנות להקריב שור או שה שבהם וע\"י יתעלה נפשו הבהמית, והיינו מפני שקרובים זל\"ז ששניהם שרשן מפני שור, שהבהמות שרשן מפני שור ונה\"ב שורשה ג\"כ מפני שור רק שזהו מפני שור שבאדם שהרי יש ד' פנים לאדם, ומ\"מ הם קרובים זל\"ז, שהרי מ\"מ שניהם מפני שור, רק זהו מפני שור שבפני אדם<sup data-n=\"1001\">19</sup> וזהו מפני שור שבפני שור, ולכן ע\"י הקרבת הבהמה גשמי' עי\"ז מתעלה הנפש הבהמי' הרוחני' שבאדם שהוא בחי' כח המתאוה שבאדם להתעלות בעילוי אחר עילוי כמו הקרבן שעולה עד רזא דא\"ס, ונת' במ\"א שעליית נה\"ב שבאדם הוא עוד יותר נעלה מעליית הבהמה ע\"י הקרבן, ע' בד\"ה שה תמים זכר בן שנה (ך\"ט<sup data-n=\"1002\">20</sup>). ועכשיו בתפלה שנגד תמידים יש ג\"כ דבר הגשמי והו\"ע מצות מעשיות שתיקנו בשעת התפלה<sup data-n=\"1003\">21</sup> כמו לבישת טלית ותפילין, שהם ג\"כ ק\"ש בכתב בחי' מעשה, וגם זה\"ע ר\"א יהיב פרוטה לעני והדר מצלי שהוא בחי' מעשה הצדקה גשמי שבה יתאחז אור הרוחני דנה\"ב שיוכל להתעלות כו'.\n<b>אמנם</b> כדי שיתעלה הבהמה ועל ידה יתעלה נה\"ב שבאדם היו צריכין לסמוך הקרבן בשתי ידיו, ועי\"ז הוא הנותן כח שיוכל הבהמה להתעלות וע\"י תתעלה נה\"ב שבאדם. וכמו בנדרים שהי' צריך להדיר בדבר הנדור, וע\"י מבטא שפתיו מתעלה הדבר הנדור שיהי' גבוה יותר מהנודר עד שמוכרח לפרוש ממנו, וכמ\"ש בדרושי הנדרים<sup data-n=\"1004\">22</sup> שהבהמה בעצם היא גבוה יותר בשרשה, אך הנה היא נפלה בשבה\"כ ונשפלה למטה מטה, לכן צריך האדם שהוא גבוה יותר למטה שהרי הוא מדבר שנעלה על הבע\"ח, להוציא בשפתיו שה\"ז כעולה וכקרבן ועי\"ז מתעלה הבע\"ח. כן הוא בקרבנות ג\"כ, שהסומך שתי ידיו על הבהמה נותן כח בה שתוכל",[["1001","19","<b>שהבהמות שרשן מפני שור ונה\"ב שורשה. . רק זה מפני שור שבפני אדם</b>: בד\"ה זה תרנ\"ג שם: שהבהמה הוא מפני שור שבפני שור, והנה\"ב הוא מפני אדם שבפני שור. וכ\"ה לקמן בהמשך והחרים ד\"ה הים ראה וינוס ע' רפא: והנה\"ב שורשה מפני אדם שבפני שור. וכ\"ה בכ\"מ בדא\"ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380422\" data-slug=\"likkutei-torah\" data-id=\"4001380422\">לקו\"ת נשא שם כח, סע\"ג</a>-ד. מאמרי אדה\"ז תקע\"א ע' קעח. אוה\"ת דרושים לחה\"פ (כרך ג) ע' תשסד. תבוא ע' תתרסז. דרושים לשמע\"צ ע' א'תשפא. סה\"מ תרכ\"ט ע' קיד. וע' קכז. עטר\"ת (הוצאת תשמ\"ח) ע' תרסה. תרפ\"ז ע' מא. תרצ\"ט ע' 63. תש\"ה ס\"ע 76."],["1002","20","<b>ונת' במ\"א שעליית נה\"ב שבאדם. . יותר נעלה מעליית הבהמה. . ע' בד\"ה שה תמים. . (ך\"ט)</b>: סה\"מ תרכ\"ט ע' קיד. ד\"ה ובראשי חדשיכם תרל\"ט פ\"ב בסה\"מ תרל\"ט ח\"ב (נמצא בדפוס)."],["1003","21","<b>בתפלה. . יש ג\"כ דבר הגשמי. . והו\"ע מצות מעשיות שתיקנו בשעת התפלה</b>: בד\"ה זה תרנ\"ג מוסיף: או י\"ל דאותיות התפלה הן הדבר שע\"י מתעלה הנה\"ב דעקימת שפתיו הוי מעשה כו'."],["1004","22","<b>וכמ\"ש בדרושי הנדרים</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380647\" data-slug=\"likkutei-torah\" data-id=\"4001380647\">לקו\"ת מטות פא, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380652\" data-slug=\"likkutei-torah\" data-id=\"4001380652\">פב, ג</a> ואילך. וראה לקמן המשך והחרים ד\"ה הים ראה. וש\"נ."]]],[2000510317,"להתעלות<sup data-n=\"1005\">23</sup> ע\"י הכהן המעלה, והיינו כי אדם הוא בגימ' מ\"ה הוא הנותן כח לבהמה שהיא בגימ' ב\"ן שתוכל להתעלות<sup data-n=\"e56\">ד</sup>. ובזה יובן מ\"ש ויהושע בן נון מלא רוח חכמה כי סמך משה את ידיו עליו, ולכאורה נתינת הטעם שאו' כי סמך אינו מובן והל\"ל כי למד ממשה, או שמשה מסר לו כל' רז\"ל משה קבל תורה מסיני ומסרה ליהושע. אך הענין שלמסור דבר הרוחני צ\"ל ע\"י גשם שבה יתאחז הדבר הרוחני, ולכן ע\"י מה שאומר ולמד אותו ד\"ת, הרי הדבור הוא עדיין רוחני, לכן נאמר כי סמך משה את ידיו עליו, וע\"י הסמיכה נמסר לו כח הרוחני ג\"כ, וזה\"ע הסמיכה שהיו סמוכין איש מפי איש שהו\"ע מסירת הכח הרוחני<sup data-n=\"1006\">24</sup> ע\"י סמיכה זו. וכמו\"כ יובן בענין סמיכת הקרבן שצריך האדם בחי' מ\"ה ליתן כח להבהמה בחי' ב\"ן שתוכל לעלות<sup data-n=\"1007\">25</sup>, ואז כחה גדול שתתעלה בעילוי אחר עילוי ותגביה עמה גם נה\"ב שבאדם ג\"כ שתעלה בעילוי אחר עילוי עד רום המעלות גבוה מעל גבוה כו'. ועפ\"ז יובן ג\"כ מה שבני ישראל דוקא סומכין<sup data-n=\"1008\">26</sup> ולא בנות ישראל, להיות בני ישראל שרשם מש' מ\"ה, אבל בנות ישראל שרשם מבחי' המל', לכן בני ישראל דוקא סומכין ולא בנות ישראל כו'. וזהו וסמך כו' ועי\"ז ונרצה שעיקר המשכת הרצון עליון הוא ע\"י הקרבת נה\"ב שזהו ע\"י הקרבת הבהמה, והגורם שתוכל הבהמה הגשמיות להתעלות זהו הסמיכה של האדם בגימ' מ\"ה, ולכן ע\"י וסמך עי\"ז נעשה להיות ונרצה לו לכפר עליו.",[["1005","23","<b>שהסומך שתי ידיו על הבהמה נותן כח בה שתוכל להתעלות</b>: בד\"ה זה תרנ\"ג מוסיף: והגם שמקדש אותה בפה תחלה ואומר הרי זו עולה כו' ומה צריך עוד הסמיכה בידיו, אך הענין הוא כמשנת\"ל דהמשכת דבר צריך להיאחז בדבר גשמי, וכמו\"כ יובן כאן דבכדי להמשיך האור העליון על הבהמה הוא ע\"י הסמיכה בידיו דוקא, דהידים הם בדוגמת ע\"ס העליונות כנ\"ל."],["1006","24","<b>וזהו\"ע הסמיכה שהיו סמוכין איש מפי איש שהו\"ע מסירת הכח הרוחני</b>: ראה ביאוה\"ז לאדהאמ\"צ נה, א. סה\"מ תרל\"ג ח\"ב ע' תכז. ועוד."],["1007","25","<b>סמיכת הקרבן. . ליתן כח להבהמה. . שתוכל לעלות</b>: לקמן בהמשך והחרים ד\"ה הים ראה וינוס הנ\"ל מוסיף: וענין הסמיכה בנפש האדם זהו\"ע לימוד התורה שקודם התפלה שהתורה היא בחי' עוז ותושי' שנותנת כח בנה\"א ומתשת כח הנה\"ב. ע\"כ. עיי\"ש עוד בזה. וראה גם ד\"ה וסמך את ידו בסה\"מ תרנ\"ג שם."],["1008","26","<b>מה שבני ישראל דוקא סומכין. . שרשם משם מ\"ה, אבל בנות ישראל שרשם מבחי' המל'</b>: בד\"ה זה תרנ\"ג מבאר זה: דבני ישראל הם בחי' מ\"ה שנמשך משם הכח לעלות, משא\"כ בנות ישראל הם בחי' מל' שזהו בחי' שם ב\"ן המתעלה כו'.\n\n<b>ד</b>  <b>אדם הוא בגימ' מ\"ה הוא הנותן כח לבהמה. . ב\"ן שתוכל להתעלות</b>: בשולי הגליון נרשם בגוכי\"ק: וענין המ\"ה שנותן כח בב\"ן צ\"ל ג\"כ ע\"י דבר גשמי, י\"ל שזהו כח האדם העושה המצוה שאז היא נעשית מצוה, וזהו ע\"י עשיי' גשמי' דוקא שאם הרהר לא עלתה כלום כו'."]]],[2000510318,"<h3>אור לי\"ד בודקין כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ צו [שבת הגדול], ל\"א).</b>\n<b></b>הדר קבלוה בימי אחשורוש כו' האבות ומ\"ת\n[צו, שבת הגדול]\n<b>אור</b> לארבעה עשר<sup data-n=\"1009\">1</sup> בודקין את החמץ, המעיין בספרי המקובלים יראה שסוד בדיקת החמץ הוא בכדי שיהי' אח\"כ כלי לקבל כו'. ובמאו\"א אות ב' ס\"ה כל בדק<sup data-n=\"1010\">2</sup> הוא מצד אחיזת החיצון שם<sup data-n=\"1011\">3</sup>, וצריך לחזק הבדק שלא יתאחז שם<sup data-n=\"1012\">4</sup>, וזהו סוד בדיקת החמץ לבדוק ביסוד דנוק' אם יש ח\"ו לאיזה חיצון אחיזה בגבורות אשר שם כו', כי הבדיקה היא אם נמצא דם שהוא בחי' גבורות שמזה יכול להיות יניקה לחיצונים, וע\"י הבדיקה מתברר שאין שם יניקה לחיצון ונעשית עי\"ז כלי לקבל<sup data-n=\"1013\">5</sup>. וכמשל דירת המלך צריכה שתהי' מנוקה מכל צואה ולכלוך, כ\"ש שבכדי להיות המשכה פנימיות בחי' ביום חתונתו זה מתן תורה, זהו שנצטוינו לבדוק החמץ קודם הפסח בכדי שיהיו נש\"י נקיים מכל חימוץ הוא בחי' הגבורות קשות בכדי שיהיו כלי לקבל וכענין הפסק טהרה כו'. והוא כענין מ\"ש וקבל היהודים שנעשו כלי לקבל בחי' תורה<sup data-n=\"1014\">6</sup>, משא\"כ בשעת מ\"ת אף שפסקה זוהמתן אבל לא הי' נפסק",[["1009","1","<b>אור לארבעה עשר</b>: מיוסד והגהות על ד\"ה זה להצ\"צ משנת תרט\"ז שנמצא בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש בכת\"י 1029 נז, א ואילך [כולל הנחות אדמו\"ר מהר\"ש ממאמרי הצ\"צ משנת תרט\"ז]. מאמר הצ\"צ (מלבד ההתחלה וסיום) מיוסד על ד\"ה וקבל היהודים בתו\"א מגילת אסתר צו, ג ואילך. ונו\"א ממאמר ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א</a> בס' מאמרי אדה\"ז תקס\"ו ע' קכו ואילך. [וראה גם בהביאור לד\"ה וקבל בתו\"א מג\"א שם צז, א ואילך. מאמרי אדה\"ז תקס\"ו שם ע' קנב ואילך]. ובארוכה ד\"ה וקבל היהודים בשערי אורה פו, ב ואילך. וראה בארוכה הגהות לד\"ה וקבל באוה\"ת מגילת אסתר (הוצאת תש\"נ) ע' קעא ואילך. קעט ואילך. קפה. וד\"ה וקבל בפלח הרמון שמות ע' שצה ואילך [והוא הנחת הר\"ה מפאריטש ממאמר הצ\"צ מפורים תרט\"ז].\nהמאמר נמצא בשינויים והוספות בד\"ה זה משבת הגדול תרס\"ו בסה\"מ ליקוט ח\"ג ע' נ ואילך. חלקו הראשון של המאמר נת' בארוכה בד\"ה זה בסה\"מ עזר\"ת ע' קמב ואילך. [שם לא נגמר המאמר בגוכי\"ק]. ובד\"ה זה בסה\"מ תרצ\"ד (נמצא בדפוס) [מיוסד על חלקו הראשון של ד\"ה עזר\"ת].\nלהתחלת וסיום המאמר (על המשנה: אור לארבעה עשר) ראה הגהות לד\"ה וקיבל היהודים באוה\"ת מג\"א שם ע' קפד-ה. וראה גם ד\"ה אור לארבעה עשר: תער\"ג בסה\"מ תער\"ב-ע\"ו ע' רטז. — וראה עוד על מארז\"ל אור לארבעה עשר בד\"ה זה בסה\"מ עטר\"ת ע' שמג-ד. וע' שנ-נא. הש\"ת ע' 38-37. וע' 42. סה\"ש תרח\"ץ ע' 265. הגש\"פ עם לקוטי טעמים ומנהגים ע' ב-ג."],["1010","2","<b>ובמאו\"א. . כל בדק</b>: הובא ונת' באוה\"ת מג\"א שם ע' קפד. ד\"ה זה תרס\"ו עזר\"ת ותרצ\"ד שם. וראה גם סה\"מ עטר\"ת שם ע' שנ."],["1011","3","<b>כל בדק הוא מצד אחיזת החיצון שם</b>: בד\"ה זה עזר\"ת שם מוסיף כאן הגה\"ה: (דבדק היינו קלקול ושבר, והוא מאחיזת החיצונים כו'). ע\"כ. וראה גם ד\"ה זה תרצ\"ד שם."],["1012","4","<b>וצריך לחזק הבדק שלא יתאחז שם</b>: בד\"ה זה עזר\"ת מוסיף: וצריכים לחזק את הבדק להסיר את אחיזת החיצונים ויהי' כלי שלימה, וז\"ס בדיקת חמץ כו' דחמץ הוא היצה\"ר ונה\"ב וכמ\"ש מכף מעול וחומץ, וצריכים לבער את החמץ בכדי להיות כלי לקבל."],["1013","5","<b>וע\"י הבדיקה מתברר. . ונעשית עי\"ז כלי לקבל</b>: בד\"ה זה עזר\"ת מוסיף כאן: ומהו כלי הוא בחי' הביטול וכמאמר כלי מלא אינו מחזיק, כשהוא מלא ברצונות זרות זה אני רוצה וזה אין אני רוצה זה אני יכול כו', והסיבה לזה הוא ישות וחומריות הנה\"ב כו' וכמ\"ש במ\"א, וצ\"ל כלי ריקן בביטול כל הרצונות זרות ואז הוא כלי לקבל כו', וז\"ע ביעור חמץ והוא ע\"י הבדיקה כו'. ונת' בארוכה בד\"ה זה תרצ\"ד שם."],["1014","6","<b>והוא כענין מ\"ש וקבל היהודים שנעשו כלי לקבל בחי' תורה</b>: בהבא לקמן עד סוף הפיסקא ראה בהביאור לד\"ה וקיבל היהודים ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370438\" data-slug=\"torah-or\" data-id=\"3901370438\">תו\"א מג\"א שם צח, א</a>."]]],[2000510319,"בשלימות, והמופת ע\"ז הוא מחטא העגל כמשי\"ת. וכן מצינו בד' מדות שבתלמידים משפך כו' שמכניס בזו ומוציא בזו שאינו קולט היטב השפע אשר נמשך לו מאת רבו ואינו עומד על תוכן ואמיתות הדברים לכן נק' משפך שמכניס בזו ומוציא בזו, אבל רבי אליעזר בן הורקנוס בור סוד שאינו מאבד טפה והיינו שהי' כלי לקבל ההשפעה מאת רבו ולא הי' מאבד טפה. וכן ארז\"ל משרבו תלמידי שמאי והלל שלא שמשו כל צרכן רבו מחלוקת בישראל, והיינו מפני שלא שמשו כל צרכן שלא היו בבחי' כלי קיבול לקבל השפע מאת רבן בתוכן ועמקיות הדברים לכן רבו מחלוקת בישראל, שזה קיבל כך לפי השגתו וזה קיבל כך כו', אבל אם היו משמשין כל צרכן היו עומדים על תוכן ועמקות כוונת רבן לא הי' מחלוקת כ\"כ<sup data-n=\"1015\">7</sup>, וכמו דורות הראשונים שארז\"ל באבות משה קיבל תורה מסיני ומסרה ליהושע ויהושע לזקנים כו' יוסי בן יועזר קיבל מהם כו' שקיבלו התורה כמו שהיא כו', שזהו כמו וקבל היהודים שנעשו בחי' כלי לקבל כו' וכמשי\"ת אי\"ה.\n<b>ולהבין</b> זה הנה נודע שגלות מצרים הי' הקדמה למ\"ת, שכדי שיוכלו ישראל לקבל את התורה הוצרכו תחלה לצרף בכור הברזל דמצרים, וא\"כ צריך להבין מהו שארז\"ל ע\"פ החלו לעשות שבמ\"ת הוא רק החלו לעשות שאמרו נעשה ונשמע כו' הדור קבלוה בימי אחשורש, ולהבין זה איך מה שבמ\"ת שעל כל דיבור פרחה נשמתן הי' רק החלו לעשות<sup data-n=\"1016\">8</sup> ובימי אחשורש קבלוה כו', וצריך להבין ענין מ\"ת<sup data-n=\"1017\">9</sup>. הנה ארז\"ל קיים אברהם כל התורה כולה עד שלא ניתנה שנאמר עקב אשר שמע אברהם בקולי וישמור משמרתי כו' וא\"כ מה הי' החידוש במ\"ת מאחר שאברהם קיימה קודם מ\"ת כו', וגם צ\"ל איך קיים אברהם כל התורה קודם מ\"ת שלא הי' עדיין בחי' המצות כו'. וגם לא הי' אפשר עדיין להיות שהרי איך קיים מצות תפילין שכ' בה ענין יצ\"מ ועדיין לא הי' שעבוד מצרים. ומה שלכאורה יש להקשות הלא אלפים שנה קדמה תורה לעולם ואיך נאמר שם כל הציוויים לבנ\"י קודם שהי' מציאותם שהרי לא הי' עולם, ואם כי על נש\"י י\"ל שעלו במחשבה הקדומה מ\"מ הלא נאמר בתורה סיפור מצרים וכדומה, אך זהו הי' אצלו ית' כמ\"ש ואהי' אצלו שעשועים יום יום ויומו של הקב\"ה אלף שנה וא\"כ אין זה שייך לברה\"ע, אבל אברהם אינו מובן איך קיים כל התורה כולה עד שלא ניתנה. אך",[["1015","7","<b>משרבו תלמידי שמאי והלל. . רבו מחלוקת. . אבל אם. . היו עומדים על תוכן ועמקות כוונת רבן לא הי' מחלוקת כ\"כ</b>: בד\"ה זה עזר\"ת מציין כאן: ”עמ\"ש בדרוש בשעה שהקדימו בתחילתו\". ראה המשך בשעה שהקדימו תער\"ב ח\"א ס\"ע כ ואילך. וראה גם מאמרי אדה\"ז תקס\"ז ע' רפה ואילך. על פרשיות התורה ח\"ב ע' תשכג-ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470091\" data-slug=\"or-hatorah-hb\" data-id=\"8316470091\">אוה\"ת בשלח ע' תקנז</a> ואילך."],["1016","8","<b>ולהבין זה איך מה שבמ\"ת שעל כל דיבור פרחה נשמתן הי' רק החלו לעשות</b>: בד\"ה וקיבל היהודים במאמרי אדה\"ז תקס\"ו שם: הנה יפלא מאמר זה מאד איך יתכן שבשעת מ\"ת שעל כל דיבור ודיבור פרחה נשמתן לא הי' רק התחלה. ובד\"ה וקבל בשערי אורה שם פח, ב: וזה פלא גדול. ובסה\"מ תרפ\"ז ע' קי ובסה\"מ מלוקט ח\"א ע' שיז: דלכאורה הוא דבר נפלא. [נת' בסה\"מ מלוקט ח\"א שם]. ובסה\"מ מלוקט ח\"ג ע' סז וח\"ו ע' קלא: שלכאורה הוא דבר פלא."],["1017","9","<b>וצריך להבין ענין מ\"ת, הנה ארז\"ל קיים אברהם כל התורה כולה</b>: בהבא לקמן ראה בארוכה לעיל ד\"ה וכל העם ע' קסג ואילך. וש\"נ."]]],[2000510320,"הענין הוא דהנה באברהם כתיב הלוך ונסוע הנגבה שהי' תמיד בבחי' הלוך ונסוע, הלוך בחי' רצוא, ונסוע בבחי' שוב<sup data-n=\"1018\">10</sup> ע\"ד והחיות רצוא ושוב כו', והנה פי' רצוא ושוב הוא במקום אשר א\"א לידבק שם בבחי' השגה גמורה ודביקה כ\"א בבחי' רצוא ושוב<sup data-n=\"1019\">11</sup> דוקא, והוא מצד בחי' סוכ\"ע, אבל בבחי' ממכ\"ע<sup data-n=\"1020\">12</sup> שם יכול להגיע האדם ולדבוק נפשו באהוי\"ר כו', שזהו ענין עילה ועלול שהעילה דבוקה בעילתו כו', אבל בבחי' סוכ\"ע א\"א להיות בבחי' השגה כ\"א ע\"ד רצו\"ש דוקא, וע\"י רצו\"ש זה ממשיך החיות מלמעלה ג\"כ בבחי' מטי ולא מטי להיות כי גם החיות הזה הבא מלמעלה א\"א להתיישב בכלי כ\"א בדרך מטי ולא מטי כמבואר בכתהאריז\"ל.\n<b>וביאור</b> הענין הנה כתיב יהללו את שם הוי' כי הוא צוה ונבראו<sup data-n=\"1021\">13</sup>, וצ\"ל מ\"ש כאן ונבראו ולא כתב ברא כמ\"ש בראשית ברא אלקים, והיינו כי ברא הוא בחי' כח הפועל בנפעל זהו שייך בבחי' שם אלקים שהוא בחי' השתלשלות החיות בבחי' עו\"ע בחי' ממכ\"ע, ולכן שייך בחי' ברא והיינו שהוא בחי' כח הפועל בנפעל, ובחי' זו שייך על בחי' ש' אלקים שהוא ל' כח כמו ואת אילי הארץ לקח והיינו בחי' כח הפועל בנפעל, אבל מבחי' שם הוי' הוא ונבראו ממילא שאינו מתלבש בבחי' זו בבחי' ברא בכח הפועל בנפעל כ\"א ממילא. ואף ששם הוי' הוא ג\"כ רק שם והארה מאתו ית' כי עצמותו ית' מובדל ומרומם מגדר עלמין, ושם הוי' הוא רק שם והארה מאתו ית', אבל מ\"מ אפי' בבחי' שמו ית' שהוא ש' הוי' אינו שייך לומר בחי' ברא כ\"א ונבראו ממילא ומאליו כו' (והיינו מפני ששם הוי' הוא שם העצם משא\"כ שאר השמות הם כינויים כו') והוא בחי' סוכ\"ע. והנה בבחי' זו צ\"ל בדרך רצוא ושוב כי א\"א לידבק שם שיתיישב האור בכלי כ\"א בדרך רצו\"ש דוקא, שצ\"ל תחלה הרצוא ואח\"כ השוב וחוזר חלילה כו', ובן עזאי הציץ ומת היינו שהי' אצלו הרצוא בלא השוב והציץ במקום שא\"א להגיע לשם בבחי' רצוא כ\"א בבחי' שוב דוקא, לכן מת שהוא בחי' הסתלקות החיות בבחי' א' הוא בחי' רצוא לבד, אבל ר\"ע נכנס בשלום ויצא בשלום שהי' בבחי' רצו\"ש<sup data-n=\"1022\">14</sup>, וזה הי' מדרגת אאע\"ה שהי' תמיד בבחי' רצו\"ש.\n<b>וזשארז\"ל</b> קיים אברהם אבינו כל התורה כולה עד שלא ניתנה, כי התורה היא נק' תורת הוי' מצות הוי', והיינו שע\"י התומ\"צ ממשיכים בחי' ש'",[["1018","10","<b>הלוך ונסוע הלוך בחי' רצוא ונסוע בבחי' שוב</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370327\" data-slug=\"torah-or\" data-id=\"3901370327\">תו\"א יתרו עג, ד</a>."],["1019","11","<b>במקום אשר א\"א לידבק. . כ\"א בבחי' רצוא ושוב</b>: ראה בהביאור לד\"ה וקבל בתו\"א מג\"א שם צז, א: ההמשכה מבחי' זו שלמע' מהשתל' א\"א שיהי' נמשך כ\"א בבחי' רצוא ושוב."],["1020","12","<b>רצוא ושוב. . מצד בחי' סוכ\"ע אבל בבחי' ממכ\"ע</b>: ראה בארוכה בד\"ה זה עזר\"ת שם ע' קמד ואילך ההפרש בין רצו\"ש דממכ\"ע ורצו\"ש דסוכ\"ע. וראה גם סה\"מ תרס\"ה ע' רכז ואילך. תשי\"א-י\"ג ע' 33 ואילך. ועוד."],["1021","13","<b>הנה כתי' יהללו את שם הוי' כי הוא צוה ונבראו. ֿ. ונבראו ולא כתב ברא</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a> ואילך. סה\"מ תרכ\"ט ע' קלה ואילך. תרל\"ב ח\"א ע' כ ואילך. וע' כח ואילך."],["1022","14","<b>ובן עזאי הציץ ומת. . הרצוא בלא השוב. . אבל ר\"ע נכנס בשלום ויצא בשלום. . בבחי' רצו\"ש</b>: ראה בכ\"ז אוה\"ת ויקרא (כרך ב) ע' תקמ. סה\"מ תרמ\"ט ע' רנט ואילך. תשכ\"ב ע' רב. וע' רז ואילך. לקו\"ש ח\"ג ע' 990 [ובהע' 12-11 שם]."]]],[2000510321,"הוי' הסוכ\"ע, ואברהם המשיך בחי' זו בבחי' רצו\"ש שהוא כללות התומ\"צ, שכללות התומ\"צ הוא בחי' רצו\"ש, וכמו באדם הנה יש רמ\"ח אברים ושס\"ה גידים, וכללות חיות האדם הוא במוח ולב, ונודע כי לב הוא בחי' רצוא ומוח הוא בחי' השוב, א\"כ כללות החיות דאדם הוא רצו\"ש. וכך יובן בכללות התומ\"צ שהוא בחי' זאת התורה אדם כלליות כולם הוא ג\"כ בחי' רצו\"ש, ואברהם הי' תמיד ברצו\"ש זהו מה שקיים אברהם כל התורה כולה עד שלא ניתנה. אך הנה אברהם הי' יכול להיות תמיד ברצו\"ש מפני שנשמתו היתה כלי להיות תמיד ברצו\"ש, ולא כל האדם זוכה לבחי' זה<sup data-n=\"1023\">15</sup>. וזהו מעלת מ\"ת שניתנה התומ\"צ שבהם וע\"י נמשך בחי' זו, מפני כי התומ\"צ הם כלים להמשכה זו, והיינו כי מצות עשה הם בחי' רצוא שזהו שאנו מברכים אשר קדשנו במצותיו שהוא בחי' דביקה בבחי' רצוא, וכמו מי שעושה איזה מצוה הנה בשעה שהוא עושה המצוה הוא רץ לעשות רצון קונו והרי הוא כמו בחי' הרצוא כו', ומל\"ת הוא בחי' השוב כנודע ממ\"ש במ\"א מענין מל\"ת שגבוהים ממ\"ע, והוא כי א\"א להגיע לבחי' זו כ\"א ע\"י לא דוקא<sup data-n=\"1024\">16</sup>, כך בבחי' השוב שא\"א להגיע לבחי' זו בבחי' רצוא כ\"א בבחי' ביטול השוב כו'. וזהו ענין נעשה ונשמע שהי' במ\"ת שהקדימו נעשה לנשמע, כי פי' נשמע הוא בחי' המשכת האורות כי נשמע הוא לשון אסיפה וקיבוץ מלשון וישמע שאול כו', ונעשה הוא בחי' הכלי לקבל האור כי א\"א להיות האור בלא כלי, כמובן מענין יסוד האש עד\"מ שהוא הגבה למעלה מכל הד' יסודות תחת גלגל הירח ואעפ\"כ אינו מאיר בלילה לפי שהאור הבא ממנו אינו מאיר אא\"כ יש איזה דבר למטה שנאחז בו ודולק כמו פתילה ואחר שכלה ונשרפה הפתילה מסתלק האור כו'. וזהו ולא עם הארץ חסיד כי מפני שהוא עם הארץ אינו כלי לקבל בחי' אור זה<sup data-n=\"1025\">17</sup> כו' כי האור צ\"ל בכלי דוקא. וכמו שמצינו באלישע כתיב ויאמר הגישה אלי עוד כלי ותאמר אין עוד כלי ויעמוד השמן<sup data-n=\"1026\">18</sup>, כי מפני שלא הי' בחי' כלי נסתלק האור כו'. ועוד זאת שהכלים דתומ\"צ נק' איברים שאינו דומה לשאר כלים כו', והיינו שממשיכים האור שזהו ענין רמ\"ח פקודין רמ\"ח אברין דמלכא כמו שאבר האדם ממשיך חיות הנפש, כמו העין ממשיך שישרה בה כח הראי', משא\"כ בלא העין הנה כח הראי' מסתלק בשרשו בבחי' הנפש, והעין הוא הוא הממשיך בחי' כח הראי' כמ\"ש במ\"א<sup data-n=\"1027\">19</sup> כך התומ\"צ הם כלים",[["1023","15","<b>אברהם. . שנשמתו היתה כלי להיות תמיד ברצו\"ש ולא כל האדם זוכה לבחי' זה</b>: בתו\"א מג\"א שם צו, ג: מעלת אברהם היתה גדולה מאד מצד שרש נשמתו ולא כל האדם זוכה לזה."],["1024","16","<b>כנודע ממ\"ש במ\"א מענין מל\"ת שגבוהים ממ\"ע. . ע\"י לא דוקא</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380053\" data-slug=\"likkutei-torah\" data-id=\"4001380053\">לקו\"ת פקודי ג, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380067\" data-slug=\"likkutei-torah\" data-id=\"4001380067\">ו, ד</a> ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380455\" data-slug=\"likkutei-torah\" data-id=\"4001380455\">לקו\"ת בהעלותך לו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381125\" data-slug=\"likkutei-torah\" data-id=\"4001381125\">ברכה צט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381157\" data-slug=\"likkutei-torah\" data-id=\"4001381157\">שה\"ש ז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381310\" data-slug=\"likkutei-torah\" data-id=\"4001381310\">מה, ג</a>. סה\"מ תרל\"ד ע' פא-ב. ועוד."],["1025","17","<b>וזהו ולא עם הארץ חסיד כי. . אינו כלי לקבל בחי' אור זה</b>: ראה תו\"א מג\"א שם צו, סע\"ג: וזהו ולא עם הארץ חסיד, חסיד הוא בעל מדת האהבה, והיא היא בחי' אור (כי ב\"פ אור בגימ' ואהבת), וא\"א להיות גילוי אור האהבה כ\"א שיהי' בחי' כלי למטה שיתפעל בו, ובחי' כלי זו הוא ע\"י תומ\"צ, משא\"כ עם הארץ. — וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381016\" data-slug=\"likkutei-torah\" data-id=\"4001381016\">לקו\"ת האזינו עג, ב</a>."],["1026","18","<b>וכמו שמצינו באלישע. . אין עוד כלי ויעמוד השמן</b>: ראה בכ\"ז בביאור לד\"ה וקבל בתו\"א מג\"א שם צז, ב."],["1027","19","<b>שהכלים דתומ\"צ נק' איברים. . שאבר האדם ממשיך חיות. . כמ\"ש במ\"א</b>: ראה מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' סד. סט. סה\"מ תרל\"ג ח\"ב ע שנ-נא. [ובהנסמן שם בתחילת המאמר]."]]],[2000510322,"להמשכת האור כו'. ועוי\"ל שמחמת ששורש הכלים הם מבחי' תהו שקדם לתיקון רק שנפלו בשבירה, ולכן כאשר מתבררים יש בהם כח להמשיך האור כמו המאכל שמחי' את האדם כו' כמ\"ש במ\"א. וזהו יביאו לבוש מלכות שהוא בחי' לבוש דתורה<sup data-n=\"1028\">20</sup> שהתורה היא בחי' כלי ולבוש להמשכת אוא\"ס כמ\"ש עוטה אור כשלמה כו'.\n<b>ולהיות</b> כי יצ\"מ הוא הקדמה למ\"ת לכן כמו במ\"ת כתיב כי תרכב על סוסיך כן ביצ\"מ נאמר לסוסתי ברכבי פרעה. ולהבין ענין בחי' הסוס צ\"ל שורש ענין סוסיך דמ\"ת שתיבת סוסיך סובל פי' סוס אחד, וגם סוסיך משמע ל' רבים ומיעוט רבים שנים, והיינו שבסוס אחד יש ב' בחי' והיינו כי סוס גימט' ב' פעמים ס\"ג, וכמארז\"ל ששה דברים נאמרו בסוס דעתו גסה עליו ג\"ס אותיות ס\"ג כו'. ולהבין ענין ב' פעמים ס\"ג, הנה כתיב כי גאה גאה<sup data-n=\"1029\">21</sup> ות\"י אתגאי על גיוותניא, פי' שהוא ית' מתגאה ומסלק אורו מן הגיאים, כי הנה פי' גיאים שמתגאי' א\"ע לקבל יניקה ממקום גבוה בחי' ורב חסד שזהו מ\"ש אם תגביהי כנשר<sup data-n=\"1030\">22</sup> אעפ\"כ משם אורידך, כי גבוה מעל גבוה כו' שהוא ית' מתגאה על גיוותניא שמסלק אורו מהם לבלתי תת להם יניקה וממילא נופלים כו', והסתלקות אורו ית' הוא בבחי' בינה דרור עלמא דחירו (פי' ג\"ר דכתר) שמבחי' בינה לא יש יניקה לחיצוני', כי שבה\"כ הי' בז\"ת דס\"ג<sup data-n=\"1031\">23</sup> דהיינו בבחי' מדות, וכמו באדם הנה מהידים שהם מדות צומחים צפרנים ובצפרנים הוא אחיזת הקליפות כמ\"ש בזהר בטופראי אחידין כו'. אבל מבחי' ג\"ר דבינה אינם יכולים לקבל שלכן נק' דרור בחי' בן חורין, וכמשארז\"ל ע\"פ חרות על הלוחות א\"ת חרות אלא חירות שהקליפות אינם יכולים לקבל יניקה מהם, וזהו מ\"ש אשריך ארץ שמלכך בן חורין כו'. וזהו כי גאה גאה שמתגאה מן הגיאים היינו הקליפות וסט\"א שמתגאי' לקבל יניקה והוא ית' מתגאה עליהם ומסלק אורו ית' למקום אשר א\"א לקליפות לקבל משם וממילא הם נופלים כו', וזהו משפיל גיאים עדי ארץ, והוא פעם אחד ס\"ג, כי ס\"ג לשון גס שמתגאה מן הגיאים כו'.\n<b>והנה</b> בחי' כי גאה גאה זה מתלבש במי שהוא דכא ושפל רוח דוקא, וכמ\"ש מרום וקדוש אשכון את דכא ושפל רוח, פי' מה שהוא בחי' מרום וקדוש במי הוא מתלבש במי שהוא דכא ושפל רוח דוקא כמ\"ש בזהר דיורא דקוב\"ה במאנין",[["1028","20","<b>וזהו יביאו לבוש מלכות. . לבוש דתורה</b>: ראה תו\"א מג\"א שם צו, ד: אך על ענין המשכה זו נאמר יביאו לבוש מלכות וסוס אשר רכב עליו המלך והלבישו את האיש וגו', והענין כי הנה לבוש מל' היינו בחי' תומ\"צ כו', והמשכת בחי' לבוש זה שיהי' התלבשות אוא\"ס ב\"ה בתומ\"צ במעהמ\"צ וקיומן בפועל ממש הוא ע\"י בחי' סוס וכמ\"ש גבי מ\"ת כי תרכב על סוסיך מרכבותיך ישועה [כדלקמן בפיסקא שלאח\"ז]. וראה לעיל ע' קלו (בשוה\"ג)."],["1029","21","<b>ולהבין ענין ב\"פ ס\"ג. . כי גאה גאה</b>: בהבא לקמן ראה גם אוה\"ת וירא צה, ב."],["1030","22","<b>שמתגאי'. . לקבל יניקה ממקום גבוה. . אם תגביהי כנשר</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח כו, ב</a>. הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370452\" data-slug=\"torah-or\" data-id=\"3901370452\">תו\"א ויחי קב, סע\"ב</a> ואילך. סה\"מ תרל\"ב ח\"א ע' נג ואילך. ובכ\"מ."],["1031","23","<b>שמבחי' בינה לא יש יניקה. . שבה\"כ הי' בז\"ת דס\"ג</b>: ראה בהביאור לד\"ה וקבל בתו\"א מג\"א שם צז, ג."]]],[2000510323,"תבירין, וכמ\"ש במד\"ר ר\"פ צו הקב\"ה תשמישו בכלים שבורים לב נשבר ונדכה כו', שדוקא במי שהוא לב נשבר ונדכה מתלבש בו בחי' מרום וקדוש, כי כל הגבוה ביותר יכול להשפיל עצמו למקום נמוך ביותר<sup data-n=\"1032\">24</sup> כו', שלכן במצרים כתיב אני ולא מלאך<sup data-n=\"1033\">25</sup> כו', ובמקום גדולתו אתה מוצא ענוותנותו, ואדרבה דוקא במי שהוא דכא ושפל רוח, שזהו מ\"ש מי אל כמוך נושא עון כו' לשארית נחלתו למי שמשים עצמו כשיריים דוקא, וכמ\"ש במ\"א שבחי' גדולתו ית' אינו יכול להיות נמשך כ\"א במי שהוא שפל רוח דוקא<sup data-n=\"1034\">26</sup>, כי בבחי' גס הרוח אינו יכול להיות נמשך בחי' גדולתו ית' שזהו היפך כו', כ\"א דוקא במי שהוא שפל רוח בחי' ביטול, ולכן השראת אוא\"ס ב\"ה בחכ' דוקא<sup data-n=\"1035\">27</sup> כו'. וזהו בחי' ס\"ג הב', והיינו כי ס\"ג המילוי הוא ג' יודי\"ן ואל\"ף אחד, והיינו כי אל\"ף הוא בחי' פלא בחי' כתר לכן הוא נמשך בבחי' שפל רוח המגביהי כו'. וזהו ב' פעמים ס\"ג, הא' בבחי' העלאה מלמטלמ\"ע בחי' הסתלקות מן הגיאים, והב' הוא בחי' המשכה<sup data-n=\"1036\">28</sup> אשכון את דכא ושפל רוח. וזהו ב' בחי' דתורה ותפלה, תפלה הוא בחי' העלאה מלמטלמ\"ע הוא כמו בחי' ס\"ג שמלמטלמ\"ע שמתגאה על הגיאים, ותורה הוא בחי' המשכה מלמעלמ\"ט בחי' ס\"ג שמלמעלמ\"ט.\n<b>וזה</b> הי' במ\"ת כי תרכב על סוסיך כו', אכן במ\"ת הי' עדיין החלו לעשות, וגמר הקבלה הי' בימי אחשורש, והיינו כי במ\"ת עדיין לא פסקה זוהמתן לגמרי לכן חזרו וחטאו, וגם בכל ימי הנביאים והשופטים היו ישראל מרופין פעם כך ופעם כך כו', והיינו מפני שלא היו עדיין בחי' כלי לקבל האור דתורה שלא היו נקיים מזוהמת הנחש עדיין, משא\"כ בימי אחשורש חזרו וקיבלוה והיינו מפני המס\"נ שהי' אצלם בפו\"מ כל השנה<sup data-n=\"1037\">29</sup> מגזירת המן הרשע, הנה ע\"י המס\"נ נזדככה הכלי שלהם כמו ע\"ד לע\"ל, לכן היו בבחי' כלי לקבל בחי' התורה. וזהו מ\"ש במד\"ר גדולה הסרת טבעת",[["1032","24","<b>כי כל הגבוה ביותר יכול להשפיל. . למקום נמוך ביותר</b>: ראה בארוכה לעיל ד\"ה זאת חוקת. וש\"נ."],["1033","25","<b>שלכן במצרים כתי' אני ולא מלאך</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380126\" data-slug=\"likkutei-torah\" data-id=\"4001380126\">לקו\"ת צו יב, ג</a>. סידור עם דא\"ח רצט, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' תמב. סה\"מ תרל\"ב ח\"א ע' רפח. סה\"מ תש\"ה ע' 150. ועוד."],["1034","26","<b>לשארית נחלתו. . כשיריים דוקא וכמ\"ש במ\"א שבחי' גדולתו ית'. . נמשך. . שפל רוח דוקא</b>: ראה סה\"מ תרכ\"ו ע' שג ואילך. תרכ\"ז ע' קצח ואילך. [ובהנסמן שם בתחילת המאמר]. רג-ד. תמב ואילך. [ובהנסמן שם בתחילת המאמר]. תמז. תנא. תר\"ל ע' קצו, קצט. רג ואילך. ועוד."],["1035","27","<b><a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">ולכן השראת אוא\"ס ב</a>\"ה בחכ' דוקא</b>: ראה תניא פל\"ה בהגה\"ה (מד, סע\"ב)."],["1036","28","<b>וזהו ב\"פ ס\"ג הא' בבחי' העלאה מלמטלמ\"ע. . והב' הוא בחי' המשכה</b>: ראה תו\"א מג\"א שם צו, ד: סוס הוא בגימט' ב\"פ גס כו', והנה ענין הסוס הוא שמוליך לרוכבו למקום שאין יכול להגיע לשם מצ\"ע, ויש בזה ב' בחי', שמעלהו הרים גדולים, ומורידו בקעות גדולות, כך הנה יש בבחי' ביטול זה ב' בחי', ממטלמ\"ע למקום שאין יניקה ואחיזה לסט\"א עלמא דחירות כו' וממעלמ\"ט להיות נמשך גילוי בחי' ביטול זה למטה כו'. וראה גם לקמן בהמשך המאמר פיסקא: ועפ\"ז נבין ענין מ\"ש ביצ\"מ. — וראה אוה\"ת מג\"א ע' קעו וע' קפא שב' בחי' אלו מלמטלמ\"ע ומלמעלמ\"ט הו\"ע רצוא ושוב שנת\"ל שנעשה ע\"י המצות. עיי\"ש."],["1037","29","<b>המס\"נ שהי' אצלם בפו\"מ כל השנה</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א מג\"א שם צז, א</a>: מסרו עצמן למות כל השנה כולה. ועד\"ז הוא בשערי אורה שם צ, ב. ובסה\"מ עטר\"ת ע' שו. תרפ\"א ע' קצא. תש\"ח ע' 118. ובכ\"מ בדא\"ח. נת' בסה\"מ מלוקט ח\"א ע' שיט. ח\"ב ס\"ע ער-רעא. וראה הוספות לתו\"א מג\"א קכ, ד: כמעט משך שנה."]]],[2000510324,"ממ\"ח נביאים<sup data-n=\"1038\">30</sup> שעמדו לישראל שהרי בעת הנביאים היו ישראל מרופפים עדיין שלא פסקה זוהמתן לגמרי, אבל בימי אחשורש קבלוה שהיו בבחי' כלי לקבל כו'. ואפ\"ל פי' וקבל היהודים כי הנה התורה היא בחי' רצו\"ש כנ\"ל מ\"ע בחי' רצוא ומל\"ת בחי' שוב, ובימי אחשורש קיבלוה, פי' שנתיישבה אצלם התורה בבחי' כלי ולא הי' בבחי' רצו\"ש שהוא מפני שא\"א להתיישב בכלי כנ\"ל לכן הוא בבחי' רצו\"ש, אכן ע\"י המס\"נ בפו\"מ נתיישבה אצלם בבחי' כלי גם בבחי' השוב, דוגמת כמו לע\"ל שכתיב כי עין בעין יראו שיושג כל התורה בבחי' השגה גמורה ולא בבחי' רצו\"ש לבד. אך זה הי' הוראת שעה כ\"א בימי אחשורש, אך אח\"כ הי' בבחי' רצו\"ש, שלכן נק' יהודים, פי' וענין יהודים, להיות כי יש ב' בחי' ברכה והודאה, ברכה הוא בחי' המשכה כו', והנה הברכה הוא רק בבחי' שמך כמ\"ש ומברכי' את שמך, ע' בד\"ה ויהיו חיי שרה (ל\"א)<sup data-n=\"1039\">31</sup>, אבל בחי' הודאה הוא כמ\"ש מודים אנחנו לך לעצמותו ית', ולכן נק' יהודים ע\"ש שהיו בבחי' ביטול לעצמותו ית'.\n<b>ועפ\"ז</b> נבין ענין מ\"ש ביצי\"מ שהיא הקדמה למ\"ת ג\"כ לסוסתי ברכבי פרעה<sup data-n=\"1040\">32</sup> דימיתיך רעייתי, וצ\"ל מהו שייך בחי' סוסים ביצי\"מ, הלא ביצ\"מ כתיב ועברתי בארץ מצרים אני ולא מלאך ומהו ענין הסוסים כו'. הנה ענין הסוס הוא שרץ למקום גבוה מאד אשר האדם בעצמו לא יוכל להגיע לשם וגם יכול להורידו בבקעות גדולות כו' והיינו בחי' העלאה והמשכה כנ\"ל, וזהו ג\"כ מה שהי' במצרים נגוף ורפוא נגוף למצרים ורפוא לישראל, והיינו כנ\"ל בפי' גאה גאה שמתגאה על הגיאים, והיינו כי פרעה התגאה ואמר מי ה' אשר אשמע בקולו כו' והגביה א\"ע לקבל ממקום גבוה מאד, אכן הוא ית' גאה גאה שמתגאה ומסלק אורו מן הגיאים לבלתי תת להם יניקה ולכן ממילא הי' נגוף למצרים כו', ורפוא לישראל, מפני כי ישראל היו בשפלות מאד לכן היו כלים לקבל בחי' מרום וקדוש, וכמ\"ש מרום וקדוש אשכון את דכא ושפל רוח כנ\"ל. וזהו לסוסתי ברכבי פרעה בחי' סוסים דוקא ב\"פ ס\"ג היינו ההעלאה בחי' אתגאי על גיוותניא בחי' פרעה, והמשכה בישראל דוקא בחי' מאנין תבירין כו'. וזהו אני ולא מלאך אני גימט' ס\"ג כי ס\"ג ע\"ה עולה ס\"ד, ואני עם ג' אותיות ג\"כ עולה ס\"ד.\n<b>וזהו</b> מ\"ש מצה זו שאנו אוכלים על שום מה כו' ע\"ש שלא הספיק כו' שנגלה עליהם מלך מלכי המלכים כו' על שם הביטול בחי' מ\"ה, לכן נגלה עליהם בחי' מלך מלכי המלכים הקב\"ה, וכן בימי מרדכי ואסתר כתי' מה ראו על ככה ומה הגיע עליהם, פי' מ\"ה ראו על ככה שבחי' מ\"ה נתגלה להם בבחי' ראי' גם ע\"י בחי' ככה כי יש כה ויש ככה, כה הוא בחי' כל הנביאים נתנבאו בכה, וככה הוא בחי' כ\"ף",[["1038","30","<b>וזהו מ\"ש במד\"ר גדולה הסרת טבעת ממ\"ח נביאים</b>: ראה גם לקמן ח\"ב סד\"ה ושמתי כדכד."],["1039","31","<b>יש ב' בחי' ברכה והודאה. . ע' בד\"ה ויהיו חיי שרה (ל\"א)</b>: לעיל ע' נג ואילך. נז ואילך. וש\"נ."],["1040","32","<b>מ\"ש ביצ\"מ. . לסוסתי ברכבי פרעה</b>: בכ\"ז ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370285\" data-slug=\"torah-or\" data-id=\"3901370285\">תו\"א בשלח סג, ד</a>."]]],[2000510325,"הדמיון לבחי' כה<sup data-n=\"1041\">33</sup>, ומה הגיע אליהם<sup data-n=\"1042\">34</sup> שגם בבחי' ככה הגיע להם בחי' שהיו בבחי' מ\"ה הוא בחי' הביטול דמ\"ה. וזהו שארז\"ל איזהו שוטה המאבד מה שנותנים לו, שמאבד בחי' השם מ\"ה<sup data-n=\"1043\">35</sup> בבחי' ביטול ומ\"ה גימט' אדם כו', וכשמאבדו ה\"ז סימן שוטה.\n<b>והנה</b> כדי לבוא לבחי' מצה זו<sup data-n=\"1044\">36</sup> שאנו אוכלים ע\"ש מה בחי' ביטול, היינו שיהי' בחי' כלי לקבל בחי' ביטול זה צ\"ל תחלה אור לארבעה עשר בודקין את החמץ, כי החמץ הוא בחי' הגבהה והתנשאות בחי' גס הרוח שמזה הוא יניקה לחיצוני', וכדי שיהי' בחי' כלי לביטול דמ\"ה צריך לבער את החמץ, והיינו ע\"י בדיקת החמץ<sup data-n=\"1045\">37</sup> שבודקו בחורין ובסדקין על ידו מבער הקליפות כו'. וזהו כי יד על כס י\"ה שבי\"ד בניסן הוא העברת הכסוי של עמלק<sup data-n=\"1046\">38</sup> שמכסה על בחי' י\"ה כמ\"ש במ\"א בד\"ה מגילה נקראת ובהביאור<sup data-n=\"1047\">39</sup>, וכח זה להעביר הקליפות ניתן בפסח דוקא שזהו מ\"ש אך ביום הראשון תשביתו שאור שמבחי' ביום הראשון גימט' כתר ניתן הכח להשבית בחי' שאור, והשבתת חמץ ושאור הוא בערב פסח כנודע ממארז\"ל אך חלק, זהו שבי\"ד בניסן מעבירים קלי' עמלק בחי' י\"ד שעל כס י\"ה, ומדאורייתא בביטול בעלמא סגי, והיינו כי בפסח ניתן הכח לבער הקליפות לכן בביטול בעלמא סגי וממילא הם בטלים כו', רק מדרבנן צריך בדיקה דוקא בחורין ובסדקים בכדי שיהיו נשמות ישראל כלי לקבל בחי' הביטול דמ\"ה כו', והבדיקה היא אור לארבעה עשר דוקא כי בי\"ד שהוא ערב פסח הוא ההשבתה לגמרי, וקודם לזה הוא הבדיקה<sup data-n=\"1048\">40</sup>, שלא ימצא רק מה שצריך לסעודת היום עד שישבות החמץ לגמרי ויקבל מבחי' שם מ\"ה כו'.",[["1041","33","<b>כי יש כה ויש ככה. . כ\"ף הדמיון לבחי' כה</b>: ראה הוספות לתו\"א מג\"א שם קיח, ד. וראה גם מאמרי אדה\"ז הקצרים ע' רצה: כל הנביאים לא ראו הנבואה אלא בדמיונות והסתר לפיכך נאמר בהם כה שהכ\"ף יורה על הדמיון, וכשישראל בגלות ואומות מושלים עליהם אז אינו נראה אלקות כלל ויש יותר הסתרת פנים אז הי' ככה שני דמיונות."],["1042","34","<b>מה ראו על ככה ומה הגיע אליהם. . שבחי' מ\"ה נתגלה להם</b>: בכ\"ז ראה בארוכה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו\"א מג\"א צט, סע\"ב</a>-ג. הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370529\" data-slug=\"torah-or\" data-id=\"3901370529\">תו\"א מג\"א קיח, ג</a> ואילך. המשך מצה זו תר\"מ פכ\"ז בסה\"מ תר\"מ ח\"א ע' קעז."],["1043","35","<b>וזהו שארז\"ל איזהו שוטה המאבד מה. . שמאבד בחי' השם מ\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380089\" data-slug=\"likkutei-torah\" data-id=\"4001380089\">לקו\"ת ויקרא ג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380690\" data-slug=\"likkutei-torah\" data-id=\"4001380690\">מסעי צא, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380847\" data-slug=\"likkutei-torah\" data-id=\"4001380847\">ראה לג, רע\"א</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380168\" data-slug=\"likkutei-torah\" data-id=\"4001380168\">לקו\"ת תזריע כב, א</a>. פינחס עו, ב. לקו\"א להה\"מ (הוצאת קה\"ת) סכ\"ב (ח, א). או\"ת להה\"מ (בהוצאת קה\"ת) סתכ\"ג (קג, א). סה\"מ מלוקט ח\"ב ס\"ע שכט-ל."],["1044","36","<b>והנה כדי לבוא לבחי' מצה זו</b>: בהבא לקמן עד סוף המאמר ראה ד\"ה אור לארבעה עשר תער\"ג בסה\"מ תער\"ב-ע\"ו שם ע' רטז."],["1045","37","<b>צריך לבער את החמץ והיינו ע\"י בדיקת החמץ</b>: בד\"ה אור לארבעה עשר תער\"ג שם מוסיף: דבאמת הבדיקה והביעור הם ענין אחד שלכן מברכים בעת הבדיקה ג\"כ על ביעור חמץ ובד\"פ הם ב' ענינים. עיי\"ש. וראה שו\"ע אדה\"ז או\"ח סתל\"ב ס\"א: קודם שיתחיל לבדוק צריך לברך כו' על ביעור חמץ ואע\"פ שבשעה זו אינו מבערו עדיין מ\"מ כיון שלאחר הבדיקה מיד הוא מבטל ומפקיר כל החמץ כו' הרי ביטול זה נק' ביעור. ושם בסיום הסעיף: הבדיקה שהיא תחילת הביעור. וראה גם שם ס\"ב."],["1046","38","<b>וזהו כי יד על כס י\"ה שבי\"ד בניסן הוא העברת הכסוי של עמלק</b>: בד\"ה זה תער\"ג בסה\"מ תער\"ב-ע\"ו ע' עה הובא זה בשם התקו\"ז, ונת' בארוכה שם ע' רד ואילך. וראה גם אוה\"ת תצוה ע' א'תשד."],["1047","39","<b>כמ\"ש במ\"א בד\"ה מגילה נקראת ובהביאור</b>: סה\"מ תרכ\"ז ע' קפג. [וראה גם שם ע' קנז. וש\"נ]. הביאור לד\"ה מגילה נקראת נמצא בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש כת\"י 1029 כז, ב ואילך. [הכולל הנחות ממאמרי הצ\"צ משנת תרט\"ז, ולא נדפס עדיין]."],["1048","40","<b>בי\"ד שהוא ערב פסח הוא ההשבתה לגמרי וקודם לזה היא הבדיקה</b>: ראה ד\"ה אור לארבעה עשר בסה\"מ עטר\"ת ע' שנ ובסה\"מ הש\"ת ע' 42 ההפרש בין בדיקת חמץ באור לי\"ד לבין ביעור חמץ ביום י\"ד. עיי\"ש."]]],[2000510326,"<h3>כי ישאלך בנך</h3>\n<b></b><b>בס\"ד. (ליל ב' דחה\"פ, ל\"א).</b>\nליל ב' דחה\"פ\n<b>כי</b> ישאלך בנך<sup data-n=\"1049\">1</sup> מחר לאמר מה העדות והחוקים כו', והתשובה ואמרת לבנך עבדים<sup data-n=\"e57\">ה</sup> היינו כו' ויוציאנו ה' ממצרים כו' ויצוונו ה' לעשות את כל החוקים כו'. וידוע שכנגד ד' בנים דברה תורה ושאלה זו מבואר שהיא שאלת בן חכם. ויש להבין מהו שנק' חכם אם אינו יודע ענין העדות כו', וגם ענין יצ\"מ. גם מהו ההפרש בין שאלת בן רשע מה העבודה הזאת לכם בפ' בא (י\"ב פסוק ך\"ו) ובין שאלת בן חכם מה העדות כו' אשר צוה כו' אתכם בפ' ואתחנן (וא\"ו פסוק ך'). והגם שמבואר התירוץ ע\"ז ששם<sup data-n=\"1050\">2</sup> בפ' בא אמר לכם והוציא עצמו מן הכלל וכאן נאמר ה' אלקינו, אעפ\"כ הדבר צריך ביאור.\n<b>הנה</b> מבואר כאן ג' דברים העדות והחוקים והמשפטים שיש בכללות התורה והמצות. ולהבין ענין העדות, הנה כתיב בשמחה ובטוב לבב מרוב כל,",[["1049","1","<b>כי ישאלך בנך</b>: מיוסד על חלק מד\"ה זה להצ\"צ באוה\"ת ואתחנן ע' שצט ואילך. והגהות ע\"ז שם ע' תד ואילך. [כנסמן לקמן בפרטיות]. מאמר האוה\"ת נדפס יחד עם ההגהות בסה\"מ תרל\"ג ח\"א ע' רה ואילך.\nמאמר זה נמצא בתוס' הגהות בד\"ה זה בסה\"מ תרל\"ג ח\"א שם ע' רכד ואילך. ונמצא בשינויים והוספות בד\"ה זה בסה\"מ עטר\"ת ע' שנה ואילך (וראה גם שם ע' שנא). ובד\"ה ויקם עדות ביעקב בסה\"מ הש\"ת ע' 51 ואילך. ובד\"ה כי ישאלך: תשל\"ג (והמשכו בד\"ה עבדים היינו). תשל\"ח (סה\"מ מלוקט ח\"ד ע' ריג ואילך). תש\"מ. תשד\"מ (והמשכו בד\"ה ויקם עדות ביעקב). תשמ\"ו. לקו\"ש ח\"ג ע' 961 ואילך. לתחילת המאמר ראה גם ד\"ה זה בסה\"מ תרנ\"ד ע' רטז-יז.\nלכמה מעניני המאמר ראה גם ד\"ה כי ישאלך בס' מאמרי אדה\"ז פרשיות ח\"ב ע' תשמט ואילך. ונו\"א שם ע' תשעג ואילך. ובס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' מג ואילך. ובתוס' הגהות באוה\"ת ואתחנן (כרך ו) ע' ב'רצב ואילך [וראה בד\"ה כי ישאלך תשד\"מ (בתחילתו) בטעם הדיוק שכמה מאמרי דא\"ח דחג הפסח התחלתם הוא בפסוק כי ישאלך]."],["1050","2","<b>שמבואר התירוץ ע\"ז ששם. . אמר לכם. . וכאן נא' ה' אלקינו</b>: ראה בד\"ה כי ישאלך להצ\"צ באוה\"ת ואתחנן פ\"ב-ג בשם האלשיך והאברבנאל. ובאוה\"ת ואתחנן (כרך ו) שם הוא בשם הרוקח. וראה גם הגש\"פ עם לקוטי טעמים ומנהגים מכ\"ק אדמו\"ר בשם המחזור ויטרי. ובדעת זקנים מבעה\"ת עה\"פ. ועוד.\n\n<b>ה</b>  <b>והתשובה. . עבדים היינו כו' ויוציאינו ה' ממצרים</b>: כ\"ה ל' הפסוק (ואתחנן ו, כא), אך בנוסח ההגדה (פיסקא עבדים היינו) הל' הוא: ”ויוציאנו ה' אלקינו ממצרים\". ובשולי הגליון מעיר כ\"ק אדמו\"ר מהר\"ש על נוסח ההגדה: צ\"ע דבקרא זה דעבדים נאמר רק שם הוי' לבד<sup data-n=\"1636\">589</sup>, ולשון ויוציאינו ה' אלקינו חיפשתי בקורק'<sup data-n=\"1637\">590</sup> ולא נמצא כלל, ודוחק לאמר שכל כתבי האריז\"ל יהי' בנוי רק על נוסח ההגדה, וגם כי מאין סמכו נוסח זה."],["1636","589","<b>צ\"ע דבקרא. . נאמר רק שם הוי' לבד</b>: ראה גם הגש\"פ עם לקוטי טעמים ומנהגים ע' יב פיסקא: ”עבדים היינו כו' ויוציאנו ה' אלקינו משם ביד חזקה ובזרוע נטויה\", שם מעיר ע\"ז כ\"ק אדמו\"ר: מיוסד על הכתוב (דברים ו, כא) ובהוספות התיבות אלקינו, ובזרוע נטוי' שאינם בקרא. וראה בפע\"ח מ\"ח וסי' האריז\"ל הביאור ע\"ד הסוד. ובסידור רבינו ז\"ל נתבאר ע\"פ דא\"ח. ושייכות ובזרוע נטויה לאלקינו מובן גם ע\"פ מארז\"ל (ב\"ר ספי\"ב) אשר אלקים מורה על מדת הדין, וזרוע היינו יד שמאל (ברכות ו, א. נזיר ג, ב)."],["1637","590","<b>בקורק'</b>: קונקורדנציה (ס' שרשים ומלים בתנ\"ך)."]]],[2000510327,"שהשמחה של מצוה הוא יותר מרוב כל<sup data-n=\"1051\">3</sup>, כי כל בשמים ובארץ, שמים הו\"ע ג\"ע העליון וארץ הוא ג\"ע התחתון, ובחי' כל הוא העמוד המחבר, כתרגומו דאחיד בשמיא וארעא. ובאמת יש מדרגות עד אין קץ ואין תכלית מיני ג\"ע עליון ותחתון כמ\"ש ילכו מחיל אל חיל, וקדושים בכ\"י יהללוך סלה, וכל החיים יודוך סלה בלי הפסק, לכן יש רוב כל. גם כל בגימ' נו\"ן, נו\"ן שערי בינה ושער הנו\"ן הנק' כל הוא הממוצע המחבר חו\"ב, כי החכמה מאין תמצא והבינה נק' יש כמ\"ש להנחיל אוהבי יש, והיחוד וחיבור דאין וביטול דחכמה ביש והשגה דבינה הוא ע\"י כל שער הנו\"ן. אך במצות נאמר בשמחה כו' מרוב כל כי כל חיי העוה\"ב שיש בו מדרגות עד אין קץ הוא רק ביו\"ד נברא העוה\"ב זיו והארה בעלמא מא\"ס ב\"ה כמ\"ש הודו על ארץ ושמים ונשגב שמו לבדו, אבל בקיום המצות נאמר אשר קדשנו במצותיו, קדשנו במצותיך, בחי' מצותיך ממש, וכמ\"ש בתומ\"צ והיו הדברים האלה אשר אנכי מצוך וכתיב בפ' והי' כו' אל מצותי אשר אנכי מצוך והיינו בחי' אנכי מי שאנכי ממש מצוך.\n<b>וזהו</b> שמצות נק' בשם עדות<sup data-n=\"1052\">4</sup> על מצות עליונות כמ\"ש רז\"ל נובלות חכמה של מעלה תורה, כמו נובלות פרי, כך תורה היא נובלות חכמה של מעלה, וחכמה של מעלה נק' תורת הוי' ממש מצות הוי', כמו שבת להוי', מועדי הוי', הקב\"ה מניח תפילין, והקב\"ה מתעטף בציצית, ובב\"ר פ' ג' נתעטף הקב\"ה בטלית לבינה וע' בגמ' ר\"ה די\"ז ובחדא\"ג מהרש\"א שם, והיינו שזהו בחי' לבושי' כתלג חיור, והתומ\"צ שלמטה הם עדות ה' נאמנה כמ\"ש רז\"ל בנר המערבי עדות הוא ששכינה שורה בישראל, וישראל הם הנק' עדים כמ\"ש אתם עדי, וכתיב ששם עלו שבטים כו' עדות לישראל להודות לשם הוי' ממש שיומשך ויתגלה ע\"י המצות שהם העדות, וע\"ז אמר דהע\"ה בדרך עדותיך ששתי כעל כל הון שהשמחה של מצוה בגשמי' הוא יותר מרוב כל הון יקר ונעים דג\"ע ועוה\"ב, ואנכי ממש מצוך היום דוקא בעוה\"ז כמ\"ש היום לעשותם, ויפה שעה א' בתשומע\"ט בעוה\"ז מכל חיי העוה\"ב וע\"ז א' עדות ה' נאמנה.\nב) <b>והחוקים</b><sup data-n=\"1053\">5</sup> הו\"ע מ\"ש אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי, וחוקות הוא מל' חקיקה כמ\"ש במדרש רבה ר\"פ בחוקותי חוקה שבהם חקקתי שמים וארץ כו', חוקה כו' השמש והירח כו'. כי הנה כתיב כל אשר חפץ ה' עשה<sup data-n=\"1054\">6</sup> בשמים ובארץ, וכתיב בדבר ה' שמים נעשו, וידוע שהתהוות החומר ושמים וארץ וכללות הנבראים הם מהדבור העליון כמ\"ש בעשרה מאמרות נברא",[["1051","3","<b>הנה כתיב בשמחה ובטוב לבב. . יותר מרוב כל</b>: בהבא להלן עד סוף הפיסקא ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370362\" data-slug=\"torah-or\" data-id=\"3901370362\">תו\"א תצוה פא, א</a> ואילך. סה\"מ תרל\"ג ח\"א ע' קעו. ובכ\"מ."],["1052","4","<b>וזהו שמצות נק' בשם עדות</b>: בהבא לקמן עד סוף הפרק ראה ד\"ה כי ישאלך להצ\"צ באוה\"ת ואתחנן שם פי\"ד (ס\"ע תח ואילך)."],["1053","5","<b>ב) והחוקים</b>: בהבא לקמן עד סוף הפרק ראה ד\"ה כי ישאלך להצ\"צ באוה\"ת ואתחנן שם ע' תט ואילך."],["1054","6","<b>כי הנה כתי' כל אשר חפץ ה'. . וכתי' בדבר ה' שמים נעשו</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370188\" data-slug=\"torah-or\" data-id=\"3901370188\">תו\"א מקץ מא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370192\" data-slug=\"torah-or\" data-id=\"3901370192\">מב, ד</a> [הובא בד\"ה כי ישאלך להצ\"צ באוה\"ת שם]. ובסה\"מ תרכ\"ט (הוצאת תשנ\"ב) ע' יז ואילך. וש\"נ."]]],[2000510328,"העולם ובראשית נמי מאמר הוא, והצורה שבהם כמו שהרקיעים וגלגלים עגולים הם שרשם מבחי' סוכ\"ע, ותמונת הארץ כדורי ותולה ארץ על בלימה, וכן צורת ותמונת כל הנבראים הוא מבחי' כל אשר חפץ ה' עשה ובחכמה יסד ארץ כונן שמים כו' ובדעתו תהומות נבקעו, וגם תהלוכות הגלגלים שהשמש זורח ממזרח ובא למערב וכדומה הוא הנק' חוקות שמים וארץ מלשון חוק, כמ\"ש חוק וזמן נתן להם שלא ישנו את תפקידם בבחי' ביטול וצבא השמים לך משתחוים, והחוקה היא מקורה מהתורה ואם לא בריתי שהיא התורה חוקות שמים וארץ לא שמתי. והמשל הוא שיש ב' מיני אותיות, אותיות הכתב שהם משני דברים נפרדים דיו וקלף רק שמתאחדים ונדבקים יחד הדיו והקלף, אבל אותיות החקיקה<sup data-n=\"1055\">7</sup> הוא שהאותיות עצמיים מיני' ובי'. ככה יובן ההפרש למעלה לבין אותיות הדבור שבדבר ה' שמים נעשו ובין אותיות החקיקה שלמעלה שהוא בחי' מח' וח\"ע דתומ\"צ, כמ\"ש במחקק גימט' רמ\"ח, שע\"י קיום הרמ\"ח מ\"ע נעשה החקיקה בעולמות. ויש חוק וחוקה, כמו חוק בשארו שם דמילה בחי' דכר, וחוקה דפסח בחי' נוק', וחוקות דתורה הוא המחבר, וגם בנש\"י אמר אם בחקתי תלכו שההילוך הו\"ע אה\"ר דבכל מאדך להיות בבחי' הלוך ונסוע בלי גבול כמ\"ש ונתתי לך מהלכים בין העומדים, וכח ההילוך הוא ע\"י חוקות דתומ\"צ. וזהו באר חפרוה שרים בחי' באר מים חיים דכנס\"י, בא\"ר ר\"ת בידך אפקיד רוחי, להיות בבחי' אליך ה' נפשי אשא הוא ע\"י מחקק בגימט' רמ\"ח, ועי\"ז נעשה חקיקה מבפנים ומבחוץ, כמו למשל כלי גשמי צריך תחלה להעביר כל חלודה ולצחצח את הכלי מבחוץ, ואח\"כ לעשות חקיקה ותוך כלי קיבול מבפנים, כך ע\"י החקיקה דמחוקק<sup data-n=\"1056\">8</sup> דרמ\"ח מ\"ע עי\"ז מעביר כל רע דחיצוני' בבחי' אתכפי' ואתהפכא, וגם עי\"ז עלי באר בחקיקה פנימי' להיות ושכנתי בתוכם ממש כמ\"ש ונקדשתי בתוך בנ\"י, זהו החוקים דתורה.\n<b>והמשפטים</b><sup data-n=\"1057\">9</sup> הוא כמ\"ש ועלו מושיעים בהר ציון לשפוט את הר עשו, והוא כמ\"ש חסד ומשפט כו' שהמשפט לאלקים הוא, כמו שמבואר בתניא<sup data-n=\"1058\">10</sup> ענין צדיקים יצ\"ט שופטן וכמ\"ש להושיע משופטי נפשו<sup data-n=\"1059\">11</sup> כמ\"ש ובערת הרע מקרבך, ולע\"ל ואת רוח הטומאה אעביר מן הארץ ויבוער הרע לגמרי וכ\"ז הוא ע\"פ משפט התורה ואלה המשפטים אשר תשים לפניהם. ויובן מזה שע\"י ג' דברים אלו דעדות וחוקים ומשפטים דתומ\"צ גשמיי' דוקא יומשך ויתגלה גילוי אוא\"ס ב\"ה ממש גם למטה בעוה\"ז יותר מכל מיני המשכות דג\"ע ועוה\"ב דרוב כל הנ\"ל.",[["1055","7","<b>והמשל הוא שיש ב' מיני אותיות. . אותיות הכתב. . אותיות החקיקה</b>: הבא להלן (עד התיבות: וזהו באר) מיוסד על <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380270\" data-slug=\"likkutei-torah\" data-id=\"4001380270\">לקו\"ת בחוקותי מה, א</a>. מה, ד ואילך. חוקת נז, סע\"ב ואילך. נט, ג [הובאו בד\"ה כי ישאלך להצ\"צ באוה\"ת שם]."],["1056","8","<b>וזהו באר חפרוה שרים. . הוא ע\"י מחוקק</b>: הבא להלן עד סוף הפיסקא מיוסד על לקו\"ת חוקת סג, ב. סד, סע\"ד [הובא בד\"ה כי ישאלך להצ\"צ באוה\"ת שם]."],["1057","9","<b>והמשפטים</b>: בהבא להלן בפיסקא זו ראה בארוכה ד\"ה כי ישאלך להצ\"צ פ\"ח (אוה\"ת ואתחנן שם ע' תב)."],["1058","10","<b>כמו שמבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310016\" data-slug=\"tanya\" data-id=\"3401310016\">תניא</a></b>: בד\"ה זה בס' תרל\"ג נוסף בגוכי\"ק: פי\"א ופי\"ג."],["1059","11","<b>צדיקים יצ\"ט שופטן וכמ\"ש להושיע משופטי נפשו</b>: בד\"ה זה בס' תרל\"ג שם נתקן בגוכי\"ק: צדיקים יצ\"ט שופטן אבל הבינונים זה וזה שופטן וכמ\"ש להושיע משופטי נפשו."]]],[2000510329,"ג) <b>וע\"ז</b> הוא השאלה דבן חכם<sup data-n=\"1060\">12</sup>, דהוא יודע ענין ההמשכה דתומ\"צ, כמו שקיים אברהם אבינו כל התורה כולה עד שלא ניתנה, כי האבות הן המרכבה בבחי' ביטול ומס\"נ יומם ולילה באהבה רבה ונפלאה, לכן בכל העובדות שלהם כמו בחפירת בארות ומקלות המשיכו כל האורות עליונים להאיר החשך ואפילה כמ\"ש מי העיר ממזרח צדק. אבל השאלה הוא איך ע\"י ג' דברים הנ\"ל דעשי' גשמיי' דוקא כמו מצות אכילת מצה דוקא בגשמי'<sup data-n=\"1061\">13</sup> יומשך מוחין דאבא, אבל ע\"י כוונת אכילת מצה בלא אכילה לא יומשך כלל. והגם שאמרו מצות צריכות כוונה, היינו שהוא יותר טוב עם הכוונה, כי מצוה בלא כוונה כגוף כו', אבל העיקר הוא העובדות גשמי', והיום לעשותם דוקא כמ\"ש אשר אנכי מצוך היום. וע\"ז הוא עיקר השאלה איך ע\"י העשי' דעדות וחוקים ומשפטים גשמי' נובלות הנ\"ל יומשך מבחי' אנכי מי שאנכי יותר מג\"ע ועוה\"ב כמ\"ש קדשנו במצותיך ממש.\n<b>והתשובה</b> ע\"ז עבדים היינו<sup data-n=\"1062\">14</sup> לפרעה כו' ויוציאנו ה' ממצרים ביד חזקה כו' ויצוונו כל החוקים כו'. הענין הוא שדוקא ע\"י גלות מצרים ופרעה הקריב כו' נעשה הכנה וניתן להם זה הכח<sup data-n=\"1063\">15</sup> והעוז שע\"י תומ\"צ בגשמיות דוקא דעדות וחוקים ומשפטים יומשך ויתגלה אוא\"ס ב\"ה גם למטה בעוה\"ז הגשמי ממש לע\"ל וכמ\"ש ונגלה כבוד ה' וראו כו', כמו שע\"י גלות מצרים זכו למ\"ת.\n<b>ולהבין</b> זה צ\"ל משארז\"ל ששאל לרב יהודה כד הוה בדיחא דעתי' כו' כל חללי דעלמא מ\"ט עזי מסגי ברישא והדר אמרי, ואמר לו כברייתו של עולם ברישא חשוכא והדר נהורא. ויובן זה, הנה ידוע שיש ב' בחי' ברצון, פנימי' וחיצוני'<sup data-n=\"1064\">16</sup>, ופנימי' הרצון נק' חפץ, וכמ\"ש כי תהיו אתם ארץ חפץ, וכתי' (ישעי' ס\"ב ד') חפצי בה, וכל גבולך לאבני חפץ וכמ\"ש כי חפץ בבת יעקב, שהוא חפץ ותשוקה פנימיות, כמו שאנו רואים באדם שרוצה לעשות איזה עסק ומשא ומתן שהעיקר המכוון בזה להרוויח ולהחיות נפשו ונפשות בני ביתו ולזה עיקר מגמתו וחפצו, אבל עצם העסק הוא רק חיצוניות הרצון, שאם הי' באפשרי להרוויח בלי עסק זה לא הי' רוצה בשום אופן בזה העסק והטרחא, אך כי לא סגי בלא\"ה הוכרח שיהי' לו רצון בפרטיות בכל העסק בעל כרחו, ואעפ\"כ נק' רצון כמו כופין אותו עד שיאמר רוצה אני שנק' רצון ע\"פ ד\"ת, אך הוא רק חיצוניות ובטל וטפל להעיקר המכוון פנימי' חפצו ורצונו. גם אנו רואים שא\"א לבוא אל העיקר המכוון",[["1060","12","<b>וע\"ז היא השאלה דבן חכם</b>: בהבא להלן בפיסקא זו ראה ד\"ה כי ישאלך להצ\"צ שם ספי\"ד (אוה\"ת ואתחנן שם ע' תט)."],["1061","13","<b>מצות אכילת מצה דוקא בגשמי'</b>: ראה גם סה\"מ מלוקט ח\"ד שם ע' ריד (הע' 16)."],["1062","14","<b>והתשובה ע\"ז עבדים היינו</b>: בהבא להלן עד סוף הפרק ראה ד\"ה כי ישאלך להצ\"צ פ\"ז (אוה\"ת ואתחנן שם ס\"ע תה ואילך)."],["1063","15","<b>וניתן להם זה הכח</b>: בד\"ה זה בס' תרל\"ג נתקן כאן בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש: וניתן לנו."],["1064","16","<b>הנה ידוע שיש ב' בחי' ברצון פנימי' וחיצוני'</b>: בהבא להלן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. לג, ד. וראה גם סה\"מ תרכ\"ז ע' קלו. וש\"נ."]]],[2000510330,"הפנימי רק כשעוסק בטפל וחיצונית תחלה אח\"כ יוגמר חפצו הפנימי. ככה יובן למעלה שתכלית הבריאה הוא בשביל ישראל, כמ\"ש בראשית בשביל ישראל כו' ובשביל התורה שנק' ראשית, וכמ\"ש כי זה כל האדם שכל העולם כולו לא נברא אלא לצוות לזה, לכן סדר הבריאה תחלה דומם בשביל צומח, וצומח בשביל חי, וצומח וחי בשביל מדבר שהוא האדם, והוא העיקר והם טפלים לו, והעיקר דמדבר הוא אתם קרוים אדם כי זה כל האדם, זה הוא המשכת גילוי אלקות כמ\"ש בקי\"ס זה אלי, ולעתיד הנה אלקינו זה זה הוי' קוינו לו, שע\"י ג' קוין דתורה ועבודה וגמ\"ח היינו שלשה דברים שהעולם עומד עליהם יומשך אוא\"ס בגילוי עד שיאמר עליו כי הוא זה, כמארז\"ל בקרי\"ס כאו\"א מראה באצבעו ואומר זה כו', וכל העולם כולו לא נברא אלא לצוות לזה האדם כי זה הוא פנימיות רצון העליון שיהי' לו דירה בתחתונים ע\"י ישראל ותומ\"צ, וכמ\"ש הן לה' אלקיך השמים ושמי השמים כו' רק באבותיך חשק ה', ונק' ארץ חפץ ויאר ה' פניו אליך דוקא, וכמו במ\"ת פנים בפנים דיבר ה' עמכם. אך שיהי' הגילוי זה דמ\"ת שיהי' יאר ה' פניו אליך, יאר פניו אתנו סלה צ\"ל תחלה בחי' חיצוני' ואחוריי' דגלות מצרים ופרעה אותיות העורף, כי קליפה קדמה לפרי<sup data-n=\"1065\">17</sup>, כמו שאנו רואים בטבע דצמיחת הארץ כשאדם נוטע אילן המכוון שלו הוא בשביל הפרי, ובתחלה צומחין העלין והקליפות ואח\"כ יוגמר הפרי, כמו אל גינת אגוז ירדתי שהאגוז מסובב בקליפין ופרי גנוז בתוכו, וגם בחטה תחלה יצמח הקש והתבן והמוץ ואח\"כ יוגמר החטה, ובלא זה לא יהי' גידול החטה כלל, ואח\"כ כשיוגמר הפרי והחטה אז אין צריך כלל להקליפה והתבן והמוץ כ\"א כמוץ אשר תדפנו רוח. וכן ארז\"ל שני אלפים תהו ואח\"כ שני אלפים תורה<sup data-n=\"1066\">18</sup>, וגלות מצרים קודם מ\"ת, כן גם בכל הענינים הרוחני' למעלה מעלה שרש הקליפה קדמה לפרי. וזהו ג\"כ השאלה מ\"ט עזי מסגי ברישא, שהמכוון על עובדי כוכבים ששרשם משערות וחיצוניות כמ\"ש הן עשו אחי איש שעיר, ונק' שעיר ע\"ש שעיר עזים, כידוע שעיקר יניקת החיצוני' הוא משערי דעזים, והדר אימרי הוא ישראל עם קרובו, ושרשם משערות דקדושה ושער רישי' כעמר נקי, וגם אימרי ע\"ש את ה' האמרת היום וחלקי ה' אמרה נפשי. והשיב לו כברייתו ש\"ע ברישא חשוכא והדר נהורא כמובן מכל הנ\"ל, לכן הי' תחלה גלות מצרים פרעה עורף חיצונית וחשך הנ\"ל, והדר נהורא דמ\"ת שנק' תורה אור וטוב כמ\"ש במשה ותרא אותו כי טוב הוא שעל ידו ניתנה תורה אור כמ\"ש וירא כו' את האור כי טוב.\nד) <b>אך</b> להבין זה בתוס' ביאור<sup data-n=\"1067\">19</sup> למה דוקא ע\"י חשך דפרעה בגלות מצרים יתגלה אור דתורה וישראל, ואם מהטעם דפרעה אותיות עורף ואחוריים דרצון העליון ששם כחשיכה כאורה שוין ומשם יכול גם פרעה לקבל כל אור ושפע, זה",[["1065","17","<b>כי קליפה קדמה לפרי כמו שאנו רואים. . שכשאדם נוטע אילן</b>: בכ\"ז ראה בארוכה סה\"מ תרכ\"ט (הוצאת תשנ\"ב) ע' כג. קיח. שכב-ג. וש\"נ."],["1066","18","<b>שני אלפים תהו ואח\"כ שני אלפים תורה</b>: נת' בד\"ה כי ישאלך בסה\"מ עטר\"ת הש\"ת שם. עיי\"ש."],["1067","19","<b>אך להבין זה בתוס' ביאור</b>: בהבא להלן עד סוף המאמר ראה (בקיצור) ד\"ה כי ישאלך להצ\"צ שם פט\"ו (אוה\"ת ואתחנן שם ע' תי)."]]],[2000510331,"גופא קשה למה נגרע שהאור דישראל יהי' גרוע מהחושך דמצרים הלא שם כחשיכה כאורה שוים ממש.\n<b>ויובן</b> תחלה מ\"ש ביהושע שוב מול בני ישראל שנית כו' היום גלותי חרפת מצרים<sup data-n=\"1068\">20</sup> מעליכם, דע\"י מצות מילה דוקא גלותי חרפת מצרים. הנה ערלה נק' חרפה כמ\"ש גבי שכם כי חרפה היא לנו, ומצרים נק' ערות הארץ וחרפה וערלה המסתיר ומבדיל לגמרי. כי הנה יש מסכים והבדלות דקדושה, כמו והבדילה הפרוכת<sup data-n=\"1069\">21</sup> לכם בין הקדש ובין קדה\"ק, שגם אחר ההבדלה הוא קדש שמאיר הקדושה עליונה דרך הפרוכת, וכמו המבדיל בין קדש לקדש, ויש הבדלה עוד למטה במדרגה היינו המבדיל בין קדש לחול, וגם שם אינו מבדיל ומסתיר לגמרי שהרי אמר ששת ימים תעבוד, שעיקר עבודת האדם בעוה\"ז לעשות מחול קדש ולהוסיף מחול על הקדש, כמו שמצינו בגמ' שהיו אוכלים חולין על טהרת תרומה או קדש ונק' חולין שנעשו על טהרת הקדש<sup data-n=\"1070\">22</sup>, כמו קדש עצמך במותר לך, שכל דברים המותרים הם מק\"נ שנק' חול ומעורב טו\"ר, וע\"י עבודת האדם יוכללו בקדושה כמ\"ש בכל דרכיך דעהו וכל מעשיך יהיו לשם שמים, שכללות התורה ומצותיה הוא לברר בירורי נוגה ולאהפכא מחשוכא לנהורא, וא\"כ ההבדלה שבין קדש לחול אינו מסך מבדיל לגמרי, וע\"ז אומרים ברוך אתה ה' המבדיל בין קדש לחול. אבל יש עוד מסך המבדיל בין טמא לטהור שהוא ענין דברים האסורים והטמאים דגקה\"ט לגמרי ומסך מבדיל זה המסתיר לגמרי אור אלקי נק' ערלה, וטמא טמא יקרא, שא\"א להיות להם עלי' ותיקון עפ\"י התורה. וזהו שאמרו זכרנו את הדגה אשר נאכל במצרים חנם, חנם בלא מצות, שבגלות מצרים הנק' ערלה לא הי' להם כח לעורר באתעדל\"ת אתעדל\"ע בקיום המצות מעשיות, שהעוה\"ז הי' בהסתר אור האלקי וחשך גמור, רק היו מקבלים ההשפעה ע\"י פרעה אותיות עורף מבחי' אחוריים דחיצוניות דרצון העליון שלמעלה מאתעדל\"ת אתעדל\"ע, ושם אין האתעדל\"ת מגיע כו' וקמי' כחשיכא כו' ואם צדקת כו' ושממית בידים כו', ואעפ\"כ היו מקבלים אור ושפע רב, שמפני עוצם הרוממות דכולא קמי' כלא חשיב שאינו תופס מקום כללות ההשתל' בא ההשפעה בשפע רב, כמשל הידוע שפירורי הפקר דסעודה שעושה המלך ברוממותו לשפע רב יחשב<sup data-n=\"1071\">23</sup>, אך שאינם מקבלים רק תמצית וחיצוניות ואחוריים השפעה גשמיות, שהרי כתיב וכבודי לאחר לא אתן. וזהו שנק' חרפת מצרים שהוא בחי' ערלה וחושך התחתון המחשיך ומעלים ומסתיר עוה\"ז הגשמי, ושרשו מחושך העליון דברישא חשוכא כו'.",[["1068","20","<b>ויובן תחלה מ\"ש ביהושע. . היום גלותי חרפת מצרים</b>: ראה סידור עם דא\"ח קמב, א. קמד, א ואילך."],["1069","21","<b>כי הנה יש מסכים. . והבדילה הפרוכת</b>: הבא להלן עד סוף הפיסקא מיוסד על ד\"ה ולא יקרא עוד שמך בסידור עם דא\"ח קמה, א ואילך [הובא בד\"ה כי ישאלך להצ\"צ באוה\"ת שם]. והנחה אחרת ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך</a> יב א ואילך. וראה שם יג, א."],["1070","22","<b>ולהוסיף מחול עד הקדש. . ונק' חולין שנעשו על טהרת הקדש</b>: ראה בכ\"ז בארוכה סה\"מ תרכ\"ו ע' א ואילך."],["1071","23","<b>כמשל הידוע שפירורי הפקר דסעודה שעושה המלך. . לשפע רב יחשב</b>: ראה סידור עם דא\"ח רצג, סע\"ד ואילך. סה\"מ מלוקט ח\"ג ע' קד ואילך."]]],[2000510332,"ה) <b>אך</b> עיקר הטעם שהיו ישראל בגלות מצרים בבחי' ירידה ושפלות אצל פרעה בחושך גדול כזה, המכוון הי' בכדי שיהי' יתרון אור מן החשך כידוע, והוא ע\"י הסרת הערלה ושבירת המסך המבדיל דחשך התחתון דקליפת מצרים ע\"י אותות ומופתים דעשר מכות, כמ\"ש וידעו מצרים כי אני ה', כי פרעה אמר לא ידעתי את ה' מי ה' אשר אשמע כו', שהי' מקבל מבחי' רם על כל גוים הוי' ולכן הי' למטה חושך גמור, ולבסוף הודה בעצמו ואמר ה' הוא הצדיק ואני כו'. לכן א' עבדים היינו כו' ויוציאנו ה' ממצרים ביד חזקה כו' ובמוראים גדולים, שכדי לשבר קליפת מצרים ערות הארץ הוצרך להיות הגילוי ממקום גבוה מאד כמ\"ש המגביהי לשבת המשפילי כו', ועברתי בארץ מצרים אני ולא מלאך כו'. וזהו מ\"ש אל גינת אגוז ירדתי דקאי על גלות מצרים, ולמה המשל מאגוז דוקא הלא בכל הפירות ואילנות ותבואה קליפה קדמה לפרי, וכשנגמר הפרי נזרק הקליפה לחוצה, אך עיקר המשל מהאגוז שגם כשנגמר הפרי בתכלית הוא גנוז בתוך הד' קליפות<sup data-n=\"1072\">24</sup> דאגוז ומסובב מהם ואינו יכול ליקח הפרי רק כ\"א ע\"י שבירת האגוז בתחלה. ככה יובן הנמשל דאל גינת אגוז ירדתי דשם בחושך דמצרים הי' אור גנוז בהם כידוע דכללות ס\"ר שרשי נשמות ישראל עבדו בהם בפרך בחומר ובלבנים כדי לבררם וללבנם בכור הברזל דחושך מצרים, וע\"י שהוציאנו משם ביד חזקה כו' כנ\"ל תבר כל שלשלהון דפרזלא והי' יתרון אור מהחושך ונתגלה אור הגנוז, כמ\"ש ולכל בנ\"י הי' אור במושבותם ובנ\"י יוצאים ביד רמה.\n<b>וזהו</b> היום גלותי חרפת מצרים מעליכם, שהוא הסרת הערלה והמסך המבדיל ע\"י מצות מילה ופריעה כידוע, כי כל הגוים ערלים הם כמ\"ש במשנה י\"א פ\"ג דנדרים קונם שאיני נהנה לערלים מותר בערלי ישראל, כגון ערל שמתו אחיו מחמת מילה, ואסור במולי עובדי כוכבים, והיינו לפי שהם ערלים בעצם שמקבלים בשרשם מערלה שהוא ג' קליפות כו', וישראל הם חלק הוי' עמו ויאר ה' פניו אליך, יאר פניו אתנו סלה. וע\"י יציאת מצרים זכו למ\"ת פב\"פ דיבר ה' עמכם, וניתן להם תומ\"צ בגשמיות דייקא, שעי\"ז ימשיכו גילוי עצמות ופנימי' אוא\"ס ב\"ה ממש למטה בעוה\"ז הגשמי שיהי' לו דירה בתחתונים כמ\"ש ושכנתי בתוכם ממש.\n<b>וזהו</b> שאומרים בכמה מצות זכר ליציאת מצרים, וידוע הקושי' שגם אם לא היו במצרים הלא התורה והמצות קדמו אלפים שנה לעולם. אך הענין שע\"י יציאה דגלות מצרים התחתון תכלית החושך למטה שהוא מיצר וגבול גמור המסתיר עוה\"ז לגמרי עי\"ז הי' יציאת מצרים דקדושה ג\"כ בכל העולמות שנק' מצרים וגבולים עד רום המעלות, וע\"ד שארז\"ל על שם שדי שאמר לעולמו די כח המגביל, ויצ\"מ הוא גילוי דשם הוי' הי' הוה ויהי', ואני הוי' לא שניתי אוא\"ס שבלתי בע\"ג ותכלית. וזהו עיקר דתומ\"צ כמ\"ש רחבה מצותך מאד, וזהו ואותנו",[["1072","24","<b>עיקר המשל מהאגוז. . הד' קליפות</b>: ראה בכ\"ז אוה\"ת ויצא ריג, א. אחרי ע' שח. ס' החקירה להצ\"צ צה, א. סה\"מ תרכ\"ט (הוצאת תשנ\"ב) ע' קיח. תרל\"ד ע' שכ. ועוד. וראה סה\"מ תרל\"ג ח\"א ע' רצו: האגוז הזה יש לו ג' קליפין כו'."]]],[2000510333,"הוציא משם כו' וכדכתי' וארד להצילו מיד מצרים כו' ולהעלותו כו' אל ארץ טובה ורחבה וכמ\"ש לעתיד הרחיבי מקום אהלך כו' לקבל גילוי אוא\"ס ממש בבע\"ג שלא ע\"י מסכים ולבושים דמצרים וגבולים דקדושה ולא יכנף עוד מוריך והיו עיניך רואות את מוריך כי עין בעין יראו כו'.\n<b>וזהו</b> התשובה לשאלת בן חכם מה העדות והחוקים כו' עבדים היינו לפרעה בחושך וגלות דקליפת מצרים למטה, ויוציאנו ה' אלקינו משם ביד חזקה כו' בשבירת כל המסכים המבדילים, עי\"ז נעשה יתרון האור מהחשך כו', שע\"י אתעדל\"ת דתומ\"צ גשמי' דוקא יהי' גילוי פנימי' א\"ס ב\"ה ויאר ה' פניו אליך. וזהו ויצוונו כל החוקים האלה ליראה את ה' אלקינו, יראה אותיות ראיה, כי עין בעין נראה גילוי אלקות למטה כמו למעלה בלי שום הסתר פנים. אך כלליות הגילוי הוא דוקא ע\"י הסתר פנים דגלות עכשיו כמארז\"ל חגיגה ד\"ה סע\"א דכל שאינו בהסתר פנים אינו מהן<sup data-n=\"1073\">25</sup> וכמ\"ש העם ההולכים בחושך ראו אור גדול, כי יתרון אור מן החשך דוקא, וכמו שע\"י גלות וחשך מצרים ראו אור מ\"ת דתומ\"צ הנגלות לנו, כך ע\"י החושך ואריכות הגלות דעכשיו<sup data-n=\"1074\">26</sup> כימי צאתך מאמ\"צ אראנו נפלאות מפנימיות התומ\"צ וטעמי המצות שיתגלה לע\"ל במהרה בימינו.",[["1073","25","<b>דכל שאינו בהסתר פנים אינו מהן</b>: ראה פירש\"י חגיגה שם: אינו מהן מזרע ישראל דכתיב והסתרתי פני מהם."],["1074","26","<b>הסתר פנים דגלות עכשיו. . ואריכות הגלות דעכשיו</b>: בד\"ה זה בס' תרל\"ג נתקן כאן בגוכי\"ק (תחת התיבות דגלות עכשיו. . הגלות דעכשיו): דגלות חורבן ביהמ\"ק. (וכנראה הוא שינוי מחמת הצענזור)."]]],[2000510334,"<h3>ואני תפלתי כו'</h3>\n<b></b><b>בס\"ד. (שחוהמ\"פ, ל\"א).</b>\nמצה כו' חמץ ומצה\nשחוהמ\"פ\n<b>ואני</b> תפלתי<sup data-n=\"1075\">1</sup> לך ה' עת רצון, הנה ידוע דכל מנחה הוא בחי' דין<sup data-n=\"1076\">2</sup>, ומנחה דשבת הוא עת רצון וע\"כ אומרים פסוק ואני תפלתי כו' קודם תפלת מנחה דשבת",[["1075","1","<b>ואני תפלתי</b>: מאמר זה מלבד ההתחלה והסיום מיוסד (כנראה) על ביאור מאמר הזוהר ד\"ה מצחא דאתגליא בביאוה\"ז לאדהאמ\"צ קכו, ג ואילך. וראה ד\"ה זה להצ\"צ משחוהמ\"פ תקצ\"ד בכת\"י 2098 קע, א.\nהמאמר נמצא בשינויים ובתוס' הגהות בד\"ה זה בסה\"מ תרנ\"ד ע' רלו ואילך. [שם נמצא עד קרוב לסיום המאמר פיסקא: ועפ\"ז יובן בקצרה ענין חמץ ומצה. — כמה קטעים מהמאמר כאן לא ניתנו להעתיק בד\"ה זה תרנ\"ד ונדפסו שם בשולי הגליון]. ד\"ה ועתה יגדל נא בסה\"מ עת\"ר (הוצאת תשמ\"ה ואילך) ע' רנג ואילך. וע' שכו ואילך. ד\"ה ששת ימים בסה\"מ תרע\"ח ע' רמו ואילך. ד\"ה ויאמר משה זה הדבר בסה\"מ תר\"פ ע' כ ואילך [וראה גם בד\"ה ואני תפלתי שם ע' לו]. ד\"ה ועשו לי מקדש בסה\"מ תרפ\"ח ע' פא ואילך. ד\"ה ואני תפלתי בסה\"מ תש\"ד ע' 163 ואילך. ד\"ה ששת ימים בסה\"מ תש\"ו ע' 77 ואילך. ד\"ה החודש הזה בסה\"מ תש\"ל ע' 202 ואילך."],["1076","2","<b>ידוע דכל מנחה הוא בחי' דין</b>: נת' בד\"ה זה תרנ\"ד: דתפלת מנחה יצחק תיקן כמ\"ש ויצא יצחק לשוח בשדה לפנות ערב ואין שיחה אלא תפלה, ויצחק הי' מרכבה למדת הגבורה ופחד יצחק הי' לי, ולכן כל מנחה הוא בחי' דין."]]],[2000510335,"דוקא. והענין הוא משום שאומרים בבני היכלא<sup data-n=\"1077\">3</sup> דכסיפין כו' והא אזמין עתיק יומין למצחא דילי'<sup data-n=\"1078\">4</sup> כמ\"ש בסידור האריז\"ל. והנה תוכן הענין בדרך כלל ההפרש בזה הוא מפני שבמנחה דחול הוא בחי' מצחא דז\"א וממצחא דז\"א מתערי' ך\"ד בתי דינים כו', ובמנחה דשבת הוא בחי' מצחא דעתיקא והוא בחי' רעוא דכל רעוין.\n<b>וביאור</b> הענין הוא דהנה ידוע שיש תלת חללי דגלגלתא והם ענין תלת מוחין<sup data-n=\"1079\">5</sup> מוח החכמה ומוח הבינה ומוח הדעת, והנה מוחין חו\"ב הוא להדי פנים, ומוח הדעת הוא לצד העורף, והמצח הוא מכוון כנגד מוח הדעת. וצריך להבין השייכות דמצח לדעת כי מאחר שהם מכוונים זה נגד זה משמע שיש איזה שייכות ביניהם. וגם להבין ענין דעת דקליפה שהוא קליפת עמלק שהם יודעים את רבונם ומכוונים למרוד כו', ומאחר שיש דעת דקליפה יש ג\"כ בחי' מצח דקליפה שמכוון נגד הדעת והוא בחי' מצח אשה זונה כו'. אך צריך להבין תחלה מהו ענין המוחין. ויובן ממילי דעלמא שאנו רואים כשאדם עושה איזה ענין משא ומתן וכדומה אזי תחלה מתחכם בזה ומתבונן איך שטוב וכשר הדבר לפניו, ותחלה נופל לו במחשבתו בבחי' הברקה בעלמא, ואח\"כ מתבונן בזה באורך ורוחב כמבואר בכמה מקומות ע\"ש<sup data-n=\"1080\">6</sup>, וזה נק' מוח חכמה ומוח בינה. והדעת הוא המקשר את הדבר בפנימיות כי הגם שהשכיל הדבר בשכלו ובינתו אינו מוכרח עדיין שיוחלט כך, רק עיקר קיומו הוא ע\"י הדעת שהוא ענין ההתקשרות כמו והאדם ידע<sup data-n=\"1081\">7</sup> כו'. וגם מה שנמשך ממוח ללב שיתפעל הלב ג\"כ מזה הוא ג\"כ ע\"י הדעת<sup data-n=\"1082\">8</sup> וכידוע דהדעת הוא מפתחא דכליל שית. (וכח הלידה בגשמיות ג\"כ הוא ע\"י הדעת וכידוע דחוט השדרה נמשך ממוח הדעת<sup data-n=\"1083\">9</sup> והטיפה נמשכת בחוט השדרה, ודוקא ע\"י מוח הדעת). וכמו\"כ יובן בעבודה האלקית שמוח חו\"ב הוא ההשכלה וההתבוננות בגדולת הבורא איך שואתה מחיה את כולם מאין ליש ולקרב אל השכל ע\"י משלים והסברים כמו מחיות הנפש בגוף וכהנ\"ל. אך יכול להיות גם שהשכיל בשכלו זאת היטב איך שאין העולם עושה א\"ע וכל העולמות כולם עליונים ותחתונים חיים מאלקות ומאמיתת המצאו נמצאו כל הנמצאים, אבל אין הדבר נוגע אליו ואינו",[["1077","3","<b>והענין הוא משום שאומרים בבני היכלא</b>: בד\"ה זה תרנ\"ד מוסיף כאן: והענין הוא משום שאז מאיר בחי' עתיקא כמו שאומרים בבני היכלא [כבפנים]."],["1078","4","<b>למצחא דילי'</b>: בנוסח אדה\"ז [ועד\"ז הוא בשאר הנוסחאות]: למצחא עדי יהון חלפין."],["1079","5","<b>ידוע שיש תלת חללי דגלגלתא והם ענין תלת מוחין</b>: ראה עד\"ז ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370373\" data-slug=\"torah-or\" data-id=\"3901370373\">תו\"א תצוה פג, ד</a>: תלת חללין דגלגלתא הן תלת מוחין חב\"ד, ועל כל חלק מוח גשמי שורה אור השכל השייך למוח ההוא. ועד\"ז בכ\"מ. וראה ד\"ה ששת ימים תרע\"ח שם: החללים הוא שבהם נמצאים המוחין והן כמו היכלות, והמוחין הם כלים לאור השכל כו' וכמ\"ש בסידור בשער התפילין."],["1080","6","<b>ותחלה נופל. . בבחי' הברקה. . ואח\"כ מתבונן בזה באורך ורוחב כמבואר בכמה מקומות ע\"ש</b>: ראה אגה\"ק סו\"ס טו (קכד, א). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א בראשית ו, ג</a>. הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370479\" data-slug=\"torah-or\" data-id=\"3901370479\">תו\"א שמות קח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380672\" data-slug=\"likkutei-torah\" data-id=\"4001380672\">לקו\"ת מטות פז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380872\" data-slug=\"likkutei-torah\" data-id=\"4001380872\">תצא לח, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380874\" data-slug=\"likkutei-torah\" data-id=\"4001380874\">לט, ב</a>. ובכ\"מ."],["1081","7","<b>הדעת שהוא ענין ההתקשרות כמו והאדם ידע</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא ספ\"ג</a>. ועוד."],["1082","8","<b>וכח הלידה בגשמיות. . ע\"י הדעת</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370465\" data-slug=\"torah-or\" data-id=\"3901370465\">תו\"א ויחי קה, סע\"ג</a>-ד. ועוד."],["1083","9","<b>וכידוע דחוט השדרה נמשך ממוח הדעת</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370546\" data-slug=\"torah-or\" data-id=\"3901370546\">תו\"א מג\"א קכב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380601\" data-slug=\"likkutei-torah\" data-id=\"4001380601\">לקו\"ת בלק ע, סע\"ד</a> ואילך. ובכ\"מ."]]],[2000510336,"נתפס ונדבק במוחו היטב (הנק' איין קלעפ אין מוח היטב כו'), רק העיקר הוא ע\"י מוח הדעת שהוא המקשר את הדבר בפנימי' מוחו שיהי' הדבר נתפס ונדבק במוח, וכענין טעמו וראו כי טוב ה', וטועמיה חיים זכו, ששומע הדבר במוחו ומרגיש זה כמו שמרגיש חיי נפשו (בל\"א איין דער הער אין מוח טיף), וכל זה הוא ע\"י הדעת כי הדעת הוא לשון התקשרות ולשון הרגשה (כמו וידעו כי עירומים הם כו'). וגם ההמשכה ממוח ללב שיתפעל הלב מההתבוננו' ג\"כ הוא ע\"י הדעת<sup data-n=\"1084\">10</sup> (וכמ\"ש בלק\"א פ\"ג ע\"ש), וזהו שמע ישראל כו' ואהבת, שמע הוא השמיעה במוח חו\"ב ע\"י התבוננות בגדולת הבורא איך שהוי' אלקינו הוי' אחד, ואח\"כ ואהבת בכל לבבך כו' והוא ההמשכה ממוח ללב ע\"י מוח הדעת כנ\"ל.\n<b>ועתה</b> יש להבין ענין מצחא שהוא מכוון נגד מוח הדעת, ויובן ג\"כ למעלה ענין מצחא וההפרש שבין מצחא דז\"א למצחא דעתיק יומין. והענין הוא כי הנה ידוע דאית רצון ואית רצון<sup data-n=\"1085\">11</sup>, אית רצון שלמטה מן השכל ואית רצון שלמעלה מן השכל, רצון שלמטה מן השכל הוא הרצון שנולד באדם מצד השכל והטעם, כמשל ממילי דעלמא שאחר שמשיג בשכלו איך שטוב ויפה לו איזה ענין ומראה לו טעם עפ\"י שכל וסברא ישרה לכן נולד אצלו רצון שירצה וישתוקק לאותו הדבר שהשכיל בשכלו כי טוב הוא לו מאד. ואית רצון שלמעלה מהשכל והוא מה שאנו רואים שיכול להיות באדם איזה רצון אשר הוא היפך השכל, שגם אם יבואו כמה בני אדם ויאמרו לו איך אתה עושה זאת הלא השכל מחייב היפוכו לגמרי לא ישמע להם כלל מפני טעם הכמוס שיש לו בזה (או מפני עקשותו בדבר ההוא כמ\"ש בסידור בדרוש דאנת הוא חד<sup data-n=\"1086\">12</sup> ולא בחושבן כו' ע\"ש). והנה נגד ב' בחי' רצון אלו יש ב' בחי' מצחא<sup data-n=\"1087\">13</sup>. והענין הוא כי הרצון שלמטה מן הטעם ושכל שהוא הנקרא רצון הנולד מצד השכל והטעם כנ\"ל, הנה הרצון שנולד תיכף אחר השכל והטעם הרי הרצון הוא עדיין בבחי' פנימי' מפני שיש בו הארת המוחי' עדיין, והרצון הוא בתשוקה שרוצה ומשתוקק בפנימי' לבו ומוחו, שאחר שהשיג בשכלו טוב איכות הענין ההוא אזי צמאה נפשו ורצונו לגמור הענין ההוא בכי טוב, אך אחר זמן שנסתלקו המוחין והמדות והוא עוסק באותו הענין ומדבר ועושה בזה הדבר אח\"כ, אינו בפנימי' מוחו כ\"א שנשאר ההסכם<sup data-n=\"1088\">14</sup> חזק אצלו לעשות הדבר מפני שכבר הוסכם אצלו בפנימי' מוחו ונתפעל בלבו, ע\"כ הוא עושה אח\"כ את הענין גם בלא התפעלות מחמת ההסכם הנשאר אצלו והוא הנק' חיצוניות הרצון, אבל יש בזה",[["1084","10","<b>וגם ההמשכה ממוח ללב. . הוא ע\"י הדעת</b>: בד\"ה זה תרנ\"ד מציין כאן ללקו\"ת ואתחנן ביאור לד\"ה וידעת היום. ראה לקו\"ת ואתחנן שם ה, ב. ו, ד."],["1085","11","<b>כי הנה ידוע דאית רצון ואית רצון</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370395\" data-slug=\"torah-or\" data-id=\"3901370395\">תו\"א ויקהל פז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381319\" data-slug=\"likkutei-torah\" data-id=\"4001381319\">לקו\"ת שה\"ש מז, סע\"ד</a> ואילך. סידור עם דא\"ח קל, ג. [ובהנסמן לקמן הערה ד\"ה: והנה נגד ב' בחי']."],["1086","12","<b>כמ\"ש בסידור בדרוש דאנת הוא חד</b>: סידור עם דא\"ח קסא, ב."],["1087","13","<b>והנה נגד ב' בחי' רצון אלו יש ב' בחי' מצחא</b>: בהבא לקמן ראה בארוכה אוה\"ת על מארז\"ל ע' נז ואילך. סה\"מ תרכ\"ח ע' כו ואילך. תרכ\"ט ע' פ ואילך. וש\"נ."],["1088","14","<b>אחר זמן שנסתלקו המוחין והמדות. . שנשאר ההסכם</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380686\" data-slug=\"likkutei-torah\" data-id=\"4001380686\">לקו\"ת מסעי צ, ג</a>."]]],[2000510337,"תוקף גדול עכ\"פ שלא ינטה ימין ושמאל ממה שהוסכם כבר בפנימי' כו' כנ\"ל. וכמו\"כ יובן ברצון שלמעלה מן הטעם הגלוי שיש בזה טעם כמוס לרצון<sup data-n=\"1089\">15</sup> שיש בזה ג\"כ פנימי' והוא הרצון שנולד תיכף קרוב להטעם הכמוס כנ\"ל ברצון הגלוי, ואחר שנסתלק הטעם נשאר בחי' הסכם בחי' חיצוני' הרצון לבד שהוא חיצוני' רצון שלמעלה מן הטעם כו'.\n<b>וכמו\"כ</b> יובן בעבודת ה' ענין ב' בחי' אלו, רצון שלמטה מן השכל הוא בחי' מדות הנולדים מן השכל והתבוננו', שמתבונן בגדולת הבורא ית' איך דכולא קמי' כלא חשיב, שמחמת זה תכלה נפשו אליו כמ\"ש צמאה לך נפשי כו'. ורצון שלמעלה מן השכל הוא בחי' אהבה רבה, והוא האהבה הבאה מלמעלה להאדם אשר ממילא ומאליו תתלהט ותתלהב נפשו בלא הקדמת שכל והתבוננות ונק' בחי' אהבה רבה והוא בחי' בכל מאדך בלי גבול, (ורצון שלמטה מן השכל נקרא אהבת עולם). ולמעלה נק' טורי חשוכא, כי יש ב' בחי' טורי נהורא וטורי חשוכא<sup data-n=\"1090\">16</sup>, טורי נהורא הם המדות שנולדים מן החכמה שנק' אור, וטורי חשוכא הם המדות שבהעלם הרצון (והוא בחי' מדות שבכ\"ע למעלה מן החכמה), ויובן זה ג\"כ ממ\"ש בסידור בהערה לתיקון חצות<sup data-n=\"1091\">17</sup> ע\"ש.\n<b>ויובן</b> ג\"כ ענין ב' בחי' מצחא, כי הנה זמן ההתפעלות הוא בעת התפלה וכדומה, שאז הוא שעת הכושר להתבונן במוח חו\"ב בגדולת הבורא בפסוד\"ז ובשתים לפניה כו', ומוח הדעת הוא המקשר בפנימי' כנ\"ל, אך אחר התפלה מסתלקים המוחין כי א\"א שיהי' כל היום בהתפעלות, כי אחר התפלה צריך לעסוק כל אחד בעסקיו המוכרחים שמותר עפ\"י תורה כמ\"ש ששת ימים תעשה מעשיך<sup data-n=\"1092\">18</sup> כו', ואפי' יושבי אוהלים שתורתם אומנתם עכ\"ז אינן בהתפעלות בשעת לימוד ועסק התורה כמו בתפלה, רק שנשאר ההסכם על כל היום, היינו מאחר שהוחלט אצלו בשעת התפלה ע\"י התבוננות בגדולת הבורא איך שה' הוא העיקר ומקורא דכולא ונתפעל מזה בפנימי' מוחו ולבו, ע\"כ כל היום גם אחר כלות ההתפעלות נשאר אצלו הסכם חזק להיות סור מרע ועשה טוב, והגם שהוא בלא התפעלות עכ\"ז ההסכם חזק הוא אצלו, וכמו למשל בעסק המשא ומתן כנ\"ל שמפני שהתבונן תחלה באיכות טוב ענין משא ומתן שטוב הדבר לו ונתפעל בלב ע\"כ עוסק בזה אח\"כ כמו שהוחלט אצלו כבר גם ששכח על הטעם כו' כנ\"ל. והנה ענין הסכם זה שהוא חיצוני' הרצון נק' בחי' מצחא שהוא שורה בהמצח, וע\"כ המצח הוא מכוון נגד מוח הדעת כי היינו הך, רק שהדעת הוא בבחי' פנימי' והמצח הוא בבחי'",[["1089","15","<b>טעם כמוס לרצון. . ואחר שנסתלק הטעם נשאר. . בחי' חיצוניות הרצון</b>: ראה גם סה\"מ תרנ\"ח ע' קלח. סה\"מ מלוקט ח\"ב ס\"ע רמח-ט. סה\"מ תשי\"ח ע' 398-397."],["1090","16","<b>יש ב' בחי' טורי נהורא וטורי חשוכא</b>: ראה לקו\"ת דרושים לשמע\"צ פו, סע\"ד. ועוד."],["1091","17","<b>ממ\"ש בסידור בהערה לתיקון חצות</b>: סידור עם דא\"ח קנא, ג ואילך."],["1092","18","<b>צריך לעסוק. . בעסקיו. . שמותר עפ\"י תורה כמ\"ש ששת ימים תעשה מעשיך</b>: ראה בארוכה אוה\"ת יתרו ע' תתקנא ואילך. סה\"מ תרכ\"ז ע' קלא. וראה גם לעיל ד\"ה ויקח ה\"א ע' א ואילך."]]],[2000510338,"ההסכם בחיצוניות הנשאר על כל היום, והדעת הוא בבחי' פנימי' מפני שיש בו הארת המוחין עדיין כנ\"ל. וזהו בחי' מצחא בבחי' רצון שלמטה מן השכל. וכמו\"כ יובן בבחי' רצון שלמעלה מן השכל שהוא בחי' אה\"ר שלמעלה מן השכל שנק' אה\"ר שיש בזה ג\"כ בחי' מצחא והוא הסכם הנשאר אחר כלות ההתפעלות, רק שהוא בחי' מצחא דבחי' גבוה ממצחא הנ\"ל.\n<b>והנה</b> עפי\"ז יובן למעלה ג\"כ ענין מצחא דז\"א ומצחא דעתיק, דידוע דז\"א הוא בחי' מדות חו\"ג, ושרש המדות הוא מבחי' מוחין חכ' ובינה ודעת, וכאשר המוחין מאירים בפנימי' זהו בחי' ז\"א, אמנם בחי' מצחא הוא בחי' חיצוני' אשר שם אינו מאיר הארת המוחין זהו הנק' בחי' מצחא דז\"א כנ\"ל, והוא בחי' מצחא דרצון התחתון כנ\"ל, שהוא עד\"מ באדם התחתון שהמצח מסתיר על המוחין שבראש ומעלים אותן כו'. ובחי' מצחא דעתיק הוא בחי' רצון העליון שלמעלה מן הטעם, והענין הוא כמו שארז\"ל גבי ר\"ע שסרקו בשרו במסרקות ברזל ששאל מרע\"ה זו תורה וזו שכרה ואמר לו הקב\"ה שתוק כך עלה במחשבה לפני כו', פי' שתוק שאין טעם לרצון זה, ובאמת ודאי יש טעם כי מפני מה ירצה בלא טעם שיסרקו בשרו של ר\"ע שהוא מקור התושבע\"פ (כמארז\"ל כולהו סתימאה אליבא דר\"ע), אלא שהטעם הוא טעם הנעלם וכמוס<sup data-n=\"1093\">19</sup>, וזהו שאמר לו שתוק שא\"א להתגלות בטעם גלוי, ולמעלה הוא הנקרא טעם כמוס לרצון בבחי' ח\"ס, שיש שם ג\"כ בחי' מוחין אך שהם בחי' מוחין נעלמים למעלה מעלה מן מוחין הגלויים בבחי' השתלשלות, ויש שם ג\"כ בחי' הרצון פנימי' אשר בו הארת המוחין עדיין וע\"י בחי' דעת הנעלם שהוא המקשר בפנימיות כנ\"ל, ובחי' מצחא הוא בבחי' חיצוניות רצון העליון כמשל בחי' ההסכם הנ\"ל והוא הנקרא מצחא דעתיק.\n<b>ועתה</b> יש להבין מה שמבואר לעיל שממצחא דז\"א מתערי' ך\"ד בתי דיני' כו', ובמצחא דעתיק הוא רעוא דכל רעוין. והענין הוא כי הנה אנו אומרים אבינו אב הרחמן וידוע דחכמה נק' אבינו, וזהו אבינו בחי' חכ', אב הרחמן שאבא הוא מקור החסדים כידוע. והענין יובן עד\"מ באדם למטה שאנו רואים שכאשר הוא מתבונן באיזה ענין לעשות כך וכך יכול לסבול בזה גם היפוכו, כי מרחב השכל יכול לסבול גם דבר המנגדו, והטעם לזה הוא [כי] בחכמה יכול למצוא טעם להיפוכו ג\"כ, כמו שיכול למצוא זכות להצדיק את החייב, כי מאחר שמחייב עפ\"י שכל וטעם יכול למצוא הטיה בשכלו לזכותו (וכענין שאו' על טמא טהור ומראה לו פנים). אך אחר שנסתלק השכל והטעם ונשאר אצלו ההסכם לבד לעשות כך דוקא ולא היפוכו, אז לא יכול לסבול דבר המנגד לרצונו, מאחר שכבר נסתלק השכל והטעם ולא נשאר אצלו כ\"א ההסכם בעצם הענין לעשות כך ושכח על השכל והטעם, אזי יכעוס ויקצוף מאד כשיעשו דבר שכנגד הסכמת רצונו שהוסכם אצלו, ואינו מועיל שום טעם ואמתלא להמתיק הדבר בשכל אולי מטעם זה ראוי",[["1093","19","<b>שתוק כך עלה במחשבה. . ודאי יש טעם. . טעם הנעלם וכמוס</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380760\" data-slug=\"likkutei-torah\" data-id=\"4001380760\">לקו\"ת ואתחנן יב, א</a>. שה\"ש מז, ד. [ובהנסמן בהמ\"מ לשם]. סה\"מ תרל\"ב ח\"ב ע' שצד. ועוד."]]],[2000510339,"לעשות בהיפך מהסכמתו, אחר שאינו יודע הטעם להסכמתו כו', וה\"ז עד\"מ התינוק שמלא דינין וקפידות וכעס על עשות נגד רצונו, כי לא ימצא טעם ושכל לסבול דבר שכנגד רצונו מפני צמצום המוחין שלו כידוע, משא\"כ הגדול שדעתו רחבה יסבול הרבה דברים שכנגד רצונו כי ימצא מקום לסבול גם מה שכנגד רצונו. וע\"כ החכמה מקור החסדים כנ\"ל בפי' אבינו אב הרחמן כו' דאור אבא כולו חסדים מפני רוחב החכמה יוכל למצוא זכות למנגדו ג\"כ כי רוחב השכל יסבול הכל וצמצום השכל לא יסבול אפילו כל שהוא כו' וכמ\"ש במ\"א<sup data-n=\"1094\">20</sup>. וכך יובן בענין ההסכם הנ\"ל אחר שהמוחין מצומצמים בו מאד לא יוכל לסבול אפי' כל שהוא נגד ההסכם. וכמו\"כ יובן למעלה שכאשר החכמה מאיר במדות אזי נמתקים כל הדינים כענין מ\"ש לא אוסיף עוד לקלל את האדם כי יצר לב האדם רע כו', ומתחלה הי' זה הטעם עצמו לחוב כמ\"ש אמחה כו', ואח\"כ נהפך זה הטעם עצמו לזכות<sup data-n=\"1095\">21</sup> מפני הארת החכמה שממתיק הדין הקשה, וז\"ש אבינו אב הרחמן כו'. אבל כאשר נסתלק אור החכמה ולא נשאר רק בחי' ההסכם שכן יהי', אזי נתעוררו כל הדינים כי לא יוכל לסבול דבר שכנגד הסכמת רצונו. וכענין מ\"ש הנה אנכי שולח מלאך כו' אל תמר בו כי לא ישא לפשעכם, שהמלאך הוא שליח לבד ומוכרח לעשות כמו שנצטוה בלתי נטי' כלל, כמו עד\"מ השליח ששולח המלך לעשות איזה פקודה וציווי המלך ואינו אומר לו הטעם מזה אזי חזקה שהשליח עושה שליחותו בלתי נטי' כלל גם שיחייב השכל להיפוכו, כי הוא צריך לעשות כמו שנצטוה ולא יועיל בשליחותו<sup data-n=\"1096\">22</sup>, אבל כשאומרים לו טעם ושכל בדבר השליחות יכול לשנות מעט בדבר השליחות<sup data-n=\"1097\">23</sup> אם יחייב השכל כך. וכמו\"כ יובן במלאכים עליונים שהם שלוחי השפע לא ישנו את תפקידם. וכמו\"כ יובן למעלה בענין מצחא דז\"א שהוא בחי' הסכם לבד היינו חיצוניות הרצון לבד ואין שם הארת חכמה ע\"כ מתערים ממנו ך\"ד בתי דינים כו', וע\"כ כל מנחה הוא בחי' דין, כי בשחר בג' שעות ראשונות שאז הוא זמן ק\"ש הוא בחי' המשכות מוחין במדות, אבל אחר חצות מסתלקים המוחין כו' ע\"כ במנחה הוא בחי' דין כו' כנ\"ל. וכמו\"כ יובן למטה בעבודת ה' באדם, שאחר התפלה הגם שנשאר אצלו הסכם להיות סור מרע ועשה טוב מחמת הרשימו ניכר שנשאר מהתפלה, עכ\"ז הוא עלול יותר ליפול בתאוות עוה\"ז, משא\"כ בשעת התפלה שאז הוא הארת המוחין, והדעת הוא המקשר בפנימי' כנ\"ל שהדעת הוא דעת אלקי', אבל אחר התפלה שלא נשאר רק בחי' ההסכם לבד יכול ליפול בתאוות וכדומה. כמו\"כ יובן למעלה שבחי' דעת גם שבהסתעפות מתערים מיני'",[["1094","20","<b>רוחב השכל יסבול הכל וצמצום השכל לא יסבול. . וכמ\"ש במ\"א</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370261\" data-slug=\"torah-or\" data-id=\"3901370261\">תו\"א וארא נח, סע\"ג</a>-ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381250\" data-slug=\"likkutei-torah\" data-id=\"4001381250\">לקו\"ת שה\"ש ל, ב</a>. המשך וככה תרל\"ז פצ\"ד (ע' קנא-ב). סה\"מ מלוקט ח\"א ע' קעח (ובהנסמן שם בהע' 31)."],["1095","21","<b>כענין מ\"ש לא אוסיף. . ומתחלה הי' זה הטעם עצמו לחוב. . ואח\"כ נהפך. . לזכות</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370068\" data-slug=\"torah-or\" data-id=\"3901370068\">תו\"א וירא טו, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380242\" data-slug=\"likkutei-torah\" data-id=\"4001380242\">לקו\"ת אמור לט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381319\" data-slug=\"likkutei-torah\" data-id=\"4001381319\">שה\"ש מז, ד</a>. המשך מים רבים תרל\"ו ע' י ואילך. ובכ\"מ."],["1096","22","<b>ולא יועיל בשליחותו</b>: אוצ\"ל: ולא ימעול בשליחותו."],["1097","23","<b>כשאומרים לו טעם ושכל בדבר השליחות יכול לשנות מעט בדבר השליחות</b>: יל\"ע בזה ע\"ד הנגלה, ועיין בשו\"ת צמח צדק חו\"מ סכ\"ט (לג, ב)."]]],[2000510340,"ך\"ד בתי דינים (והוא סוד עה\"ד טו\"ר), אבל בחי' דעת עצמו הוא בחי' דעת דקדושה כידוע.\n<b>וזהו</b> ענין ממה שממצחא דז\"א דייקא דמחפי' על מוחא מתערי' ך\"ד בתי דינים כנ\"ל, אך במצחא דעתיקא שם בי' גלי' רצון. והענין יובן עפמ\"ש ארך אפים וגדל חסד, שמפני שהוא בחי' ארך אפים ע\"כ הוא גדל חסד, כמשל המלך שעושה סעודה לשריו ועבדיו, שמפני גודל שפע רב ורוב עושר המלכות ע\"כ תגדל הסעודה מאד, עד שהפירורי הפקר שלו נחשבים אצל אחר ליש ודבר גדול<sup data-n=\"1098\">24</sup>. כמו\"כ עד\"מ ודוגמא יובן למעלה במל' דלעילא שמפני שהוא ארך אפים ע\"כ וגדל חסד, כי החכמה נק' דין<sup data-n=\"1099\">25</sup> הגם שהחכמה הוא מקור החסדים כמ\"ש אבינו כו', אבל מ\"מ נמשכת אח\"כ באו\"כ דמדות דאצי' וע\"כ נק' זעיר אנפין מפני צמצום האורות בכלים, והחכמה עצמה ג\"כ נמשכת מבחי' אין כמ\"ש והחכמה מאין תמצא כמשל המשכות ויניקות שערות הראש מהמוחין בבחי' יניקה מצומצמת, וע\"כ מתערים דיני' מבחי' מצחא דז\"א. אבל עתיק ואריך הם בחי' אחרונה דא\"ס ע\"כ וגדל חסד דייקא, וע\"כ במצחא דעתיק יומין (שהוא בחי' פנים דא\"א שכולל מצחא ותרין תפוחין כו') שם גילוי רצון כו', הגם שהוא בחי' חיצוני' לבד, אבל בחי' חיצוני' שבבחי' ומדרגה עליונה גבוה יותר מבחי' פנימי' שבבחי' תחתונה, וע\"כ שם הוא בחי' רעוא דכל רעוין כמ\"ש בזהר מצחא דעתיקא דבי' גלי' רצון כו' (ועוד מפני כלל אחר הידוע שבבחי' חיצוני' דוקא מתגלה בחי' היותר עליונה כמ\"ש במ\"א באריכות<sup data-n=\"1100\">26</sup>). ובעבודה הוא בחי' אהבה רבה הנ\"ל בחי' בכל מאדך בלי גבול, שלמעלה מבחי' אהבת עולם שהוא האהבה הנולדה משכל והתבוננות, כ\"א האהבה היא למעלה מן השכל והטעם לגמרי כנ\"ל (ואפ\"ל ענין טעם הכמוס ג\"כ בכאן הוא ענין התענוג שיש לנשמה באלקות מצד עצמו כניצוץ אל השלהבת, כי בטעם יש ב' פי' הא' הוא לשון טעם ושכל כמו בדרז\"ל מאי טעמא דר' פלוני, והב' הוא ענין טעם ותענוג כמ\"ש טוב טעם ודעת כו', וזהו ענין טעם הכמוס שהוא תענוג הנשמה בעצם מאלקות כמ\"ש כי הוא חייך ממש כו'), ולאהבה כזו אין לה הפסק כלל והוא כיתד בל תמוט עולם ועד. ועפ\"י הנ\"ל יובן מ\"ש כי אל דעות הוי'<sup data-n=\"1101\">27</sup>, דידוע שהוא בחי' ב' דעות דעת עליון ודעת תחתון, דעת תחתון היינו הדיעה שמלמטה למעלה שהעולם נברא יש מאין שאין אנו משיגים רק גוף העולמות שהוא בחי' יש גמור,",[["1098","24","<b>כמשל המלך שעושה סעודה. . שהפירורי הפקר שלו נחשבים. . ליש ודבר גדול</b>: ראה סידור עם דא\"ח רצג, סע\"ד ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540831\" data-slug=\"torat-chaim\" data-id=\"2300540831\">תורת חיים שמות</a> (הוצאת תשס\"ד) ח\"א קכו, א. דרך מצותיך עט, א. קונ' ומעין מאמר ז' בתחילתו. סה\"מ מלוקט ח\"ג ע' קד ואילך. ועוד."],["1099","25","<b>כי החכ' נק' דין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, ד</a>. ובארוכה ביאוה\"ז להצ\"צ ח\"א ע' תשיח ואילך. וראה גם סה\"מ תרל\"ד ע' לח. וש\"נ."],["1100","26","<b>שבבחי' חיצוני' דוקא מתגלה בחי' היותר עליונה כמ\"ש במ\"א באריכות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381276\" data-slug=\"likkutei-torah\" data-id=\"4001381276\">לקו\"ת שה\"ש לז, סע\"א</a>-ב. מאמרי אדה\"ז תקס\"ד ע' קכו [ושם: ידוע מהבעש\"ט והמגיד ז\"ל ששורש החיצוניות גבוהות מהפנימיות כו']. וע' קצב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600479\" data-slug=\"or-hatorah-hb\" data-id=\"8316600479\">אוה\"ת נ\"ך (כרך א) ע' תעט</a>-פ. ועוד."],["1101","27","<b>וע\"פ הנ\"ל יובן מ\"ש כי אל דעות הוי'. . ב' דעות דעת עליון וד\"ת</b>: בהבא לקמן ראה בארוכה סידור עם דא\"ח מד, סע\"א ואילך. פיה\"מ לאדהאמ\"צ צ, סע\"ד ואילך. סה\"מ תרל\"ט ח\"ב ד\"ה מזמור לתודה. וש\"נ."]]],[2000510341,"ואלקות אין אנו משיגים, וע\"כ אנו אומרים שהעולם נברא יש מאין כי בחי' אין הוא בחי' העלם שאין אנו משיגים את כח האלקי עצמו רק שאנו מתבונני' איך שהעולם הוא נברא מאלקות. וד\"ע הוא איך דקמי' כולא כלא חשיב והוא בחי' מיש לאין שהאמת הוא שאלקות הוא היש האמיתי מקורא דכולא וכל העולמות כולם עליונים ותחתונים כאין וכאפס נחשבו. והנה מההתבוננות אשר מאין ליש יכול להסתעפות מזה יש גמור, אבל בחי' ד\"ע איך שהוא קמי' ממש דכולא קמי' כלא חשיב לא יסתעף מזה בחי' יש כלל אף מבחי' ההסכם שהוא בחי' מצחא כנ\"ל, וזהו ענין ב' הבחי' הנ\"ל כו'.\n<b>ובזה</b> יובן מה שאומרים קודם תפלת מנחה דשבת ואני תפלתי לך ה' עת רצון, שהגם שבכל מנחה הוא בחי' דין כמשנ\"ת לעיל באריכות, אבל במנחה דשבת הוא עת רצון מפני שבשבת במנחה הוא בחי' התגלות מצחא דעתיקא כמו שאומרים בבני היכלא דכסיפין כו' והא אזמין עתיק יומין למצחא כו'. והענין הוא שבחי' מצחא דעתיקא מאיר בבחי' מצחא דז\"א, וע\"כ כל דינין משתככי' כו' (וכמשל המלך באור פני מלך בעת שמחתו אז נמתקים כל הדינים ומטיב לכל כו', וכמו\"כ יובן למעלה שמפני הארת מצחא דעתיקא במצחא דז\"א נמתקים כל הדינים) וכענין שכתוב בזוה\"ק וכל שולטני רוגזין ומארי דדינא כולהו ערקין ואתעברו מנייהו כו' ואנפהא נהירין כו'.\n<b>ועפי\"ז</b> יובן בקצרה ענין חמץ ומצה, כי הנה מצה בגי' ע\"ב ס\"ג<sup data-n=\"1102\">28</sup>, וחמץ ושאור הוא בחי' גבורות. והנה ההפרש בגשמיות בין חמץ למצה<sup data-n=\"1103\">29</sup> הוא, שבחמץ ושאור יש בו נפוח והתפשטות ויש בו טעם, ומצה היא נאפית קמח ומים כמו שהוא בלי שום התפשטות וגם אין בה טעם (וכמארז\"ל בלע מצה יצא, לא בעינן טעם מצה). וע\"ד הסוד ענין חמץ ושאור הוא בחי' גבורות שבחו\"ג<sup data-n=\"1104\">30</sup> ששרשם בבחי' דעת, ונת\"ל דמבחי' דעת דקדושה יכול להסתעף בחי' יש עד בחי' יש ולגרמי' ממש, והוא מפני שבבחי' דעת הי' שבירת הכלים כמ\"ש וימלוך בלע כו' וימת דידוע דבלע הוא סוד הדעת כו'. ובעבודה הוא משנת\"ל שמבחי' מצחא דז\"א מתערי' דיני' כו', היינו שלאחר התפלה שנשאר רק ההסכם יכול ליפול ברע ח\"ו, כי יש זלע\"ז בחי' מצח אשה זונה, וזהו\"ע חמץ אותיות מצח. גם חמץ הוא אותיות מחיצה, וה\"ע מחיצה של ברזל המפסקת בין ישראל לאביהם שבשמים, והוא בחי' קלי' עמלק<sup data-n=\"1105\">31</sup> דעת דקלי' כמשארז\"ל יודעי' את רבונם ומכוונים למרוד בו<sup data-n=\"1106\">32</sup>, כי דעת",[["1102","28","<b>מצה בגימ' ע\"ב ס\"ג</b>: בד\"ה ששת ימים תרע\"ח שם מוסיף כאן: דע\"ב הוא בחי' חסד."],["1103","29","<b>והנה ההפרש בגשמיות בין חמץ למצה</b>: בהבא לקמן ראה סידור עם דא\"ח שם מה, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080441\" data-slug=\"or-hatorah-hb\" data-id=\"8160080441\">אוה\"ת ויקרא ע' תמא</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200063\" data-slug=\"or-hatorah-hb\" data-id=\"8159200063\">שם (כרך ג) ע' תשעה</a> ואילך. סה\"מ תרכ\"ז ע' שלג. שלט. תרכ\"ט ע' קמא. ועוד."],["1104","30","<b>חמץ ושאור הוא בחי' גבורות שבחו\"ג</b>: בבוך תרל\"א נרשם תחילה: חמץ ושאור הוא בחי' חו\"ג. ואח\"כ נתקן בגוכי\"ק כבפנים. ובד\"ה ששת ימים תרע\"ח שם: חמץ ושאור הוא בחי' חו\"ג שבגבורה. ועי' <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200044\" data-slug=\"or-hatorah-hb\" data-id=\"8159200044\">אוה\"ת ויקרא (כרך ג) ע' תשנו</a>."],["1105","31","<b>מחיצה של ברזל. . והוא בחי' קלי' עמלק</b>: בד\"ה ששת ימים תרע\"ח מוסיף: ברזל בגימ' עמלק. וראה בארוכה סה\"מ תרכ\"ז ע' קנו ואילך. וע' קפג ואילך."],["1106","32","<b>קלי' עמלק. . כמשארז\"ל יודעים את רבונם ומכוונים למרוד בו</b>: ראה לעיל ד\"ה זכור גו' עמלק ע' קצג. וש\"נ. ולקמן ח\"ב ד\"ה וירא את עמלק. בהבא לקמן אודות קליפת עמלק ראה שם בארוכה."]]],[2000510342,"דקדושה אין בהם שהוא בחי' התקשרות והרגשת אלקות כנ\"ל כמ\"ש אין דעת אלקים בארץ כו' כ\"א בחי' החוצפא נגד אלקות, גם שמבינים שה' הוא העיקר מ\"מ מורדי' בו, והו\"ע מצח דקלי' שהוא ההסכם למרוד בחוצפה ועזות, וכמו במלחמת עמלק עם ישראל שהי' על לא דבר שלא נגעו ישראל בו ובעמו כלל, רק מפני שלא הי' יכול לסבול האותות והמופתים שעשה ה' לישראל. וז\"ע חמץ ושאור הנ\"ל, מפני ששרש חמץ ושאור הוא בחי' דעת, ויש זלעו\"ז בחי' דעת דקלי' כנ\"ל א\"כ אסור לאכול חמץ ושאור כו'. אבל מצה הוא בחי' ע\"ב ס\"ג, וידוע דע\"ב הוא בחכ', וכתי' ימותו ולא בחכ' שהי' בחי' מיתה אבל לא בחכ', שבחכ' לא הי' שבירה ומיתה כלל וע\"כ אין מזה הסתעפות רע כלל (והגם שבס\"ג הי' השבירה כמ\"ש בס' הקבלה הוא בס\"ג דס\"ג)<sup data-n=\"1107\">33</sup> כמ\"ש במ\"א<sup data-n=\"1108\">34</sup>, ובעבודה הוא בחי' מ\"ה וביטול עצמי, ולא הביטול שמצד הטעם ודעת שהוא בחי' יש מי שבטל, ומבחי' יש יכול להסתעף יש ולגרמי', אבל מבחי' מ\"ה העצמי' שהוא בחי' ביטול בעצם למעלה מן הדעת והוא בחי' ד\"ע כמו דקמי' כולא כל\"ח והוא דעה עליונה דמיש לאין לא יסתעף מזה שום רע כלל (והוא כענין הנ\"ל שבמצחא דעתיקא גלי' רצון כו').\n<b>וזהו</b> שבעת ימים מצות יאכל כו', כי ז' ימים הוא ז' מדות עליונות ובמדות הי' השבירה כמ\"ש וימלוך וימת וגם בבחי' דעת כנ\"ל, והוא שרש ענין מצה וחמץ ושאור כנ\"ל וע\"כ צריך לאכול מצה בפסח ז' ימים שהוא להמשיך בחי' מצה בחי' מ\"ה העצמי' הנ\"ל בבחי' שבעת הימים הנ\"ל ואז לא יסתעף גם מבחי' ז' הימים שום רע כלל. וע\"כ מותר לאכול חמץ ושאור אחר הפסח, כי מאחר שכבר המשיכו בפסח ע\"י אכילת מצה בחי' מ\"ה בז' הימים הנ\"ל לא יזיק השאור וחמץ כלל. ולכן נתלה המן ביום שני דפסח, ושם הי' ע\"י בחי' מ\"ה שראו על ככה שגם בבחי' ככה דמיון לבחי' כה<sup data-n=\"1109\">35</sup> הגיע הביטול דמ\"ה ע\"י המס\"נ שהיו כל השנה, וגם לדורות ע\"י אכילת מצה קטנות אבא לילה הראשונה (וממילא נחשב כל היום ראשון) אז ביום שני הו\"ע תליית המן ברוחניות, שהוא איבוד השאור וחמץ קלי' עמלק שיודע רבונו ומתכוין למרוד בו, שהו\"ע השבתת השאור ברוחניות כו' (עד שבשבועות מצוה דוקא בשתי הלחם חמץ תאפינה שמעלים גם החמץ כו'), והוא כענין הנ\"ל שכשמאיר מצחא דעתיקא במצחא דז\"א אז הוא עת רצון וע\"כ אומרים בשבת במנחה ואני תפלתי לך ה' עת רצון.",[["1107","33","<b>שבס\"ג הי' השבירה. . בס\"ג דס\"ג</b>: בד\"ה ששת ימים תרע\"ח שם: בשם ס\"ג הי' השבירה רק בז\"ת שבו."],["1108","34","<b>שבחכ' לא הי' שבירה ומיתה כלל. . כמ\"ש במ\"א</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370492\" data-slug=\"torah-or\" data-id=\"3901370492\">תו\"א קי, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370529\" data-slug=\"torah-or\" data-id=\"3901370529\">קיח, ג</a>. ועוד."],["1109","35","<b>ע\"י בחי' מ\"ה שראו על ככה. . דמיון לבחי' כה</b>: ראה לעיל סד\"ה אור לארבעה עשר ע' רמא-ב. וש\"נ."]]],[2000510343,"<h3>והחרים ד' כו'</h3>\n<b>שש\"פ ל\"א.</b>\n<b>והחרים</b><sup data-n=\"1110\">1</sup> ה' את לשון ים מצרים והניף ידו על הנהר בעים רוחו והכהו לשבעה נחלים, וארז\"ל במד\"ר קהלת ע\"פ הבל הבלים ר' יהודה ב\"ר סימון אמר ז' הבלים שא' קהלת כנגד ז' ימי בראשית, בראשון בראשית ברא אלקי' את השמים וכתי' כי שמים כעשן נמלחו<sup data-n=\"1111\">2</sup> (ישעי' נ\"א), בשני כו', בשלישי יקוו המים וכתיב והחרים הוי' את לשון ים מצרים. ולהבין זה, וגם להבין מהו ענין שצריך להחרים את לשון ים מצרים לע\"ל שהרי נא' אח\"כ והניף ידו על הנהר ולמה להנפת ידו על הנהר צריך להחרים את לשון ים מצרים, ואם צריך להחרים את לשון הים הי' צ\"ל ההנפה אח\"כ על הים עצמו, וגם מהו לשון הים.\n<b>ויובן</b> בהקדם פי' והחרים<sup data-n=\"1112\">3</sup> שת\"י פי' לשון ויבש וכן פי' רש\"י, ובמכלול פי' ענין כריתה וגזירה כענין שאה\"כ לגוזר י\"ס לגזרים, וכענין כל חרם בישראל, כל חרם אשר יחרם, והיינו שענין החרם אשר יחרם לה' הגם כי אין הדבר נשחת ונאבד וכלה, אמנם מן האדם המקדישו נחרם ממנו שה\"ה מוחרם ומשחת ממנו לבלי יהנה מהם. ובפי' והכהו לז' נחלים פי' הת\"י לשבעא נחלין, ורש\"י פי' לז' גזרים לעבור בו<sup data-n=\"1113\">4</sup> ז' גליות האמורים למעלה והיינו מאשור וממצרים ומפתרוס כו', והמכלול עשה בפי' כמו פשרה בין הת\"י לרש\"י לחבר ב' פירושים להיות אחד, והיינו שפי' שהעמק שבו המים נגרים יקרא נחל גם כשאין המים עוברים בו, כמו ויחפרו עבדי יצחק בנחל וכמו ענין נחל איתן.",[["1110","1","<b>והחרים</b>: ברשימת המאמרים כותב כ\"ק אדמו\"ר זי\"ע אודות מאמר זה: מכאן עד סד\"ה וביום הביכורים הוא המשך הנודע בשם והחרים תרל\"א\", ונדפס בשם לקו\"ת תורת שמואל שער ב' [ברוקלין, תש\"ה]. בהוצאה הנ\"ל נדפס בפוטוגרפיא מכת\"י הר\"ש סופר, וכאן נדפס לראשונה באותיות מרובעות מגוף כתי\"ק כ\"ק אדמו\"ר מהר\"ש. וכן חלקנו את ההמשך לפרקים, לתועלת הלומדים ומעיינים.\nלהתחלת המאמר ראה ד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080258\" data-slug=\"or-hatorah-hb\" data-id=\"8160080258\">אוה\"ת נ\"ך (כרך א) ע' קצא</a>-ב. וראה לכללות המאמר: סידור עם דא\"ח רפט, ד ואילך. מאמרי אדה\"ז פרשיות ח\"א ע' רנח ואילך. רסו ואילך. מאמרי אדהאמ\"צ ויקרא ח\"א ע' ריב ואילך. רנ ואילך. שער האמונה לאדהאמ\"צ פנ\"ב ואילך (פג, א ואילך). וראה לקמן ע' שסד ד\"ה הבל הבלים שהוא רישומי דברים ממאמר זה.\nעניני המאמר הובאו ונתבארו בד\"ה זה בסה\"מ תשי\"ג ע' 386 ואילך. תשכ\"ט ע' קעה ואילך. תשל\"ד ע' 115 ואילך. תשמ\"ה ע' 162 ואילך. וראה גם ד\"ה זה תשמ\"ט (סה\"מ מלוקט ח\"ג ע' קכז)."],["1111","2","<b>בראשון בראשית ברא. . את השמים וכתי' כי שמים כעשן נמלחו</b>: הרי שסופן להבל ולכליון (פי' המ\"כ לקהלת רבה שם)."],["1112","3","<b>ויובן בהקדם פי' והחרים</b>: בהבא לקמן בפיסקא זו ראה ד\"ה והחרים ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600191\" data-slug=\"or-hatorah-hb\" data-id=\"8316600191\">אוה\"ת נ\"ך (כרך א) שם ע' קצא</a>-ב."],["1113","4","<b>ורש\"י פי' לז' גזרים לעבור בו</b>: ראה ד\"ה והחרים באוה\"ת נ\"ך שם (בפי' רש\"י): לפי\"ז פי' נחלים אינו נחל מלא מים, אלא ענין מישור."]]],[2000510344,"<b>אך</b> באמת י\"ל שפליגי בפלוגתא שבין פי' הזהר והאריז\"ל בענין קרי\"ס<sup data-n=\"1114\">5</sup>, שלפי' הזהר הי' הקריעה בי\"ס בחי' מל' סופא דכל דרגין ועלו בי\"ע לאצי', והאריז\"ל פי' שע\"י הקריעה במל' דאצי' בחי' י\"ס סופא דכל דרגין נתגלה האצי' בבי\"ע. וכמו\"כ י\"ל דפליגי הת\"י ורש\"י בקריעת הנהר דלע\"ל כשיניף ידו על הנהר והכהו לשבעה נחלים, שלפי' הת\"י יהיו ז' נחלים היינו שע\"י הקריעה והבקיעה של הנהר הוא בחי' בינה דאצי'<sup data-n=\"1115\">6</sup> יתגלה בחי' ז\"ת דעתיקא בז\"א, ולכך פי' שיהי' ז' נחלין היינו ז' המשכות כנודע מענין מקור מעין נהר<sup data-n=\"1116\">7</sup>, ונהר ונחל הם בחי' אחת וה\"ז כפי' האריז\"ל בקרי\"ס. ורש\"י ס\"ל בהכאת הנהר דלע\"ל כמו הזהר בקרי\"ס שהעלי' היא מלמטלמ\"ע שבי\"ע עלו באצי' ולכן כמו בקרי\"ס שנקרע הים לי\"ב קרעים בכדי שכל שבט יעלה במסילתו כן בנהר דלע\"ל יהי' הקריעה לז' גזרים בכדי שכאו\"א יעלה במסילה בפ\"ע. אך עדיין צ\"ל לדברי שניהם למה קרי\"ס הי' לי\"ב גזרים נגד י\"ב שבטים, ובהכאת הנהר דלע\"ל יהי' לז' נחלים<sup data-n=\"1117\">8</sup> וא\"כ איך יתעלו י\"ב שבטים בז' מסילות ובע\"כ יעלו יותר משבט אחד במסילה, ולפי\"ז הי' די אם הי' נקרע לב' חצאין, ומהו מספר ז' נחלים דוקא ולא ד' שהי' כנגד ד' דגלים.\n<b>אך</b> הענין יובן בהקדם הבנת הענין<sup data-n=\"1118\">9</sup> למה הי' צריך להיות קרי\"ס ביצ\"מ, שכל האותות והמופתים שהי' ביצ\"מ הי' למען רבות מופתי, והכל הי' כדרך הנלחם בתכסיסי מלחמה, כמו שפי' רש\"י שבתחלה מקלקל מימיו<sup data-n=\"1119\">10</sup> ונתן טעם לסדר היו\"ד מכות, עד ששלחם פרעה ומיהר לשלחם כמ\"ש ותחזק מצרים על העם למהר לשלחם כי אמרו כולנו מתים, ולמה הי' צריך עוד לקרי\"ס הלא כבר יצאו ממצרים, ואם מפני לברוח מפרעה הלא הי' אפשר באופן אחר, ואם מפני לנער מצרים בים הי' אפשר להמיתם ולבערם באופן אחר, ובפרט כי באותו צד שירדו בו עלו<sup data-n=\"1120\">11</sup>, אשר מזה מובן שהצורך הוא רק שילכו ישראל ביבשה בתוך הים לאיזהו תועלת, והיינו בכדי שעי\"ז",[["1114","5","<b>בפלוגתא שבין פי' הזהר והאריז\"ל בענין קרי\"ס</b>: ראה סידור עם דא\"ח רפט, ד ואילך. מאמרי אדה\"ז פרשיות ח\"א ע' רנח ואילך. מאמרי אדהאמ\"צ ויקרא ח\"א ע' ריב ואילך. רנ ואילך. שער האמונה לאדהאמ\"צ פנ\"ד (פו, ב ואילך)."],["1115","6","<b>הקריעה והבקיעה של הנהר הוא בחי' בינה דאצי'</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, א</a> ואילך. ובכ\"מ."],["1116","7","<b>כנודע מענין מקור מעין נהר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381284\" data-slug=\"likkutei-torah\" data-id=\"4001381284\">לקו\"ת שה\"ש לט, א</a>-ב. מאמרי אדה\"ז תקס\"ח ח\"ב ע' תריא ואילך. הנחות הר\"פ ע' סו. אוה\"ת פנחס ע' א'קנד. שה\"ש (כרך ג) ע' תתקמז-ח. וראה גם סידור עם דא\"ח קד, א."],["1117","8","<b>קרי\"ס. . לי\"ב גזרים. . ובהכאת הנהר. . לז' נחלים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, רע\"א</a>. מאמרי אדה\"ז פרשיות ח\"א ע' רנד. וע' רסו. שער האמונה לאדהאמ\"צ פג, סע\"א."],["1118","9","<b>אך הענין יובן בהקדם הבנת הענין</b>: בהבא לקמן בפיסקא זו ראה מאמרי אדה\"ז פרשיות שם ע' רנה. וע' רסז. שער האמונה שם פג, ב ואילך."],["1119","10","<b>כמו שפי' רש\"י שבתחלה מקלקל מימיו</b>: ראה פירש\"י וארא ח, יז (אודות עשר המכות): ויש טעם בדבר באגדה בכל מכה ומכה למה זו ולמה זו, בטכסיסי מלחמות מלכים בא עליהם, כסדר מלכות כשצרה על עיר בתחלה מקלקל מעיינותיה, ואח\"כ תוקעין עליהם ומריעין בשופרות ליראם ולבהלם, וכן הצפרדעים מקרקרים והומים וכו', כדאי' במדרש רבי תנחומא."],["1120","11","<b>כי באותו צד שירדו בו עלו</b>: ראה תוד\"ה כשם ערכין טו, א: שישראל לא עברו הים לרחבו מצד זה לזה שא\"כ היו ממהרים ללכת אל א\"י, אלא רצועה אחת עברו בים לאורך הים עד שפנו למדבר לצד אחד כו' לאחר שהלכו כחצי גורן עגולה."]]],[2000510345,"יבואו לאיזהו גילוי נעלה מאד שבלא ההילוך ביבשה בתוך הים לא הי' באפשרם לבוא לבחי' גילוי גדול זה, וצ\"ל מהו הגילוי שהוצרכו גינו לירד בתוך הים.\n[ב)] <b>ויובן</b> בהקדם ענין יציאת מצרים ומהו בחי' מצרים בעבודה שבנפש, והענין הוא שכמו ששעבוד מצרים הי' בחומר ובלבנים הגשמי' בעול קשה ודחיקה ונגישה בבחי' שעבוד וסבלות מצרים וכמ\"ש והנוגשים אצים כו' ויוכו שוטרי בנ\"י כו', כן ברוחניות הנה ירידת הנשמה בגוף היא צורך עלי', וכאשר אינו מתעלה ע\"י מניעת הגוף וכ\"ש בעשותו אחת ממצות ה' אשר לא תעשינה שזהו ע\"י הגברת יצרו הרע אשר מושל ושולט עליו, והרי מאסר הגוף ונה\"ב המה יותר גרוע הרבה מכמו היושב במאסר שכמ\"ד<sup data-n=\"1121\">12</sup> לפניו, אבל מאסר הגוף הוא גרוע הרבה שהרי בעל כרחך אתה חי, וכ\"ז בא לו ע\"י אשר אינו שליט ברוחו לכלוא את הרוח הוא הכח המתאוה שבנפשו הבהמית, שאפי' גם בתאוות היתר צריך לאכפי', שהרי מן ההיתר יכול לבוא לאיסור וכמ\"ש הוי מושכי העון בחבלי השוא וכעבות עגלה חטאה (ישעי' ה' י\"ח), פי' ענין חבלי השוא הוא חבל דק אשר מצד עצמו הוא לשוא נחשב, ומ\"מ בריבוי חבלים דקים<sup data-n=\"1122\">13</sup> אשר מצ\"ע לשוא נחשבו אמנם ע\"י ריבוים נעשה כעבות עגלה, כן הוא בענין החטא והעון אשר כל א' מצ\"ע נדמה לו שהוא שוא, כמו דקדוק קל שבדברי סופרים שיוכל המדמה לדמות הלא לשוא נחשב אם לא יקיים דקדוק זה שבד\"ס, אמנם באמת לא כן הוא, ומלבד מה שדברי סופרים בעצם הם בחי' היותר גבוה וכמארז\"ל במשנה חומר בדברי סופרים מד\"ת שהרי האומר אין תפילין כו', הרי מקיבוץ הרבה דקדוקי' מד\"ס נעשה כעבות עגלה חטאה גם לפ\"ד המדמה כו', ועוד שמחבלי השוא יוכל לבא לידי עוונות חמורים שהם כעבות עגלה, וכמארז\"ל היום אומר לו כך ומחר אומר לו כו' עד לך עבוד כו'. וכאמרם ז\"ל גבי בן סורר ומורה ימות זכאי ואל ימות חייב, הרי ממילוי תאוות לבו באכילה ושתי' הגשמיי' יוכל לבוא לאיסורים חמורים עד שע\"פ ד\"ת ימות זכאי במיתה חמורה דסקילה שזהו הוראה על חומר העון שיוכל לבוא מתאוות אכילה ושתי', דאל\"כ למה אין דינו בסייף או חנק, אלא שע\"י מלאת תאוות לבו באכילה ושתי' יוכל לבוא לאיסורים חמורים עד שדינו בסקילה בעודו זכאי, מהיות כי כ\"כ הדבר ברור בעיניהם ז\"ל שאמרו אמרה תורה ימות זכאי כו', וכ\"ש משארי תאוות הגוף ונה\"ב שיוכל לבוא ע\"י לעוונות ופשעים החמורים מאד כו'.\n<b>וע\"י</b> ריבוי התאוות מלבד שיוכל לבא לאיסורי' חמורים הנה מתגשם לבו עד שנעשה כלב האבן לבלי ישים אל לבו כלל וכלל התבוננות אלקותו ית', וגם כשישים אל לבו בעת מן העתים אינו פועל כלל לבוא לאיזה מדה שבלב באהבה או ביראה כו', והיינו מפני טמטום הלב וטמטום המוח שמטומטם מכל צד כאבן וכמארז\"ל חמרא דפרגיתא ומיא דיומסוס קיפחו עשרת השבטים, ור\"א בן ערך איקלע",[["1121","12","<b>שכמ\"ד</b>: שכמה דרכים."],["1122","13","<b>בריבוי חבלים דקים. . נעשה כעבות העגלה</b>: ראה בכ\"ז סה\"מ תשט\"ז ע' 523. ועוד."]]],[2000510346,"להתם אימשך אבתרייהו ועקר תלמודו בעי למקרא בספרא אמר החרש הי' לבם תמורת החדש הזה לכם, ופי' המפרשים שלמה אמר דוקא החרש הי' לבם הוא מהיות כי נעשה לבו אטום<sup data-n=\"1123\">14</sup> כחרש, ע' בד\"ה החדש הזה לכם (חורף ך\"ו<sup data-n=\"1124\">15</sup>), וכ\"ז בא לו ע\"י חמרא דפרגיתא ומיא דיומסוס. וי\"ל כי ע\"י חמרא דפרגיתא בא לידי טמטום הלב, כי יין הוא בחי' בינה ובינה ליבא לכן ע\"י בחי' היין הנ\"ל בא לידי טמטום הלב, וכאמרז\"ל במשנה במדה שאדם מודד בה מודדין, וע\"י מיא דיומסוס בא לבחי' טמטום המוח<sup data-n=\"1125\">16</sup> שע\"י התענוג שבא לו מרחיצה במיא דיומסוס בא לידי טמטום המוח. ושרש ההפרש שביניהם בעבודה שבנפש, טמטום הלב הוא שגם כאשר מתבונן באיזהו דבר התבוננו' בגדולת הבורא עכ\"ז אינו פועל לבוא לידי מדה שבלב באהוי\"ר מחמת טמטום הלב, וטמטום המוח הוא שגם להתבונן אינו יכול מחמת אטימת מוחו כו'.\n[ג)] <b>וביאור</b> הענין צ\"ל תחלה ענין טמטום הלב שהוא שנעשה לבו אטום ומטומטם כאבן שהגם שהוא מתבונן בשכלו היטב ומבין הדבר לאשורו, עד\"מ כשרואה העולם ומלואו ה\"ה מבין היטב שבהכרח יש מי שברא אותו שהרי אין הדבר עושה א\"ע שזהו כלל מונח כידוע, וכאשר מתבונן בזה היטב הי' צריך להיות בבחי' התפעלות אהוי\"ר לאלקותו ית' שברא ויצר הכל, אלא שזהו ענין טמטום הלב הגם שמבין היטב מ\"מ אינו מתפעל מזה כלל, לבוא לבחי' הולדת אהוי\"ר בחי' דו\"ר כ\"א נשאר כמו קודם שהשכיל והבין הדבר, מחמת טמטום לבו שאטומה מלקבל בחי' הדעת וההתקשרות שמזה בא ההולדה, וכמו הולדה גשמי' שבא מבחי' דעת דוקא כמ\"ש והאדם ידע וכנודע שהטיפה נמשכת ע\"י חוט השדרה דרך ח\"י חוליות שבה, אמנם צ\"ל כלי לזה, שבלא המקבל לא יוליד כלום, כן בבחי' הדעת והשגה שבאלקות דהן אמת שע\"י הדעת הוא עיקר הולדת אהוי\"ר כי הדעת הוא מפתחא דכליל שית כמ\"ש בד\"ה ואני תפלתי<sup data-n=\"1126\">17</sup>, להיות כי הדעת הוא מקשר ומחבר בחי' המוחין להביא מהם להיות גילוי המדה, מ\"מ אם לא יהי' כלי לקבל לא יועיל כלל גם התקשרו' דעתו. וענין הכלי בנפש הוא ע\"פ מה שנודע מארז\"ל ברכות ד\"מ לא כמדת בשר ודם מדת הקב\"ה, מדת בשר ודם כלי ריקן מחזיק ומלא אינו מחזיק, והיינו כאשר מלא מכל מיני תאוות רעים מתענוגי ותפנוקי גופו ונה\"ב. והענין הוא דלכאורה יפלא למה יומשך העונש למי שמהלך אחר עצת היצה\"ר הלא יוכל לזכות א\"ע במה שניתן לו יצה\"ר ומה יעשה, ולפי\"ז איננו חייב בדבר כלל, וכמ\"ש לא אוסיף להכות כו' כי יצר לב האדם רע כו', וא\"כ למה יומשך עליו העונש, אלא שבאמת נה\"ב הוא כח המתאוה לבד<sup data-n=\"1127\">18</sup>, ומה שחפץ ומתאוה לתאוות רבים זהו מחמת שהוא הוא אשר",[["1123","14","<b>ופי' המפרשים. . כי נעשה לבו אטום</b>: ראה חדא\"ג מהרש\"א לשבת קמז, ב (הובא בסה\"מ תרכ\"ו דלקמן)."],["1124","15","<b>בד\"ה החדש הזה לכם חורף (ך\"ו)</b>: סה\"מ תרכ\"ו ע' ל ואילך."],["1125","16","<b>טמטום הלב. . טמטום המוח</b>: בהבא לקמן ראה מאמרי אדה\"ז הקצרים ע' תפב-ג. אוה\"ת שמיני (כרך ב) ע' תפ ואילך. סה\"מ תרכ\"ו ע' סח ואילך. ד\"ה לפיכך נקראו בסה\"מ תשט\"ז ע' 477 ואילך."],["1126","17","<b>כמ\"ש בד\"ה ואני תפלתי</b>: תרל\"א (לעיל ע' רנא-ב)."],["1127","18","<b>שבאמת נה\"ב הוא כח המתאוה לבד</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חוקת נו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380964\" data-slug=\"likkutei-torah\" data-id=\"4001380964\">דרושים לר\"ה סא, ב</a>. סה\"מ תרכ\"ט ע' קא-ב."]]],[2000510347,"הלביש את כח המתאוה שבנפשו הבהמי' בלבושי' צואים וצייר בה ציורים רעים, שהוא הוא המתחייב בנפשו למה הלבישה וציירה בציור רע מכל מיני תאוות רעות היתר ואיסור ח\"ו, שהרי בכח המתאוה עצמו שבנפשו הי' יכול לעבוד את ה' כמ\"ש בכל לבבך בשני יצריך, אלא שהוא קלקל והעביר את הדרך הטוב והישר בעיני אלקי' ואדם להלבישה ולציירה בלבושי' וציורים רעים מכל מיני רע, שגם תאוות היתר בכלל רע הוא, רק שהוא בדקות יותר בחי' רע דנוגה כידוע, וכמ\"ש מזה בכ\"ד באורך, ע' בד\"ה וידבר דמטות יהי לבי תמים<sup data-n=\"1128\">19</sup>, וע\"י שהוא מלא ותאב למלאות תאוות וזדון לבו אשר השיאו, ה\"ה כלי מלא מתאוות רבות ולכן אינו מחזיק. וזהו שרש ענין טמטום הלב שאטום כחרש מחמת תאוות לבו כו', וכ\"ש אם נמצא בו חוצפא וגסות ועקשות הרי אין אני והוא יכולים לדור כו', וגם אם אוהב גופו ונה\"ב למלאות רצונותיו הזרים הרי אהבת גופו ואהבת השי\"ת שני דברים הפכים הם, וקצר המצע מהשתרע שני ריעים כאחד הוא תאוות ואהבת הגוף ואהבתו ית', ולכן צריך לעשות כלי ריקן הוא להיות לבו ריקן מכל התאוות וחמדת שעשועי בנ\"א בתאוות הגופניות, ולשום רעיוניו בגדולת הבורא, ואז הרי הוא כלי המחזיק ברכה והמשכת אלקותו ית', כי כלי ריקן מחזיק, ע' בד\"ה הנותן לשכוי בינה<sup data-n=\"1129\">20</sup>, מענין ואמונה כל זאת.\n<b>וזהו</b> שרש ענין יצ\"מ בנפש האדם לצאת ממאסר הגוף ונה\"ב והגבלותיו שזה יכול וזה אינו יכול, עד שיהי' לבו תאוב ופתוח להמשכת אלקותו ית', וזהו יצ\"מ בנפש, שכמו בגשמיות יצאו ישראל משעבוד מצרים, כן ברוחניות כשיוצא ממאסר הגוף, ונפשו הבהמי' תצא מלבושי' צואים וציורים רעים אשר צייר בה כנ\"ל, אז הרי הוא חפשי לגמרי מכל הנהגותיו והגבלותיו שהיו עד כה שהם אשר יטרידוהו תמיד לטרוח ולחפש עדי ימצא מקום למלאות תאוות נפשו כו', ואז ה\"ה כקטן שנולד ורואה עולם חדש ממש, ובכדי שיוכל לבוא לקבל התורה שזהו לעומת ממש נגד יצרו הרע ושעשועי בנ\"א בתענוגי בנ\"א, שהרי אמרו ז\"ל כך היא דרכה של תורה פת במלח תאכל ומים במשורה תשתה ועל הארץ תישן שזהו היפך הרגלו בתענוגי ותפנוקי בנ\"א להתעדן באכילה ושתי' ושארי דברים המעדנים גופו, וכמו ישראל כשיצאו ממצרים הרי הם יצאו מאפילה לאור גדול כו' ומשעבוד לגאולה כו'.\n[ד)] <b>והנה</b> נודע כי יצ\"מ הי' הקדמה למ\"ת שזה מובן, וגם ענין שעבוד מצרים מה שהוא הקדמה למ\"ת זהו ג\"כ מובן, שזהו כמו האומן כשעושה כלי צריך ליתן תחלה הכסף בכור לצרפו<sup data-n=\"1130\">21</sup> מהפסולת, כי לבד מה שהכסף איננו נקי הרי לא",[["1128","19","<b>וכמ\"ש מזה בכ\"ד באורך ע' בד\"ה וידבר דמטות </b>[אוצ\"ל: דחוקת]<b> יהי לבי תמים</b>: ראה לעיל ד\"ה וידבר גו' זאת חוקת ע' רטז. וש\"נ. [נק' בכ\"מ בדרושי אדמו\"ר מהר\"ש בשם: וידבר גו' חוקת יהי לבי תמים]. וד\"ה זה בסה\"מ תרכ\"ט ע' קא-ב."],["1129","20","<b>בד\"ה הנותן לשכוי בינה</b>: מאמרי אדה\"ז תקס\"ב ח\"ב ע' שצו. ובתוס' הגהות ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ע' א'תד</a>."],["1130","21","<b>שעבוד מצרים. . הקדמה למ\"ת. . כמו. . הכסף בכור לצרפו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370221\" data-slug=\"torah-or\" data-id=\"3901370221\">תו\"א שמות מט, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370328\" data-slug=\"torah-or\" data-id=\"3901370328\">יתרו עד, סע\"א</a>-ב."]]],[2000510348,"יוכשר למלאכה בעודו מעורב עם הפסולת, כך בכדי שיקבלו ישראל את התורה הוצרכו תחלה להיות במצרים בשעבוד קשה בכדי לזככם שיוכלו לקבל התורה. אך ענין קרי\"ס יפלא למה היו צריכים לילך בים שנת\"ל שזהו לאיזה תועלת והיינו ג\"כ הכנה למ\"ת, ולכאו' אינו מובן כלל למה צריכין לילך בים קודם קבלת התורה, ומה ניתוסף בנפשותיהם כשהלכו בים עד שמזה יהי' תועלת לקבלת התורה.\n<b>אך</b> הענין הוא דבצאת ישראל ממצרים לא נזדככו בנפשותם עדיין ולא היו רק בבחי' אמונה בלבד וכמ\"ש ויאמן העם, וישמעו כי פקד ה', ונודע כי שמיעה הוא מרחוק עדיין ששומע הדבר, ומהיות כי אינו דומה שמיעה לראי'<sup data-n=\"1131\">22</sup> שראי' הוא הנחה היותר נעלה בנפש כו', ע' בד\"ה פקח עיניך וראה, ובקרי\"ס נא' וירא ישראל כו' ויאמינו, שהיתה האמונה בבחי' ראי' והכרה, והיינו כי יצ\"מ וקרי\"ס הי' הכנה למ\"ת ובמ\"ת נא' וכל העם רואים את הקולות רואים את הנשמע ושומעין את הנראה, להיות כי פרחה נשמתן על כל דיבור ודיבור עד שבאו לעצם פנימיות נקודת הנפש אשר שם ראי' ושמיעה בלתי מחולקים כלל, שהרי התחלקותם הוא רק כשמתגלים בכחות נפשו בהתלבשות כאו\"א בכלי האבר הראוי' לו כח הראי' בעין וכח השמיעה באוזן, אמנם כמו שהן כלולים בנפשו א\"א לחלוק עדיין ולומר שזהו כח הראי' וזהו כח השמיעה כו', ולכן במ\"ת שעל כל דיבור ודיבור פרחה נשמתן הגיעו לשרש ומקור פנימיות נקודת הנפש אשר היא בלתי התחלקות עדיין כנ\"ל, ולכן היו יכולים לראות את הנשמע ולשמוע את הנראה כו', והוצרכו לכ\"ז בכדי שעי\"ז יוכלו לקבל מ\"ת בחי' אנכי ולא יהי' לך שמפי הגבורה שמענו זהו כלליות כל התרי\"ג מצות, אנכי כולל רמ\"ח מ\"ע ולא יהי' לך כולל כל שס\"ה ל\"ת, לכן הוצרכו להגיע לשרש נפשם בבחי' הכלליות, ומהיות כי גם שארי הדברות הם ג\"כ כוללים לכן הי' צ\"ל שעכדו\"ד יפרח נשמתן כו', בכדי שיהיו כלי מוכן לקבל כו'.\n[ה)] <b>ובכדי</b> שיוכלו לבוא לבחי' זו זהו ע\"י הקדמת קרי\"ס<sup data-n=\"1132\">23</sup> שראתה שפחה על הים מה שלא ראו נביאים כמ\"ש רש\"י ע\"פ זה אלי והוא מהמכילתא פ' בשלח, והיינו כי מה שהלכו ביבשה בתוך הים זהו הוראה שהשיגו בעלמא דאתכסיא, כי ים ויבשה הוא בחי' עלמא דאתכסיא ועלמא דאתגליא<sup data-n=\"1133\">24</sup> והוא כמו מחשבה ודיבור כמ\"ש במ\"א, ועז\"נ ברוך כו' מן העולם ועד העולם שהוא בחי' המשכה מעלמא",[["1131","22","<b>שמיעה הוא מרחוק. . אינו דומה שמיעה לראי'</b>: בהבא לקמן ראה בארוכה המשך וככה תרל\"ז פל\"ג (ע' מד-ה). ופנ\"ז (ע' פו-ז). וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370334\" data-slug=\"torah-or\" data-id=\"3901370334\">תו\"א משפטים עה, א</a>. מאמרי אדה\"ז הקצרים ע' תקנו-ז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640221\" data-slug=\"or-hatorah-hb\" data-id=\"8316640221\">אוה\"ת</a> ויקרא (כרך ג) ע' תשד. שה\"ש (כרך א) ס\"ע רכא-ב. סה\"מ תרכ\"ט ע' רסח-ט. לקמן ד\"ה כמה גדולים יורדי הים. ועוד."],["1132","23","<b>ובכדי שיוכלו לבוא. . זהו ע\"י הקדמת קרי\"ס</b>: בהבא לקמן בפיסקא זו ראה בארוכה מאמרי אדה\"ז פרשיות שם ע' רנה ואילך. וע' רסז ואילך. שער האמונה לאדהאמ\"צ שם פד, א ואילך."],["1133","24","<b>ים ויבשה. . עלמא דאתכסיא ועלמא דאתגליא. ֿ. כמו מח' ודבור כמ\"ש במ\"א</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380143\" data-slug=\"likkutei-torah\" data-id=\"4001380143\">לקו\"ת צו טז, ד</a> ואילך. מאמרי אדה\"ז פרשיות ע' רנה ואילך. וע' רסז ואילך. שער האמונה לאדהאמ\"צ פנ\"ב ואילך (פד, א ואילך)."]]],[2000510349,"דאתכסיא בעלמא דאתגליא, אמנם בקרי\"ס כשהים נעשה יבשה זהו הוראה שהים בחי' עלמא דאתכסיא נעשה יבשה הוא בחי' עלמא דאתגליא, שזהו לדברי ב' הפי', רק שלפי דמשמע מהזהר עלה בי\"ע באצי', ולדברי האריז\"ל נמשך האצי' בבי\"ע, אך לדברי שניהם נתגלה ונתחבר אצי' עם בי\"ע, פי' נתחבר שגם בנבראי' דבי\"ע נעשה כמו באצי', וכנודע ההפרש בין ברואי' שבים לברואי' שביבשה, שכל מה שיש ביבשה יש בים רק שהברואים שביבשה הגם כי הם מקבלים חיות מהיבשה הוא הארץ שתוציא צמחה, מ\"מ הרי הם נפרדים מהארץ ויכולים לחיות באויר גבוה הרבה מהארץ, אבל ברואים שבים הם מובלעים במי הים והים מובלע בתוכם שזהו בחי' מקיף ומוקף, שלכן אינם טעונים שחיטה להיות כי מבריאות המים המה, ובדגים נא' אסיפה ואסיפתן זהו שחיטתן, כי כשפורשין מן המים מיד מתים כו'. אמנם הנה כתי' וידגו לרוב בקרב הארץ שיהי' גם בארץ בחי' ומדריגת דגים שבים, שגם בקרב הארץ יהי' כן, והיינו ע\"י הקדמת קרי\"ס שהים נעשה יבשה, ונמצא כי ברואי' שביבשה הלכו בחרבה בים הוא בחי' עלמא דאתכסי', ועי\"ז יכול להיות אח\"כ שידגו לרוב בקרב הארץ היינו שגם בארץ יהיו במדרי' כמו הדגים שבים, וכמו המלאכי' שנקראי' בשם נוני דימא רבא ונשמות הגבוהות כנשמת משה שנא' בו כי מן המים משיתיהו, ולכן המלאך יכול לומר ע\"ע בי נשבעתי<sup data-n=\"1134\">25</sup>, וכתי' ותקרא שם הוי' הדובר אלי' הגם שזה הי' מלאך, וכן משה אמר ונתתי מטר ארצכם כו', והיינו מפני עוצם הביטול שלהם לאלקות היו יכולים לומר על עצמם שם הוי' או ונתתי כו', ועד\"ז יובן ענין וידגו לרוב בקרב הארץ שגם בארץ יהיו כמו דגים שבים בבחי' הביטול דמלאכים ונשמות שהם בחי' נוני דימא רבא כו'. אך כדי לבוא לזה זהו ע\"י הקדמת קרי\"ס דוקא ולא די בעשר מכות באותות ומופתים שהיו במצרים, כ\"א דוקא לילך ביבשה בתוך הים ולבוא לבחי' אמונה ע\"י ראייתם שראו היד הגדולה כמ\"ש וירא ישראל כו' וכמשי\"ת לקמן אי\"ה<sup data-n=\"1135\">26</sup>, וכ\"ז הוא ע\"י הים דוקא בחי' עלמא דאתכסיא שנעשה יבשה בחי' עלמא דאתגליא כו'.\n[ו)] <b>וכדי</b> להיות קרי\"ס זהו ע\"י שהוליך הוי' ברוח קדים עזה הוא בחי' ההמשכה מבחי' א\"ס ב\"ה קדמונו ש\"ע, ולכן אמרו בזהר ע\"פ מה תצעק אלי בעתיקא תליא מילתא, ומחמת גילוי עצום כזה יוכל כל איש זר אשר לא טעם טעם עבודה כלל כמו ישראל שהיו במצרים שהיו מושקעים במ\"ט שע\"ט, מ\"מ ע\"י שברח העם מבחי' הרע שבנפשם, ואם כי עדיין הי' הרע בתוקף ובשלימות מ\"מ ע\"י כי ברח העם יכלו לילך בים ביבשה, להיות כי מחמת עוצם ותוקף הגילוי דקרי\"ס יכול כל איש זר לקרב אל הקדש פנימה עד שכל שפחה ראתה על הים מה שלא ראה",[["1134","25","<b>המלאך. . על עצמו בי נשבעתי. . וכן משה אמר ונתתי מטר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380290\" data-slug=\"likkutei-torah\" data-id=\"4001380290\">לקו\"ת בחוקותי נ, א</a>. סה\"מ תרכ\"ט ע' ריד ואילך. סה\"מ תרל\"ב ח\"א ע' לט. תרל\"ג ח\"א ע' נא. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031276\" data-slug=\"likkutei-sichot\" data-id=\"1300031276\">לקו\"ש ח\"ג ע' 1014</a>. ח\"ד ע' 1087. ובכ\"מ."],["1135","26","<b>וכמשי\"ת לקמן אי\"ה</b>: בד\"ה כמה גדולים יורדי הים (לקמן ע' רסח ואילך)."]]],[2000510350,"יחזקאל, להיות כי אמרו זה אלי, וכל הנביאים לא נתנבאו אלא בכה בחי' כ\"ף הדמיון ורק משה נתנבא בזה. ולכן ארז\"ל במד\"ר כמה נתחבט משה רבן של כל הנביאים עד שא\"ל וראית אחורי, וכאן כאו\"א מראה באצבע זה אלי, עד שראתה שפחה שהיא ממדריגות היותר אחרונים שבישראל כמ\"ש ראשיכם כו' עד שואב מימך שזהו מדריגה העשירית שבישראל והיא גם היא ראתה בבחי' זה כו', שזהו שמחמת תוקף ועוצם הגילוי יכול כל איש זר לקרב אל הקדש פנימה. אך מ\"מ הי' צ\"ל תחלה כי ברח העם, והיינו כי ענין ופי' איש זר אין הכוונה על זר ממש כענין שנא' ועמדו זרים שזה יהי' לע\"ל, דאל\"כ היו יכולים המצרי' ג\"כ להתקרב בהיותם בים ולמה נטבעו, אלא הכוונה בפי' איש זר כמ\"ש איש זר אשר לא מזרע אהרן הוא, פי' שהגם שהוא לוי או ישראל לזר נחשב נגד הכהן משרת ה' כו', ועד\"ז הכוונה כאן שכל איש זר יוכל להתקרב הכוונה הגם כי איננו מוכשר עדיין כלל מצד עבודתו לגילוי עצום כזה, מ\"מ יוכל להתקרב עד שגם שפחה שהיא ממדרגות היותר אחרונו' הוא מ\"ש בפ' נצבים עד שואב מימך פרט היותר אחרון, מ\"מ ראתה גם שפחה על הים, אמנם מ\"מ ניזוזו ממקומם והיא גם היא בערך לבחי' הגבוהי' שבישראל שהרי כולם היו רק בבחי' כי ברח לבד כו', וכמ\"ש בסש\"ב<sup data-n=\"1136\">27</sup>, וזהו פי' שכל איש זר יוכל לקרב אל הקדש בעת קי\"ס שהי' עלמא דחירו מחמת עוצם הגילוי מבחי' רוח קדים קדמונו של עולם.\n<b>ולכאו'</b> צ\"ל מאחר שנמשך הגילוי' מבחי' גבוה מאד נעלה למה משם יומשך הדקדוק שדוקא מי שהוא זר ע\"ד שפירשנו ולא זר ממש כפשוטו. אך הענין הוא ע\"ד שמצינו שארז\"ל ע\"פ לשארית נחלתו ולא לכל נחלתו למי שמשים עצמו כשיריים, שג\"ז יפלא מאחר שנמשך להיות נושא עון ועובר על פשע ומדוע דוקא למי נושא עון למי שעובר על פשע ולמי שמשים עצמו כשיריים. אך הענין דמי שאינו משים עצמו כשיריים ה\"ה אינו כלי לקבל גילוי הוי' מבחי' רב חסד שנושא עון כו', ולכן צ\"ל משים עצמו כשיריים בכדי שיהי' קצת כלי לקבל מבחי' זו דרב חסד שלמעלה מהשתל' וכמ\"ש בת\"א פ' ויקהל<sup data-n=\"1137\">28</sup> דבחי' חסד זוטא הוא כלי לקבל מבחי' רב חסד, שרצון התחתון הוא כלי לקבל רצון העליון, וע' בד\"ה והי' שארית יעקב בקרב עמים רבים (למ\"ד<sup data-n=\"1138\">29</sup>).\n<b>ועד\"ז</b> יובן כאן שבכדי שיוכל גם שפחה לראות וכמו\"כ כללות ישראל הי' צ\"ל כי ברח העם הזזה ממקומם עכ\"פ, ואם כי איננו כלי עדיין להגיע באתעדל\"ת, והגילוי הוא בבחי' אתעדל\"ע שלמעלה מאתעדל\"ת כמ\"ש ואתם תחרישון לא תתערון מידי, מ\"מ היו צריכים קצת הכנה וכלי במה שיושרה גילוי עצום הלזה כו' שאז יוכל כל איש זר לבא אל הקדש פנימה, וכמו המלך בעת תוקף שמחתו וטוב לבבו מניחים הכל לבוא לראות פני המלך כמו השרים הנכבדים ועושה סעודה",[["1136","27","<b>ע\"י שברח העם מבחי' הרע שבנפשם. . וכמ\"ש בסש\"ב</b>: ראה תניא פל\"א."],["1137","28","<b>בת\"א פ' ויקהל</b>: דף פז, סע\"ד."],["1138","29","<b>בד\"ה והי' שארית יעקב. . (למ\"ד)</b>: סה\"מ תר\"ל ע' קצט ואילך."]]],[2000510351,"לכולם כמ\"ש לכל העם כו' למקטן ועד גדול כו', וכמו\"כ ביום ניצוח המלחמה ישראל הלכו ביבשה כו' ופרעה וכל חילו טובעו בים סוף, לכן ראתה שפחה מה שלא ראה יחזקאל שהרי כולם אמרו זה אלי כו', ע\"ד משה נתנבא בזה ויותר כמובן מהמד\"ר הנ\"ל.",[]],[2000510352,"<h3>[כמה גדולים יורדי הים]</h3>\n<b></b><b>ד\"ה כמה גדולים יורדי הים] </b>\nאך כו' כמה גדולים יורדי הים כו'\nשחרית אחש\"פ\nבס\"ד. יום אחרון של פסח.\n[ז)] <b>אך</b> הנה עדיין צ\"ל דברי המד\"ר שאמר כמה גדולים יורדי הים<sup data-n=\"1139\">1</sup> שהרי משה רבן של כל הנביאי' כמה נתחבט עד שביקש הראני נא את כבודך, ובים כולם אמרו זה אלי כל א' מראה באצבע זה אלי, שלכאו' יפלא הלא גם משה הי' מיורדי הים, ונמצא כי גם הוא ראה כמו כולם ולמה הי' צריך עוד לבקש הראני נא את כבודך, וגם משמע מהמד\"ר הנ\"ל שאמר כמה גדולים יורדי הים שמשמע שראיית הים היתה עוד יותר נעלה מראיי' משה, וכדמשמע לכאו' שהרי במשה כתי' וראית את אחורי ופני לא יראו, ובים נא' זה אלי כ\"א מראה באצבע כו', דמשמע שהי' ראיית פניו. וגם עוד נוסף לזה שמשה ראה ע\"י שביקש תחלה ובים הי' בלתי שום בקשה כלל, וכמ\"ש ואתם תחרישון לא תתערון מידי וכמו שפי' רש\"י שג' כיתות היו<sup data-n=\"1140\">2</sup> כו', א\"כ הלא נודע שכל דבר שבא באתעדל\"ע בלתי אתעדל\"ת ה\"ה גבוה יותר, ובפרט בים שנא' להם ואתם תחרישון מובן שלמה ציוה ה' להם להחריש זהו מפני כי בחי' זו הוא אתעדל\"ע שלמעלה מאתעדל\"ת, וא\"כ יפלא ביתר שאת למה ביקש משה עוד הראני נא את כבודך ולא פעל כל בקשתו שהרי אמר לו ופני לא יראו כו'. וגם צ\"ל הלא נמצא בדרשי רז\"ל בגמ' סוטה די\"א ב' ובמד\"ר שאמרו זה אלי שהכירו שזהו שהציל אותנו מגזירת פרעה כל הבן הילוד, שהיו נשי ישראל יוצאו' ומולידו' בשדה, שאמרו שם וכיון שמגיע זמן מולידיהם הולכות ויולדות בשדה תחת התפוח שנא' (שה\"ש ח) תחת התפוח עוררתיך, והקב\"ה שולח משמי מרום מי שמיקר<sup data-n=\"1141\">3</sup> ומשפיר אותם כחיה זו שמשפרת את הולד שנא' (יחזקאל ט\"ז) ומולדתיך ביום",[["1139","1","<b>אך הנה עדיין. . כמה גדולים יורדי הים</b>: מאמר זה הוא המאמר השני שבהמשך והחרים תרל\"א\".\nלהתחלת המאמר ראה גם ביאוה\"ז להצ\"צ ח\"ב ע' תשמז ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950442\" data-slug=\"or-hatorah-hb\" data-id=\"8315950442\">אוה\"ת בשלח ע' תמב</a>. וע' תקל."],["1140","2","<b>וכמו שפי' רש\"י שג' כיתות היו</b>: לע\"ע לא נמצא זה ברש\"י שלפנינו. וראה ירושלמי תענית פ\"ב ה\"ה (ועד\"ז במכילתא ותיב\"ע בשלח יד, יג-יד. יל\"ש שם רמז רלג בתחלתו): ארבע כתות נעשו ישראל על הים, אחת אומרת נפול לים, ואחת אומרת נחזור למצרים, ואחת אומרת נעשה עמהן מלחמה, ואחת אומרת נצווח כנגדן. [וראה תורה שלמה בשלח שם (אות פא) שבכ\"מ הגירסא: ג' כיתות]."],["1141","3","<b>שמיקר</b>: בגמ' סוטה שלפנינו: שמנקיר. ובפירש\"י שם: מנקיר, מנקר."]]],[2000510353,"הולדת אותך לא כרת שרך ובמים כו', ומלקט להם שני עיגולי' א' של שמן וא' של דבש שנא' (האזינו ל\"ב) ויניקהו דבש מסלע ושמן כו', וכיון שמכירין בהם מצרים באין להורגן ונעשה להם נס ונבלעין בקרקע ומביאין שורים וחורשין על גבם שנא' (תלים קך\"ט) על גבי חרשו חורשים כו', לאחר שהולכים היו מבצבצין ויוצאין כצמח השדה שנא' רבבה כצמח השדה נתתיך, וכיון שמתגדלים באים עדרים עדרים לבתיהם שנא' ותרבי ותגדלי ותבואי בעדי עדיים, א\"ת בעדי עדיים אלא בעדרי עדרים, וכשנגלה הקב\"ה על הים הם הכירוהו תחלה שנא' זה אלי ואנוהו, ופרש\"י הם הכירוהו תחלה שראו שכינתו כבר, זה אלי שראיתי כבר. ונמצא לפי דרש זה הי' הגילוי דקרי\"ס שוה להצלתן מגזירת פרעה כל הבן הילוד כו', דאל\"כ האיך הכירו אותו כו', וא\"כ צ\"ל מהו הרעש דקרי\"ס הלא גם מגזירת כל הבן הילוד וגו' הי' ג\"כ בחי' זו ממש. וגם צ\"ל הלא במשה כתי' ודבר ה' אל משה פא\"פ כאשר ידבר איש אל רעהו, וא\"כ הלא דבר איש עם רעהו הוא פנים כנגד פנים ולמה ביקש הראני נא את כבודך, ואם דיבר עמו ולא ראה מהו שאמר פנים אל פנים מאי נפ\"מ, וגם צ\"ל מעלת משה שדיבר עמו פא\"פ הלא בכל ישראל נא' פב\"פ דיבר ה' עמכם.\n[ח)] <b>אך</b> הענין יובן במ\"ש וירא ישראל את היד הגדולה וגו' ויאמינו<sup data-n=\"1142\">4</sup> בהוי', דלכאו' יפלא הלא כשראו מהו נופל עוד אמונה, שענין האמונה הוא רק כשהוא בעצמו אינו יודע והוא מאמין לזולתו, אבל כשרואה בעצמו מהו נופל עוד ענין האמונה, הלא בירור יותר מראי' לא נמצא כלל, וכמ\"ש והוא עד או ראה וגו', ואיך יתכן ענין האמונה אחר הראי'. אך הענין הוא דבאמת הראי' אינה במקום האמונה, שהאמונה היתה במקום היותר גבוה.\n<b>והענין</b> הוא דהנה מצינו הרבה חילוקי מדרגות בענין האמונה, וכמו שמצינו שיש אמונה שהיא בבחי' מקיף הרחוק מאד שאינו נוגע כלל אל פנימיותו, וכמארז\"ל גנבא אפום מחתרתא רחמנא קריא<sup data-n=\"1143\">5</sup>, ואם הי' נוגע לו ענין אמונה זו שמאמין באלקי מרום האיך הוא כ\"כ מרוחק שגונב ועושה היפוך הציווי דלא תגנוב והיפך בחי' רצה\"ע ב\"ה אשר ציונו לא תגנוב, ועוד הוא מבקש שיצליח לו השי\"ת שיוכל לגנוב ולא יתפסו אותו שזהו הוראה על הקריאה שקורא רחמנא, וכ\"כ מרוחק מידיעות שכלו עד שיוכל לבקש שיעזרהו ה' להצליח לו שיוכל לעשות היפך רצונו ית', ומ\"מ כשהוא קורא רחמנא הרי בקריאה זו נודע מ\"מ שמאמין הוא באלקי מרום, דאל\"כ למה יבקשהו שיעזור לו ויצליחהו, אלא שהקריאה היא בבחי' מקיף הרחוק מאד שהגם שמאמין בבחי' מקיף רחוק הלזה, עכ\"ז אינו נוגע לו כלל בפנימיותו שיוכל להוליד מזה יראת אלקים לקיים כפי ציוויו ורצונו לא תגנוב, שהרי איך יוכל להוליד מדה שבלב הלא מובן שעדיין לא הניח שכלו כלל בזה, שאם הי' משכיל",[["1142","4","<b>אך הענין יובן. . וירא ישראל. . ויאמינו</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950460\" data-slug=\"or-hatorah-hb\" data-id=\"8315950460\">אוה\"ת בשלח ע' תס</a>. סה\"מ תרכ\"ז ע' רמז."],["1143","5","<b>חילוקי מדרגות בענין האמונה. . גנבא אפום מחתרתא רחמנא קריא</b>: ראה גם סה\"מ תר\"ל ע' קח ואילך. קיא. תרל\"ב ח\"א ע' פז ואילך. ס\"ע צ-צא. ועוד."]]],[2000510354,"ומתבונן איך הי' מבקש מה' שיעזור לו שיוכל לעשות נגד רצונו ב\"ה, אלא שלא התבונן כלל, וכ\"ש שלא נמשך בבחי' הדעת שהוא בחי' ההתקשרות, שהרי רחוקים הם זמ\"ז בשני קצוות שאם הי' מקושר לא הי' עושה היפך רצונו ית', וכשהוא עושה היפך רצונו וגונב ה\"ה מרוחק בתכלית הריחוק, וכ\"כ מוחו ולבו אטומים שאינו מבין כלל ואינו מתבונן בזה שמדבר ומבקש, ומ\"מ נק' אמונה, אך ה\"ה אמונה שהיא רחוקה בתכלית הריחוק. ויש אמונה שהיא יותר קרובה ומ\"מ אינה אמונה שלימה, והוא מה שפי' ע\"פ והי' אמונת עתך שמאמין בחיי עולם וזורע<sup data-n=\"1144\">6</sup>, שזהו לא יתכן לקרות אמונה שלימה, והלא יודע היטב שכשזורעים בארץ צומח, והוא עצמו בשנה הקודם לזה זרע והצמיח, וא\"כ איך יתכן לקרות ולכנות זה בשם אמונה, והרי לא הגבילו שדוקא כשזורע בפעם הראשון, אלא שהגם שיודע היטב וראה בעצמו מ\"מ נק' זה בשם אמונה שמאמין בחיי עולם וזורע, והיינו הגם כי זהו אינה אמונה כ\"כ מ\"מ ה\"ז הוא בכלל אמונה כו'. ונמצא כי יש מדרגה שני' באמונה, ומ\"מ בחי' אמונה זו א\"א לדמותה לאמונה שאחד מאמין מה ששמע מזולתו.\n<b>ולכן</b> האמונה מה שהאמינו ישראל בהיותם תחת יד מצרים כשאמר להם משה מאמר האל פקד פקדתי ה\"ז אמונה שלימה שהאמינו לדברי משה שאמר השי\"ת כך, וגם האמינו בהשי\"ת שביכולתו להוציאם מתחת יד פרעה ושיוציאם משעבוד הקשה דמצרים, ומ\"מ אמונה זו היא האמונה שבבחי' שמיעה עדיין, שהרי כך נא' ויאמן העם וישמעו כי פקד ה' וגו' שלא הי' אמונה זה בהם רק כמו מי ששומע ומצייר הדבר ע\"פ מה ששמע ומאמין שכן הוא, אבל לא יתכן לקרות אמונה זו בשם אמונה שבא מחמת שראה איזה דבר, שהרי אינה דומה שמיעה לראי'<sup data-n=\"1145\">7</sup>, פי' שכאשר האדם שומע איזה דבר מחבירו ומאמין לו שכן הוא, נמצא הרי הוא מצייר הדבר בשכלו שיבין היטב מה ששמע מחבירו עד\"מ הגדת עד מפי עד בדברים שהתירו רז\"ל עד מפי עד כמו עדות אשה וכדומה הרי העד אינו יכול להעיד רק מה ששמע מחבירו בלתי שום תוס' כלל, וא\"כ כשבאו להעיד בעדות אשה להתירה מכבלי העיגון ע\"פ סימנים מובהקים או בטביעת עין שזהו דוקא ע\"פ הכרה בפרצוף פנים וחוטם כמ\"ש הכרת פניהם ענתה בם, שכ\"ז הוא הודאה ע\"פ בחי' שמיעה מה ששמע שמעון עד השני מראובן עד הראשון, שראובן הכיר את לוי הנטבע ע\"פ הסימנים מובהקים שהי' לו בו או ע\"פ הכרת פרצוף פנים עם החוטם, ונמצא כי שמעון הוא רק מאמין לראובן ע\"פ מה ששמע ממנו, הגם כי שמעון לא הכיר מעולם את לוי כלל כו', ולהיות כי אינו דומה שמיעה לראי' עד\"מ הנ\"ל כשמספרי' לאחד איזהו דבר והוא יודע ומבין הדבר היטב לאשורו, מ\"מ כשרואה אח\"כ הדבר הזה עצמו מתפעל ביתר שאת ויתר עז על מה ששמע תחלה, הגם כי בעצם הדבר לא",[["1144","6","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011230\" data-slug=\"likkutei-sichot\" data-id=\"1300011230\">שפי' ע\"פ</a> והי' אמונת עתך שמאמין בחיי עולם וזורע</b>: ראה שבת לא, א בתוד\"ה אמונת: אמונת זה סדר זרעים, מפרש בירושלמי שמאמין בחי העולמים וזורע. [וראה ס' אמרי בינה (למהרצ\"ח) סי' ב' שבירושלמי לפנינו ליתא]. נת' ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011230\" data-slug=\"likkutei-sichot\" data-id=\"1300011230\">לקו\"ש ח\"א ע' 216</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151383\" data-slug=\"likkutei-sichot\" data-id=\"1300151383\">240. חט\"ו ע' 370</a>. חי\"ח ע' 295."],["1145","7","<b>שהרי אינה דומה שמיעה לראי'</b>: בהבא לקמן ראה לעיל ד\"ה והחרים (ע' רסד). וש\"נ."]]],[2000510355,"ניתוסף לו כלום. אך הענין הוא שע\"י ראיית העינים מקנה בנפשו קנין דבר ההוא באופן היותר נעלה ומשובח שהרי כששמע תחלה ציירה רק ע\"פ ראיית השני שסיפר לו, אבל הוא עצמו לא ראה כלל, ואח\"כ כשרואה בעצמו גם אם אינו מתוסף אצלו שום דבר כלל מ\"מ ה\"ה באופן היותר נעלה ומשובח.\n<b>ועד\"ז</b> יובן בחילוקי מדרגות בענין האמונה שמה שהאמינו ישראל במצרים בשמעם ממשה אשר פקד ה' אותם ה\"ז אמונה בבחי' שמיעה לבד, ועכ\"ז ה\"ז אמונה בבחי' הרגשה, שהרי כך נאמר ויאמן העם וישמעו כי פקד ה' וגו' שפעל בהם האמונה עד שהרגישו בבחי' שמיעה כי פקד ה' אותם, אמנם הנה כ\"ז הוא בבחי' שמיעה בלבד ולא בבחי' ראי', וע\"י הילוכם בים, ביבשה בתוך הים לפי ב' הפירושי', הן לפי' הזהר והן לפי' האריז\"ל יהי' איך שיהי', הרי נתחבר האצי' שהוא בחי' ראי' לפי ששם מאיר בחי' חכ' שנק' בשם ראי' כמ\"ש וירא ראשית לו, בבריאה שהוא בחי' שמיעה ע\"ש שבבריאה הוא בחי' הארת הבינה שאימא עילאה מקננא בכורסייא הוא בחי' עולם הבריאה כו', לכן היתה אצלם בחי' האמונה בבחי' ראי'.\n[י)] <b>אך</b> עדיין צ\"ל הלא איך שייך ענין האמונה מאחר שראו בראי' חושיית שלא יתכן כלל לומר אחר אמיתות הענין שמתברר ע\"י ראי' שזהו בירור היותר מתאמת מכל הבירורים, וכנ\"ל בענין הגדת העדות כו'. אמנם באמת האמונה שלהם לא הי' בבחי' ומדריגה שראו, כ\"א ע\"י הראי' ניתוסף להם בחי' אמונה בבחי' ומדרגה היותר נעלה, ואם כי בשניהם נאמר שם הוי', היינו וישמעו כי פקד ה', ויאמינו בהוי', אך הנה נודע כי ב' שמות הוי'<sup data-n=\"1146\">8</sup> הם שנאמר קודם י\"ג מדה\"ר ופסיק טעמא בינייהו, והיינו כי שם הוי' הא' הוא בחי' שם הוי' שמקור לסדר ההשתלשלו', כי הוי' לשון מהוה והוא להיותו מחי' ומהוה כל מה שנברא ונוצר ונעשה בכל סדרי ההשתל' כו', ועש\"ז נק' שם הוי', וכמארז\"ל במד\"ר ואני מה שמי לך נאה לקרות הוי' שאתה אדון לכל בריותך<sup data-n=\"1147\">9</sup> כו'. אמנם שם הוי' דלעילא הוא משארז\"ל עד שלא נבה\"ע הי' הוא ושמו בלבד והוא בחי' שם הוי' שלמעלה מסדרי ההשתלשלו' כו'. ולכן מאי דכתי' בהיותם במצרים ויאמינו בהוי' היינו בחי' האמונה בשם הוי' שבסדר השתלשלו', ובא להם ע\"י ששמעו לדברי משה שפקד ה' אותם, והאמינו בה' המהוה הכל, ולהיותו מחי' ומהוה את כולם האמינו בו שבכחו ויכולתו להוציאם ממצרים, וכמ\"ש או הנסה אלקי' לבוא לקחת לו גוי מקרב גוי במסות באותות ובמופתים וגו'. אמנם ע\"י הילוכם בים בחי' עלמא דאתכסי' שנעשה יבשה עלמא דאתגליא שהפך העלם הים לגילוי היבשה היא בחי' ארץ, אז ראו את ידו הגדולה כמ\"ש וירא ישראל את היד הגדולה כו' ועי\"ז האמינו בה' הוא בחי' שם הוי' שלמעלה מסדר השתלשלו', והיינו להיות כי ראו שהפך ים ליבשה שע\"כ לומר שזה",[["1146","8","<b>נודע כי ב' שמות הוי'</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370277\" data-slug=\"torah-or\" data-id=\"3901370277\">תו\"א בשלח סא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370372\" data-slug=\"torah-or\" data-id=\"3901370372\">תצוה פג, ג</a>. פד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380546\" data-slug=\"likkutei-torah\" data-id=\"4001380546\">לקו\"ת חוקת נז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380955\" data-slug=\"likkutei-torah\" data-id=\"4001380955\">דרושים לר\"ה נט, א</a>. מאמרי אדה\"ז תקס\"ו ע' קמג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550721\" data-slug=\"torat-chaim\" data-id=\"2300550721\">תו\"ח שמות</a> (כת\"י הר\"ש סופר) תקנז, א [ובהוצאת תשס\"ד הוא בח\"ב שעה, ד]. סה\"מ תרל\"ב ח\"א ע' קכז. ס\"ע קל-לא. תרמ\"ד (הוצאת תשס\"ג) ע' שמז. תרנ\"ד ע' רחצ ואילך."],["1147","9","<b>וכמארז\"ל. . לך נאה לקרות הוי' שאתה אדון לכל בריותך</b>: ראה לקמן ד\"ה משכיל לאיתן. וש\"נ."]]],[2000510356,"נמשך מלמעלה מסדר ההשתלשלו' דאילו ע\"פ סדר ההשתל' הנה ים הוא בחי' ומדרגה בפ\"ע וגבוה יותר מבחי' ארץ, וא\"א לילך ביבשה בתוך הים, אם לא שהערה ה' רוח ממרום הוא בחי' רוח קדים מבחי' קדמונו של עולם ומשם נמשך להיות הפך ים ליבשה, לכן ע\"י ראי' זו האמינו בבחי' שם הוי' הסוכ\"ע בחי' עד שלא נבה\"ע הי' הוא ושמו בלבד בחי' עושה פלא שגם בחי' פלא נחשב לפניו כעשי' גופני' כו'.\n[יא)] <b>אך</b> עדיין צ\"ל מאי דמשמע מסוגי' הגמ' דסוטה הנ\"ל שהכירו אותו ואמרו זה אלי שראיתי כבר. והענין הוא דהנה הגם שנא' וארד להצילו מיד מצרים, שגם מה שהציל אותם מגזירת כל הבן הילוד הוא ג\"כ בכלל זה, שהרי נא' אנכי ארד עמך מצרימה, ואם נאמר שזהו בחי' אחרת לא היו מכירין אותו מראייתם אז. אך הענין הוא דשם הגם שהצילם מיד מצרים עכ\"ז הי' ההצלה לכאו\"א בפרט, וזה נמשך לכאו\"א מצד שרש נפשו באלקי' חיים, שכאו\"א הוא חלק אלקה ממעל<sup data-n=\"1148\">10</sup> כמ\"ש כי חלק הוי' עמו. ולכן אמרו ומלקט להם ב' עיגולי' א' של שמן וא' של דבש, פי' שכמו ע\"י הלחם יחי' האדם כן ע\"י גילוי נפשו יהי' איך שיהי' עי\"ז יחי' האדם, וי\"ל שב' עיגולים היינו ב' מקיפים חי' יחידה. ומהיות כי חלק הוי' שבכאו\"א האיר, נמשך מזה הצלה לכאו\"א בפרט וכענין אם תגביהי כו' משם אורידך נאום הוי' בכלליות, כ\"ה בדרך פרט בכאו\"א מבחי' חלק הוי' שבנפשו, ולכן ע\"י שראו כל א' חלקו בבחי' הוי' הנה ע\"י החלק הכירו הכלל, ולכן אמרו זה אלי שראיתי כבר הארה ממנו. אמנם בעת קרי\"ס שירד להצילם ועל הכלל כולו יצא ה\"ז בחי' גבוה יותר נעלה, ומה גם כי שם ראו ביבשה, והראי' שעל הים הי' בתוך הים ביבשה שמובן שזהו בחי' היותר נעלה וכמשנת\"ל בענין הפך ים ליבשה כו'. ואי לזאת לא יקשה כלל מהו הגילוי דקרי\"ס הלא גם בעודם בשעבוד מצרים ראו, אך באמת אינו דומה כלל, כי מלבד ששם ראו כ\"א חלקו בבחי' הוי' וכאן ראו בחי' שם הוי' בכללות, הנה שם הי' הראי' ביבשה וכאן בים שהפך ליבשה כו'.\n<b>וזהו</b> כמה לקו באצבע<sup data-n=\"e58\">א</sup> עשר מכות אמור מעתה במצרים לקו עשרה מכות ועל הים לקו חמשים מכות, והיינו כי עשרה מכות שבמצרים הי' נגד ע\"ס, או עשר מל' דע\"ס, ועל הים לקו חמשים מכות נגד בחי' בינה, והיינו מדה כנגד מדה שאמר מי הוי' אשר אשמע בקולו נגד זה לקה על הים אותיות מ\"י נו\"ן מכות, כמארז\"ל במד\"ר. ולדעת הסובר במצרים לקו חמשים מכות ועל הים לקו חמשים ומאתים מכות צ\"ל מה מוסיף על דברי הראשון, ומה הנפק\"מ מנין המכות. אך הענין הוא",[["1148","10","<b>שכאו\"א הוא חלק אלקה ממעל</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>.\n\n<b>א</b>  <b>וזהו כמה לקו באצבע</b>: בשולי הגליונות נרשם בגוכי\"ק: כמה לקו באצבע, עשר מכות עשר ספירות, מל' דעשר ספירות. חמשים בינה, חמשים ומאתים עשירות מאות בחי' מי ברא אלה ומי בעצם. ועי\"ז וירא, כמו הרואה שרואה מרחוק ממה שעומד, כן ראיית הים גבוה יותר, והאמונה עוד יותר כו'."]]],[2000510357,"דבהיות נודע שיחידות הוא במל' ועשירות בז\"א ומאות בבינה<sup data-n=\"1149\">11</sup>, אמנם הנה מה שמאות הוא בבינה זהו מעלת הבינה מה שגבוה מז\"א, והיינו כי בבינה יש מה שזהו נעשה מקור לז\"א כענין ת\"ת דאימא נעשה כתר לז\"א, וזהו מי ברא אלה, אלה הוא בחי' גילוי המדות וא\"ו פעמים וא\"ו עולה ל\"ו כמנין מספר אלה, ומי הוא בינה היא היולדת בחי' ז' מדות לאה ילדה ששה בנים ואחר ילדה בת כו', אבל ענין מה שמאות בבינה היינו מה שהיא מקבלת מבחי' חכ'. ולכן כשאומר חמשים ומאתים היינו חמשים נגד מי, ומאתים היינו עצם הבינה, ועי\"ז ראו את היד הגדולה הוא בחי' א\"א או הארת עתיקא שמאיר בבינה, והאמינו בה' היינו בחי' עד שלא נבה\"ע הוא בחי' מל' דא\"ס שמאיר בבחי' כתר, וכמו מי שעומד במקום זה רואה להלן ממנו כמו פרסא או חצי פרסא<sup data-n=\"1150\">12</sup> וכשבא למקום ההוא הנה הוא רואה להלן עוד, כך בהיות ישראל במצרים נא' ויאמן ע\"י וישמעו, ובים ע\"י גילוי חמשים ומאתים ראו להלן בחי' יד הגדולה מקור דמקור לבחי' הנגלה דים ועי\"ז האמינו בהוי' שלמעלה מסדר ההשתל' כו'.\n<b>אמנם</b> עדיין אינו מובן ואינו מתורץ מה דק\"ל<sup data-n=\"1151\">13</sup> הלא גם משה מיורדי הים הי' ולמה הי' צריך לבקש הראני נא את כבודך, ואם נאמר שהרי משה לא נשתעבד במצרים שהרי כל שבט לוי לא עבדו בפרך וכמ\"ש לכו לסבלותיכם, מ\"מ הרי נא' אז ישיר משה ובנ\"י ונת' במ\"א בד\"ה אז ישיר<sup data-n=\"1152\">14</sup>, שעל הים הגיעו ישראל למדריגה עד שנשתוו למשה, ומ\"מ ראה משה עכ\"פ מה שראו ישראל הגם כי לא נשתעבד. אך הענין הוא דהנה נת\"ל באריכות שענין קרי\"ס הי' הקדמה למ\"ת, ומה שביקש משה הראני נא את כבודך זהו לפי מה שראה יגמה\"ר שהוא בחי' נושא עון ועובר על פשע שזהו אם חטא אדם ועבר על איזה דבר מ\"מ יומשך לו הסליחה, שעכצ\"ל שבחי' ראי' זו היא יותר נעלה, ולכן בים אמרו זה אלי וכאן נאמר ושכותי כפי עליך עד עברי וראית את אחורי ופני לא יראו, והיינו כמ\"ש בד\"ה ואני תפלתי<sup data-n=\"1153\">15</sup> שבחי' אחוריי' וחיצוניות מבחי' גבוה הוא יותר נעלה מבחי' הפנימי' של בחי' שלמטה הימנו כו', ועפ\"ז יובן ג\"כ שהגם דכתי' ודיבר ה' עם משה פנים אל פנים מ\"מ שייך עוד בקשת הראני נא את כבודך, והוא כי מ\"ש ודיבר ה' וגו' זהו שהודיעו דרכי התומ\"צ ופרטיהן, ומה שביקש הראני היינו הגם כי יעברו ח\"ו את דרך ה' מ\"מ יומשך משם הסליחה, וזהו שאמר כבודך היינו בחי' מל' דא\"ס, ואמר לו וראית את אחורי קשר של תפילין, בחי' אחוריי' מבחי' גבוה, תפילין דמארי עלמא שמניחן ע\"ג הראש הם המוחין כו', וה\"ז נעלה יותר מבחי' הפנימי' דבחי' שלמטה מזה. ומ\"ש ודיבר ה' עם משה פנים אל פנים, הלא עם כל ישראל דיבר כמ\"ש פנים בפנים דיבר",[["1149","11","<b>נודע שיחידות הוא במל' ועשירות בז\"א ומאות בבינה</b>: ראה אוה\"ת דרושים ליוה\"כ ע' א'תקסג-ד. ביאוה\"ז להצ\"צ ח\"א ע' רג. סה\"מ תרכ\"ט ע' קס. ועוד."],["1150","12","<b>רואה להלן ממנו כמו פרסא או חצי פרסא</b>: ראה בהנסמן ע\"ז בארוכה בסה\"מ תרל\"ב ח\"א ע' שלב."],["1151","13","<b>דק\"ל</b>: דקשיא לן."],["1152","14","<b>ונת' במ\"א בד\"ה אז ישיר</b>: תרכ\"ט (סה\"מ תרכ\"ט ע' קנ). תרל\"א (לעיל ע' קנז. וש\"נ)."],["1153","15","<b>כמ\"ש בד\"ה ואני תפלתי</b>: תרל\"א (לעיל ע' רנו. וש\"נ)."]]],[2000510358,"הוי' עמכם, צ\"ל כמ\"ש הרמ\"ז שפב\"פ הוא בחי' התלבשות פנים העליון בפנים התחתון, אבל פא\"פ<sup data-n=\"1154\">16</sup> הוא גילוי מבחי' פנים העליון עצמו כו', ומ\"מ פי' פא\"פ הן אמת שזהו גילוי מבחי' פנים העליון אך זהו בערך כמה שיוכל פנים התחתון לקבל, אבל בחי' הראני נא כו' לזה הי' צריך ושכותי כפי הוא בחי' הסתר כי לא יראני האדם וחי כו', ולכן וראית את אחורי לבד כו' שזהו מפני עוצם הגילוי כו'.\n<b></b>[יב)] והנה אחר שיצאו ישראל ממצרים בגילוי אותות ומופתים וקרי\"ס כנ\"ל נאמר ויבא עמלק, ולכאו' יפלא מאין הוא הכח של עמלק לבוא ללחום עם ישראל הלא ראה וידע גודל הנסים שנעשו לישראל, ומכות פרעה ידעו הכל ואיך שטבע בים, וגם זה ידע כי פרעה הוא אותיות הערף<sup data-n=\"1155\">17</sup> להיות כי יניקתו הוא מבחי' אחורי' דא\"א, ונמצא על מה בטח שיוכל להלחם בישראל ואיך גבה לבו כ\"כ לבלי יביט על כל דבר ולהלחם בישראל. אך הענין הוא כמ\"ש בד\"ה אור לארבעה עשר<sup data-n=\"1156\">18</sup>, שעמלק יודע רבונו ומתכוין למרוד בו<sup data-n=\"1157\">19</sup> שזה בחי' החוצפה והגסות והעקשות, שענין העקשות הוא שהגם שיודע היטב שלא יפעול מאומה וגם בעת עקשותו מבין שהנכון אינו אתו מ\"מ ה\"ה מתעקש, וכ\"ה דרך העזי פנים, וגם אם יודע שלא יהי' כדבריו גם אחרי חוצפ[ת]ו ועקשותו, מ\"מ ה\"ה גס הרוח בעיני עצמו שהרי הוא עמד כנגד ולא זולתו, כך יובן בקליפת עמלק שמאחר שיודע את רבונו הרי יודע שלא יוכל כלל לעשות נגד רצון הקב\"ה, ולמה לו לילך להלחם בישראל עם קרובו אשר הוציאם ממצרים ביד חזקה ובזרוע נטוי', אלא שזהו כמשל העלוקה<sup data-n=\"1158\">20</sup> שמוצצת דם ומתה עי\"ז, כך ענין מלחמת עמלק הוא אשר קרך בדרך, פי' שפועל קרירות בנפה\"א, וגם עי\"ז נתקררו ישראל בפני אחרים כמו שפי' רש\"י בס\"פ תצא משל לאמבטי רותחת שאין כל ברי' יכולה לירד לתוכה בא בליעל א' קפץ וירד לתוכה אע\"פ שנכוה הקרה אותה בפני אחרים, כך הוא ענין עמלק אע\"פ דכתי' ויחלוש יהושע מ\"מ נא' בו אשר קרך שקרך בפני אחרים כו', והיינו ע\"י החוצפה ועזות ועקשות שלו וכנ\"ל, והגם שעי\"ז כי מחה אמחה את זכר עמלק מ\"מ כדאי לו בזה וכמשל העלוקה הנ\"ל.\n<b></b>[יג)] והנה אחר יצ\"מ ומלחמת עמלק הי' ספירת העומר, והגם כי התחילו לספור קודם מלחמת עמלק, מ\"מ רוב ספה\"ע הי' אחר מלחמת עמלק. והענין הוא דהנה כתי' ראשית גוים עמלק ואחריתו עדי אובד, ולכאו' יפלא הלא למה יהי' גרוע ראשית גוים מכל הגוים שנא' בהם ועמדו זרים וכתי' כי אז אהפוך אל עמים",[["1154","16","<b>כמ\"ש הרמ\"ז שפב\"פ. . אבל פא\"פ</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830275\" data-slug=\"or-hatorah-hb\" data-id=\"8158830275\">אוה\"ת נשא ע' ערה</a>-ו. ואתחנן ע' קצג. שם (כרך ה) ע' ב'א. ראה ע' תרמ-א. ובארוכה סה\"מ עטר\"ת ס\"ע תקעט ואילך. תרצ\"ז ע' 273 ואילך."],["1155","17","<b>פרעה הוא אותיות הערף</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370260\" data-slug=\"torah-or\" data-id=\"3901370260\">תו\"א וארא נח, ב</a>. לקו\"ת שה\"ש לו, א. סה\"מ תרל\"ב ח\"א ע' נד. רכו. ובכ\"מ."],["1156","18","<b>בד\"ה אור לארבעה עשר</b>: תרל\"א (לעיל ע' רמב)."],["1157","19","<b>שעמלק יודע רבונו ומתכוון למרוד בו</b>: עד\"ז מובא בכ\"מ בדא\"ח, וראה בהנסמן לעיל בד\"ה זכור גו' עמלק."],["1158","20","<b>כמשל העלוקה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, ד</a>."]]],[2000510359,"שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד. אך הענין יובן ע\"פ מה שנת' באורך בד\"ה זכור דעמלק (ל\"א)<sup data-n=\"1159\">21</sup>, ותוכן הענין הוא, דכל האומות הכנעני והחתי הם ז' מדות הרעות, והנה נת' בענין מדות הרעות שבנפש שזהו מפני שהוא מלביש ומצייר את כח המתאוה<sup data-n=\"1160\">22</sup> שבנפשו בציור ולבוש רע, אי לזאת ע\"י התשובה יכול להפוך את כח המתאוה הלזה שיהי' תאב לאלקות שז\"ע בכל לבבך בשני יצריך שגם היצה\"ר ישוב לאהבת ה', אמנם עצם דבר הרע שעשה זה אינו יכול להתהפך, וזהו ענין שריפת פרה אדומה לאפר כמשנ\"ת שם באריכות<sup data-n=\"1161\">23</sup>. אך הנה כ\"ז הוא בז' אומות הם ז' מדות הרעות שצריך להחרימם ע\"ד שריפת הפרה, ועצם כח המתאוה אשר נתלבש בהם יכולים להעלותו. אמנם בעמלק להיות כי ראשית גוים היינו הקליפה שכנגד הדעת<sup data-n=\"1162\">24</sup> שה\"ה יודע את רבונו, פי' רבונו המחי' ומהוה אותו כי ואתה מחיה את כולם כתי' אפי' קלי' וסט\"א, ומ\"מ מתכוין בכוונה למרוד בו, ה\"ה גרוע הרבה משארי האומות ולכן א\"א להעלותו כלל וכלל כ\"א שבירתו זהו תקנתו ככלי חרס, והיינו כי בכל האומות הרי אמרו שאין אדם עובר עבירה אא\"כ נכנס בו רוח שטות, משא\"כ עמלק יודע את רבונו גם בשעת מעשה כו', ולכן מזה הטעם עצמו להיותו ראשית גוים הרי מזה עצמו ה\"ה עדי אובד ואינו דומה כלל לכל האומות כו'. ולכן אחר מלחמת עמלק הוא ספה\"ע בחי' בירור המדות דנה\"ב בחי' ז\"מ הרעות, והוא בחי' הבדיקה דא\"ח<sup data-n=\"1163\">25</sup> אולי עדיין יש איזה יניקה אחיזה לחמץ הוא בחי' הגבורות קשות דדם שמזה יוכל להיות איזה יניקה לז\"מ הרעות כמ\"ש באורך בד\"ה אור לארבעה עשר<sup data-n=\"1164\">26</sup>. ואח\"כ בשבועות הוא הקרבת שתי הלחם וחמץ שבתודה והיינו כי אז יוכל גם החמץ להתעלות, והיינו ע\"ד שארז\"ל ת\"ח צ\"ל בו שמינית שבשמינית ומעטרא לי' כסאסאה לשיבולתא, והיינו בכדי להיות בחי' ויגבה לבו בדרכי ה'<sup data-n=\"1165\">27</sup>, שגם בעבודת ה' צריך הגבהה מעט ולא יפול ח\"ו בעיני עצמו כו'. וז\"ע חג השבועות שאז גם החמץ מתעלה אמנם לא הי' נקרב ע\"ג המזבח כ\"א אכילת כהנים, והוא כי להקריב אותו א\"א כי כל שאור וכל דבש לא תקריבו, כי גם באדם אינו רק שימוש בעלמא שהו\"ע השמינית שבשמינית להיות ויגבה לבו, אבל איננו עצם העבודה כו', וכמ\"כ יובן בחה\"ש ג\"כ שהוא רק אכילה לכהנים המשמשים כו'.",[["1159","21","<b>מה שנת' באורך בד\"ה זכור דעמלק (ל\"א)</b>: לעיל ע' קצב ואילך. וש\"נ."],["1160","22","<b>נת' בענין מדות הרעות. . כח המתאוה</b>: לעיל בד\"ה והחרים ס\"ע רסב-ג. ובארוכה לעיל ד\"ה וידבר גו' זאת חוקת ע' רטז. וש\"נ."],["1161","23","<b>ענין שריפת פרה אדומה. . כמשנ\"ת שם באריכות</b>: לעיל בד\"ה וידבר גו' זאת חוקת שם ע' רטז-יז."],["1162","24","<b>בעמלק. . הקליפה שכנגד הדעת</b>: ראה גם אוה\"ת תצוה ע' א'תרצד. א'תשמא. סה\"מ תרל\"ב ח\"א ע' קטז. רמט."],["1163","25","<b>ספה\"ע בחי' בירור המדות. . בחי' הבדיקה דא\"ח [ דאשת חיל]</b>: ראה בארוכה ביאוה\"ז לאדהאמ\"צ קמ, ג ואילך. ולהצ\"צ (כרך ב) ע' תתקכז ואילך. סה\"מ תרכ\"ו ע' פז ואילך. תרנ\"ג ע' לב ואילך."],["1164","26","<b>כמ\"ש באורך בד\"ה אור לארבעה עשר</b>: תרל\"א (לעיל ע' רלה. וע' רמב)."],["1165","27","<b>ת\"ח צריך להיות בו שמינית שבשמינית. . בחי' ויגבה לבו בדרכי ה'</b>: ראה בכ\"ז בארוכה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370533\" data-slug=\"torah-or\" data-id=\"3901370533\">תו\"א מג\"א קיט, ג</a> ואילך. סה\"מ תשי\"ב ע' 262. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221162\" data-slug=\"likkutei-sichot\" data-id=\"1300221162\">לקו\"ש חכ\"ב ע' 162</a>."]]],[2000510360,"<b></b>[יד)] והנה בכל דור ודור חייב אדם לראות א\"ע כאלו הוא יצא ממצרים, ולאו דוקא בכל דור אלא שבכל יום<sup data-n=\"1166\">28</sup> חייב אדם לראות א\"ע כאלו בו ביום יוצא ממצרים ביד חזקה ובזרוע נטוי'. וע\"ז נתקן סדר התפלה, כי בהיות האדם ישן ושוכב על מטתו הרי הוא במאסר, שנפשו יוצא ולא נשאר בו רק קיסטא דחיותא, ובעמדו בבוקר קודם התפלה נא' בו חדלו לכם מן האדם אשר נשמה באפו, שהוא קודם שתתפללו על דמכם, וע\"י התפלה מתפשטת הנשמה לחיות בחיות רוחני בגוף, ולכן מתחילין להתפלל הודו לה'<sup data-n=\"e59\">ב</sup> קראו בשמו שהוא בחי' הודאה לבד, שזהו ע\"ד אמונה שענין אחד להם, שהרי ענין ההודאה הוא שמודה שכן הוא הגם שאינו מבין ונמצא כי מאמין בזה שמודה לו כו'. ואח\"כ מספר בשבחו של מקום בסיפורי הלולים שמהללים אותו ית', ואומר משפיל רשעים עדי ארץ, לעשות נקמה כו' לאסור כו' שזהו כמו עשרה מכות באותות ומופתים שהיו במצרים, ואח\"כ קודם שירת הים מספר ותרא את עני אבותינו כו' ותתן אותות ומופתים בפרעה ובכל עבדיו כו' עד שאומרים שירת הים הוא כמו קרי\"ס, ועי\"ז יכול להתחיל ברכת ק\"ש שהוא בחי' בירור הנה\"ב שגם הנה\"ב יסכים להיות בבחי' ביטול כמאמרם ז\"ל בכל לבבך בשני יצריך, שזהו כמו ספה\"ע שאחר שיצאו ממצרים התחילו לספור היום יום א' כו' שהוא בירור המדות כו', עד שבא לק\"ש בפסוק ראשון מקבל עליו ב' דברות הראשוני' אנכי ולא יהי' לך מפי הגבורה שמענו, וכמו\"כ בפסוק ראשון דק\"ש ה' אלקינו הוא קבלת דבור אנכי הוי' אלקיך, וה' אחד הוא קבלת דבור לא יהי'<sup data-n=\"1167\">29</sup> לך שז\"ע מ\"ת.\n<b>וענין</b> מלחמת עמלק בעבודה שבלב זו תפלה הוא ללחום עם הרע שבנפשו באמרו וחרה אף ה', דלכאו' יפלא מהו שייך פסוק וחרה אף בק\"ש<sup data-n=\"1168\">30</sup> שהוא תכלית הביטול למס\"נ באחד ובכל מאדך ומהו ענין וחרה אז. אך הענין הוא דהכעס הוא על",[["1166","28","<b>והנה בכל דוד ודור. . ולאו דוקא בכל דור אלא שבכל יום</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא פמ\"ז (סו, ב</a>). וראה גם מכתב י\"א ניסן תשכ\"ח (אג\"ק כ\"ק אדמו\"ר חכ\"ה ע' צח. הגש\"פ עם לקוטי טעמים וכו' (הוצאת תשמ\"ז ואילך) ע' תריח). רד\"ה בכל דור ודור תשל\"ד (סה\"מ י\"א ניסן ע' רסט. וראה גם שם ע' שלז. תט. תסו. ועוד)."],["1167","29","<b>ה' אלקינו הוא קבלת דבור אנכי. . וה' אחד. . דבור לא יהי'</b>: ראה הערת כ\"ק אדמו\"ר בסה\"מ תרל\"ב ח\"ב ע' תעז."],["1168","30","<b>מה שייך פסוק וחרה אף בק\"ש</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380476\" data-slug=\"likkutei-torah\" data-id=\"4001380476\">לקו\"ת שלח מא, א</a>.\n\n<b>ב</b>  <b>ולכן מתחילין להתפלל הודו לה'</b>: בשולי הגליון נרשם בגוכי\"ק: בתפלה בתחילה הודו, ואח\"כ ע\"י שירת הים זה אלי בא לברכת ק\"ש בירור הנה\"ב כמו ספה\"ע, [עד שבא] לק\"ש מסירות נפש, אנכי ולא יהי' לך, ה' אלקינו ה' אחד קבלה על ב' הדברות. אמנם זהו עדיין ממושבותיכם, וענין מלחמת עמלק וחרה אף ה'. ואח\"כ בתפלה אפי' נחש כרוך על עקבו, עמלק נחש הקדמוני לא יפסיק כי לא יוכל כלל, כי אחר קבלת התורה הרי אם פגע בך מנוול משכהו לבית המדרש. וק\"ש תורה ושמו\"ע העלאה והמשכה."]]],[2000510361,"ההיפך אשר מנע אותו מבחי' ביטול זה, וכענין הנהר דינור היוצא מזיעתן של חיות הקדש<sup data-n=\"1169\">31</sup>, שלכאו' ג\"כ יפלא מהו ענין הנהר דינור שהוא בחי' דין ומשפט שיוצא מביטול של החיות הקדש, אך הענין הוא כנ\"ל שע\"י הביטול שלהם ברעש גדול עי\"ז מתמלאי' כעס וקצף על ההיפך, ולכן מהזיעה היוצא מהביטול שלהם יוצא נהר דינור ועל ראש רשעים יחול בגיהנם. ועד\"ז הו\"ע מה שאומרים בפ' שני' דק\"ש וחרה אף שהוא בחי' הכעס הנמשך מהתבוננו' דק\"ש על בחי' הרע שבנפשו, שזהו מה שארז\"ל לעולם ירגיז אדם יצ\"ט על יצה\"ר, שענין ההרגזה הוא בחי' הכעס וקצף<sup data-n=\"1170\">32</sup> שיקצוף עליו מדוע תמנע הטוב הלזה ממני, וה\"ז כדוגמת מלחמת עמלק כו'.\n<b></b>[טו)] אך מה שמלחמת עמלק הי' תיכף אחר יצ\"מ קודם מ\"ת, ובעבודה שבלב זו תפלה זהו אחר ק\"ש, להיות כי ביצ\"מ הי' משה ויהושע הלוחמים במלחמת עמלק, והנה באמת יש בכאו\"א הארת משה<sup data-n=\"1171\">33</sup> שזהו מ\"ש ועתה ישראל מה הוי' אלקיך שואל מעמך כ\"א ליראה והקשו רז\"ל אטו יראה מילתא זוטרתי היא, ותירצו אין לגבי משה מילתא זוטרתי היא, ולכאורה יפלא הלא מעמך כתי' שהבקשה מכל ישראל כמ\"ש ועתה ישראל, אלא שבכאו\"א יש בחי' הארת משה והוא בחי' ביטול דמ\"ה שיש בכאו\"א מישראל, אך זהו אחר ק\"ש דוקא<sup data-n=\"e60\">ג</sup>, בהיות ידוע כי יש ב\"ן ומ\"ה, והיינו שברכת ק\"ש הוא בחי' העלאת ש' ב\"ן שז\"ע בחי' בירור דנה\"ב כו', ואח\"כ בק\"ש שם מ\"ה בחי' למס\"נ באחד ועי\"ז נעשה אדם גימט' מ\"ה היפך בחי' אשר נשמה באפו, וה\"ז בדומה לבחי' משה ויהושע שהם מ\"ה וב\"ן פני משה כפני חמה ופני יהושע כפני לבנה, זו\"נ, ולכן מלחמת עמלק הוא בעבודה שבלב דתפלה אחר ק\"ש דוקא. ואח\"כ בשמו\"ע אפי' נחש כרוך על עקבו לא יפסיק, פי' נחש הוא עמלק<sup data-n=\"1172\">34</sup> בחי' נחש הקדמוני, ובשמו\"ע אפי' נחש כרוך על עקבו לא יפסיק להיות כי זהו אחר ק\"ש ופ' שני' וחרה מלחמת עמלק ואז יש בכאו\"א מישראל בחי' הארת משה ויהושע שלוחם עם בחי' עמלק שכנגדו, וכתי' ויחלוש יהושע את עמלק ואת עמו, ולכן בשמו\"ע אינו יכול להגיע כ\"א לבחי' עקב המתפלל, ואפי' כשנחש כרוך על עקבו לא יפסיק להיות כי הנחש הוא נחלש אחר המלחמה שבפ' שני' דק\"ש לא יוכל להזיק לו כלל.",[["1169","31","<b>וכענין הנהר דינור. . מזיעתן של חיות הקדש</b>: ראה בארוכה תו\"א וישב ל, ד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370145\" data-slug=\"torah-or\" data-id=\"3901370145\">מקץ לא, סע\"א</a>-ב. לב, ד. יתרו סט, ג. מג\"א צו, א. לקו\"ת בשלח א, רע\"ד. במדבר יא, ב. שלח שם מא, א. דרושים לשמע\"צ פד, סע\"ד."],["1170","32","<b>שארז\"ל לעולם ירגיז אדם יצ\"ט על יצה\"ר. . בחי' הכעס וקצף</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380476\" data-slug=\"likkutei-torah\" data-id=\"4001380476\">לקו\"ת שלח שם מא, א</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט (לז, א</a>). פל\"א (לט, ב). תו\"א וישב ל, ד. סה\"מ תרל\"ג ח\"א ע' רלו. סה\"ש תש\"א ע' 59."],["1171","33","<b>בכאו\"א הארת משה. . לגבי משה מילתא זוטרתא היא</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב (נט, א</a>)."],["1172","34","<b>אפי' נחש כרוך על עקבו לא יפסיק. . נחש הוא עמלק</b>: ראה עד\"ז (אודות רחב\"ד) ביאוה\"ז לאדהאמ\"צ קטז, ד. תו\"ח ויצא לז, ג. שערי אורה כא, א. שער האמונה עח, ב. לקו\"ש ח\"ב ע' 375. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560224\" data-slug=\"or-hatorah-hb\" data-id=\"8316560224\">אוה\"ת בראשית (כרך ג) תקעח, ב</a>.\n\n<b>ג</b>  <b>ולכן מלחמת עמלק. . אחר ק\"ש דוקא</b>: בשולי הגליון נרשם בגוכי\"ק: שיאיר בגילוי שיוכל ללחום זהו אחר ק\"ש."]]],[2000510362,"<b>וזהו</b> שאמרו בריש המשנה אין עומדין להתפלל אלא מתוך כובד ראש, פרש\"י הכנעה ושפלות<sup data-n=\"1173\">35</sup>, חסידי' הראשונים היו שוהין שעה א' היינו בחי' התבוננו' קודם התפלה איך שנשתעבדו במצרים והקב\"ה הוציאם ביד חזקה ובזרוע נטוי' והעבירם בים בחרבה, ובהתבוננו' ביטול העולמות לאלקות הבורא ומחדש אותם מאין ליש, ואח\"כ מתחיל בפרטיות בנפשו הבהמי' להגביר נפשו האלקי' על נה\"ב, עד שתחלה צ\"ל בחי' הודאה ע\"ד אמונה, ואח\"כ פסוד\"ז שבחו של מקום וסיפור נוראותיו והנהגותיו משפיל רשעים לעשות נקמה כו' לאסור כו', ואח\"כ קרי\"ס שירת הים, ואח\"כ ברכת ק\"ש בירור דנה\"ב ע\"ד ספה\"ע, ואח\"כ ק\"ש קבלת התורה, וחרה מלחמת עמלק. וי\"ל שגם ע\"י התורה מאיר שם מ\"ה בנה\"א כי זאת התורה אדם בחי' מ\"ה, ואז אח\"כ בשמ\"ע אפי' נחש כרוך על עקבו לא יפסיק כלל להיות כי נחלש הנחש עד שלא יוכל לו כלל.",[["1173","35","<b>כובד ראש פרש\"י הכנעה ושפלות</b>: כ\"ה בכ\"מ בדא\"ח ובהערת כ\"ק אדמו\"ר בסה\"מ תש\"ז ע' 203: התיבה ושפלות אינה ברש\"י (ברכות רפ\"ה). ובאה לתוספת ביאור ענין ההכנעה. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380604\" data-slug=\"likkutei-torah\" data-id=\"4001380604\">לקו\"ת במדבר עא, ג</a>. רמ\"א בשו\"ע או\"ח סצ\"ח סוס\"א. עכ\"ל. וראה גם לקו\"ש חל\"ד ע' 69 הע' 18. אג\"ק כ\"ק אדמו\"ר ח\"ב ע' שפט-צ."]]],[2000510363,"<h3>[הים ראה וינוס]</h3>\n<b>[ד\"ה הים ראה וינוס] </b>\nבס\"ד. פ' שמיני.\n<b></b>[טז)] אמנם עדיין צ\"ל בשורש ענין קרי\"ס והוא ע\"פ מ\"ש הים ראה<sup data-n=\"1174\">1</sup> וינוס וארז\"ל ארונו של יוסף ראה וינס הים מפניו, ולכאו' צ\"ל הלא אנו אומרים בוקע ים לפני משה, ונמצא כי לפני משה נתבקע הים, ואיך יתווך זה עם מה שאמרו ארונו של יוסף ראה ועי\"ז וינוס. וגם צ\"ל דאיתא במד\"ר שטען הים עם משה שאני",[["1174","1","<b>אמנם עדיין צ\"ל. . מ\"ש הים ראה</b>: מאמר זה הוא מאמר השלישי שבהמשך והחרים תרל\"א\". בגוכי\"ק התחלת המאמר הוא: הים ראה וינוס [ראה פאקסימיליא מגוכי\"ק לקמן בהוספות], ואח\"כ נרשם בסיום המאמר שלפנ\"ז להתחיל את המאמר: אמנם עדיין צ\"ל. . ע\"פ מ\"ש הים ראה [כבפנים].\nחלק מהמאמר (מפיסקא: ולהבין ביאור הענין בעבודה, עד פיסקא: והנה כמו המקריב קרבן) הוא תוכן מד\"ה וסמך את ידו דש\"פ ויקרא תרל\"א (לעיל ע' רכט). וראה חלק מהמאמר בתוס' ביאור בד\"ה וסמך את ידו בסה\"מ תרנ\"ג ע' קפד ואילך. ובד\"ה שאו ידיכם בסה\"מ תרפ\"ז ס\"ע רפז ואילך.\nלהתחלת וסיום המאמר (פיסקא: ובכ\"ז יובן שרש ענין קרי\"ס ואילך) ראה ד\"ה הים ראה וינוס ברשימות הצ\"צ לתהלים יהל אור ע' תמא ואילך. אוה\"ת ויקהל ע' ב'רכ.\nלכללות המאמר ראה לקמן ע' שסו ד\"ה אחור וקדם צרתני שהוא רישומי דברים ממאמר זה. וראה גם לעניני המאמר: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380647\" data-slug=\"likkutei-torah\" data-id=\"4001380647\">לקו\"ת מטות פא, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380652\" data-slug=\"likkutei-torah\" data-id=\"4001380652\">פב, ג</a> ואילך. מאמרי אדה\"ז תקס\"ד ע' קפח ואילך. ס\"ע קצא ואילך. תקס\"ז ע' רפט ואילך. אוה\"ת מטות ע' א'רנו ואילך. א'שכב ואילך. ובהוספות לשם (בהוצאת תש\"ס) ע' 25 ואילך. 36 ואילך. סה\"מ תרכ\"ט ע' שנח ואילך. תרל\"ג ח\"ב ע' שצד ואילך."]]],[2000510364,"גדול ממך שאני נבראתי בשלישי ואתה נבראת בשישי, ואם מפני ארונו של יוסף ברח אינו שייך טענות כלל. וגם משמע מלשון הים ראה וינוס שלא הי' טענות כלל. וגם לכאו' יפלא ממ\"ש ואתה הרם את מטך ונטה את ידך על הים ובקעהו למה הי' צריך להטות ידו על הים כמ\"ש ויט משה את ידו על הים וגו', וגם בזה גופא צ\"ל מ\"ש ויט משה גו' ויולך ה' ברוח קדים עזה כל הלילה וישם את הים לחרבה, וגם מהו אומרו אח\"כ ויבקעו המים הלא בקיעת המים הי' צ\"ל קודם שנעשה הים לחרבה, והת\"י מפרש ויבקעו המים ואתבזיעי מיא לתריסר בזיען כל קביל תריסר שבטיא דישראל<sup data-n=\"e61\">ד</sup>.\n<b>ולהבין</b> כ\"ז צ\"ל מ\"ש אחור וקדם צרתני<sup data-n=\"1175\">2</sup> שקאי על בריאת האדם שנברא אחור לכל מע\"ב, ועכ\"ז הוא קדם, והיינו שכל העולם לא נברא אלא לצוות לזה. והיינו כי ע\"פ פשוט הנה בריאת הדומם הוא בשביל הצומח, שהרי צמיחת הצומח א\"א כ\"א ע\"י הדומם והוא הארץ אשר תוציא צמחה ע\"י הזריעה שזורעין בה, וגם בלתי זריעה מצמחת דשאים ועשבים כמ\"ש תוצא הארץ דשא עשב מזריע זרע עץ פרי, שנראה לעין כל שימוש בחי' הדומם לצומח כו'. וכן אנו רואים שהצומח הוא בשביל החי, שהרי כל הצמחים הוא בכדי שיאכלו בע\"ח הדשאים והעשבים המצמיחים, וכן התבואות הם אכילה לבע\"ח, והחי הוא בשביל המדבר שהרי אנו רואים שבהמות טהורות הותרו לאכילה כמ\"ש כירק עשב נתתי לכם את כל וכתי' וזבחת מבקרך ומצאנך, בכל אוות נפשך תזבח ואכלת בשר, וגם במדבר נא' בתת ה' לכם בערב בשר לאכול ולחם בבוקר לשבוע (בשלח י\"ו), ובריאת בהמות טמאות הם למרכב שהם שימוש המדבר. ונמצא כי ע\"פ פשוט כל הדברים שנבראו בששת ימי בראשית בחי' דצ\"ח הם בשביל האדם<sup data-n=\"1176\">3</sup>, וזהו שמצינו בדרז\"ל במד\"ר שנברא האדם אחרון לכולם בכדי שימצא הכל במוכן, שאם הי' נברא ביום ב' עד\"מ לא הי' מוצא מה לאכול ועל מה לרכוב, ונמצא מה שנברא אחרון ה\"ז יתרון המעלה. ולפ\"ז פי' הפסוק אחור וקדם, עם שהוא אחור למע\"ב מ\"מ ה\"ה קדם לשון קדימות ושבח כו'. וא\"כ צ\"ל מה שאמר הים למשה ולא עוד אלא אני גדול ממך שאתה נבראת בששי ואני בשלישי, נמצא שמה שנברא בשלישי ה\"ז יתרון כו'.\n<b></b>[יז)] אך הענין הוא דהן אמת שמה שמצא אדם הכל במוכן ה\"ז יתרון המעלה, אמנם כ\"ז הוא כשמקיים רצון בוראו בקיום דרכי ה' אשר ציונו בקיום התומ\"צ,",[["1175","2","<b>ולהבין כ\"ז צ\"ל מ\"ש אחור וקדם צרתני</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370013\" data-slug=\"torah-or\" data-id=\"3901370013\">תו\"א בראשית ג, ד</a> ואילך. מאמרי אדה\"ז תקס\"ז שם ע' רפט ואילך. סה\"מ תרל\"ג ח\"א ע' רעא ואילך. ח\"ב ע' שצד ואילך. ובדרושים שנסמנו לעיל בתחילת המאמר."],["1176","3","<b>בחי' דצ\"ח הם בשביל האדם</b>: בד\"ה וסמך את ידו תרנ\"ג שם מוסיף: ואפי' שקצים ורמשים ידוע שיש מדינות שהרמשים חופרים את האדמה ומרפאים אותה עד שהיא ראוי' לזריעה.\n\n<b>ד</b>  <b>והת\"י מפרש ויבקעו המים. . דישראל</b>: בגוכי\"ק נוסף כאן (ואח\"כ נרשם ע\"ז שאי\"צ להעתיקו: ורש\"י פי' ויבקעו המים כל מימות שבעולם."]]],[2000510365,"אך אם אינו נזהר לקיים רצון בוראו בקיום המ\"ע, וכ\"ש בעשותו אחת ממצות ה' אשר לא תעשינה ואשם, אז ה\"ה גרוע הרבה מבהמה, שהרי דצ\"ח מקיימים את תפקידם והוא אינו מקיים. וכמו שמצינו שארז\"ל נשאו דשאים ק\"ו בעצמם ומה אילנות שאין דרכם לצאת בערבוביא אמר הכתוב למיניהם אנו שדרכינו לצאת בערבוביא עאכו\"כ, הרי כי השר שלהם נשא ק\"ו דאילו הם עצמם אינם מסוג המדבר ומאין יוכלו לאמר וללמוד ק\"ו, אלא שהשר שלהם נשא ק\"ו<sup data-n=\"1177\">4</sup> בעצמו, והיינו בחי' המלאכים שנק' בשם דשא ועשב שהם בחי' יוצר משרתים ואשר משרתיו<sup data-n=\"1178\">5</sup> כמ\"ש בזהר, עכ\"פ הרי נשאו ק\"ו מאילנות בכדי לקיים רצון בוראם, והאדם שהוא בעל שכל העובר על רצונו ית' ה\"ה גרוע מהם הרבה.\n<b>ובזה</b> יובן משארז\"ל ע\"פ והרגת את האשה ואת הבהמה, אם אדם חטא בהמה מה חטאה, אלא כדי שלא תהא בהמה עוברת בשוק ואומרים זהו שנסקל פלוני על ידה. ויובן זה גם בעבודה שבלב שהבהמה היא בחי' נה\"ב, וכשפוגם באיזהו דבר הרי מוריד גם נפשו הבהמי' ג\"כ, שהיא באה להתתקן ע\"י הנה\"א מבחי' התיקון וע\"י הפגם הרי מורידה עוד, ונמצא כי הי' מקח טעות לגמרי בענין ירידת נה\"א בכדי לתקן נה\"ב שמבחי' התהו, ולא די שלא תיקנה אלא הורידה ממעלתה ודינו בסקילה הוא בחי' לב האבן, וכמו במצות סקילה היו דוחפין אותו מאחוריו נהפך על לבו הופכו על מתניו אם מת בזה יצא, וא\"ל העד נוטל את האבן ומניחו על לבו, כן הוא ברוחניות שנעשה אצלו טמטום הלב וטמטום המוח<sup data-n=\"1179\">6</sup> עד שנעשה קשה כאבן לבלי יוכל לבוא לבחי' איזה השגה בהתבוננו' אלקותו ית' וכ\"ש להוליד אהוי\"ר כו'. וזהו משארז\"ל אין חיה רעה שולטת באדם אא\"כ נדמה לו כבהמה, פי' שאם לא חטא הרי נא' ומוראכם וחתכם יהי' על כל חית השדה, אבל כשחטא הרי מסתלק בחי' הצלם אלקי' שבאדם ההוא, ולכן נדמה לו כבהמה, ובאמת לא כבהמה סתם אלא כבהמה שחטא אדם בה, והיינו שע\"י כח המתאוה שבנה\"ב בא והלבישה וציירה בציור רע עד שנתחייב סקילה ואין לו תקנה אלא לקיים בעצמו מצות סקילה, והיינו כמו שאומרים בק\"ש שעל המטה אם פגמתי באות יו\"ד ונתחייבתי סקילה כו', הריני כאילו נסקלתי, והיינו שע\"י שמקבל עליו דין שמים בחרטה גמורה ובעזיבת החטא מוחלין לו.\n<b></b>[יח)] ובכ\"ז יובן מה שאמרו שאם חטא אדם אומרים לו אפי' יתוש קדמך, פי' קדמך שלבד מה שנברא תחלה ולבד מה שהיתוש לא חטא ומקיים רצון",[["1177","4","<b>נשאו דשאים ק\"ו בעצמם. . שהשר שלהם נשא ק\"ו</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' קנח. תרל\"ב ח\"א ע' רעג. ועוד."],["1178","5","<b>המלאכים שנק' בשם דשא ועשב. . יוצר משרתים ואשר משרתיו</b>: ראה בכ\"ז אוה\"ת בראשית לג, סע\"ב ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370129\" data-slug=\"torah-or\" data-id=\"3901370129\">תו\"א וישב כז, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380230\" data-slug=\"likkutei-torah\" data-id=\"4001380230\">לקו\"ת אמור לו, א</a>. פינחס עט, סע\"ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560364\" data-slug=\"or-hatorah-hb\" data-id=\"8316560364\">האזינו עו, ד</a>. סידור עם דא\"ח סב, ב. פט, ד. רכז, ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450607\" data-slug=\"or-hatorah-hb\" data-id=\"8316450607\">אוה\"ת נח (כרך ג</a>) תרמח, ב ואילך. ביאוה\"ז להצ\"צ (כרך ב) ע' תרז. סה\"מ תרכ\"ט ע' קו ואילך. וע' קנח. תרס\"א ע' רו."],["1179","6","<b>במצות סקילה. . ברוחניות. . טמטום הלב וטמטום המוח</b>: בהבא לקמן ראה לקו\"ת דרושים לשבת שובה סד, ד. מאמרי אדהאמ\"צ דברים ח\"ג ס\"ע א'פב ואילך. סה\"מ תרל\"ב ח\"א ע' קנ. ח\"ב ע' שעו. תרס\"ה ע' לה ואילך."]]],[2000510366,"בוראו כנודע ממעשה דטיטוס, אלא שבאמת שרשו נעלה יותר הרבה שהרי שרשו הוא מבחי' התהו שקדם לתיקון. וענין קדימת התהו אין פירושו שקדם בזמן אלא שקדם במעלה ומדריגה, והיינו כנודע שבתהו הי' ריבוי האור<sup data-n=\"1180\">7</sup> ומיעוט הכלי, ובתיקון הוא מיעוט האור וריבוי הכלים. והנה פי' ריבוי האור ומיעוט האור אין פירושו שאור זה עצמו שהי' בבחי' התהו בריבוי נתמעט בבחי' התיקון, אלא שענין ריבוי האור ומיעוט האור הוא שמיעוט האור דתיקון אינו בערך כלל לבחי' ריבוי האור דתהו. ויובן דבר זה ממה שמצינו בדרז\"ל אור שנברא ביום ראשון<sup data-n=\"1181\">8</sup> הי' אדם מביט מסוף העולם ועד סופו, ודקדק הלשון מסוף העולם ועד סופו ולא אמרו מתחלת העולם ועד סופו, והיינו שהכוונה היא מתחילת עלמא דאתכסי' מלמטלמ\"ע עד סוף עלמא דאתגליא מלמעלמ\"ט, ע' בד\"ה אם בחוקותי תלכו (למ\"ד<sup data-n=\"1182\">9</sup>), ונמצא כי ע\"י האור שנברא ביום ראשון הי' אדם יכול להביט בשני עולמות עלמא דאתכסי' ועדאת\"ג, ואח\"כ כשנתמעט האור הרי ע\"י אור היום או השמש יכולים להביט רק כמו פרסא או חצי פרסא<sup data-n=\"1183\">10</sup> שאינו בערך כלל לקרותו בשם ריבוי ומיעוט, שנאמר שהאור שנתמעט הוא מאור זה עצמו שהי' בריבוי, שהרי אינו בערך כלל וכלל, והרי שניהם הם מבחי' התיקון, כ\"ש מיעוט האור דתיקון לגבי ריבוי האור דתהו אינו בערך כלל וכלל. ונמצא כי מעלת הנבראי' גדלה מאד על אדם החוטא, שלבד מה שקדמו בזמן ההתהוות ולבד מה שמקיימים רצון בוראן הנה שרשן נעלה הרבה יותר כו'. ומ\"מ אם האדם מקיים תומ\"צ ושומר פקודתו אשר פוקד ע\"פ משה בכל פרטיהן ודקדוקיהן הרי עם כי גם אז התהו קדמה, מ\"מ הרי באמת בנין התהו ושבה\"כ דתהו ה\"ז בונה וסותר ע\"מ לבנות<sup data-n=\"1184\">11</sup> הוא, דהנה באדם יתכן בעת שעושה איזהו דבר מדמה בנפשו שיתקיים, אבל לא כן הוא למעלה שהי' בונה בתחלה ע\"מ לסתור, שהיתכן שיפלא מה' דבר אלא שבנה ע\"מ לסתור, וכן בענין השבירה ג\"כ כן הוא שבאדם יתכן בעת שהוא בונה ה\"ה מדמה שיתקיים הגם שאח\"כ אינו מתקיים, ולא כן הוא למעלה שלא יתכן לומר כן והיפלא מה' דבר, אלא שהי' סותר בכוונה ע\"מ לבנות בחי' עולם התיקון. ונמצא הגם כי כל הנבראי' שקדמו קודם בריאת האדם הם מבחי' התהו שקדם באמת לתיקון, אבל מאחר שהאדם מתקן חלקו שניתן לו לתקן בבחי' התיקון הרי כל קדימת התהו הי' בשביל זה, ונמצא כי לבסוף העיקר הוא בחי' התיקון. ונמצא כי כל קדימת התהו הוא בשביל התיקון, והאדם המתקן ה\"ה משלים",[["1180","7","<b>וענין קדימת התהו. . במעלה ומדריגה. . כנודע שבתהו הי' ריבוי האור</b>: בהבא לקמן עד סוף הפיסקא ראה סה\"מ תרכ\"ו ע' צו ואילך. תר\"ל ע' קמא ואילך. קנ ואילך. תרל\"ב ח\"א ע' קסג. ח\"ב ע' תקנט. תקסב."],["1181","8","<b>ויובן ד\"ז. . אור שנברא ביום ראשון</b>: בהבא לקמן ראה במקומות שנסמנו בהערה שלפנ\"ז."],["1182","9","<b>בד\"ה אם בחוקותי תלכו (למ\"ד)</b>: סה\"מ תר\"ל שם ע' קמא ואילך."],["1183","10","<b>יכולים להביט רק כמו פרסא או חצי פרסא</b>: ראה בהנסמן ע\"ז בהמילואים לסה\"מ תרל\"ב ח\"א ע' שלב. ובד\"ה וסמך את ידו תרנ\"ג שם ע' קפו: ערך פרסא או מיל."],["1184","11","<b>בנין התהו ושבה\"כ. . בונה וסותר ע\"מ לבנות</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכח. מאמרי אדהאמ\"צ דברים ח\"ב ע' תקפב ואילך. סה\"מ תרל\"ב ח\"ב ע' תכט. וע' תלה. וע' תקנט. המשך תרס\"ו ע' שנה. ועוד."]]],[2000510367,"כל המכוון מבחי' התהו והתיקון, ונמצא כי כל מה שנברא הן מבחי' התיקון והן מקדימת התהו בבנין ושבירה לא נברא אלא לצוות לזה כו'. וזהו בבטן עקב את אחיו שהוא מבחי' התהו, להיות כי יעקב ע\"י עבודתו יורש מקומו בבחי' התהו, והיינו שישרו בחי' אורות דתהו בכלים דתיקון כו'.\n<b></b>[יט)] ולהבין ביאור הענין בעבודה שבלב זו תפלה, צ\"ל תחלה שרש ענין הקרבנות<sup data-n=\"1185\">12</sup>, שלכאו' אם חטא אדם ומעל בקדה\"ק, או בעשותו אחת ממצות ה' אשר לא תעשינה בשגגה אז הי' צריך להביא קרבן על המזבח ולהתוודות עליו ולסמוך שתי ידיו עליו, והכהן הי' מעלה אותו ע\"ג המזבח. ולכאו' יפלא מהו ענין הקרבת הבהמה על המזבח ועי\"ז יתכפר נפש החוטא, ומכ\"ש שהחוטא הוא אדם מדבר ובעל שכל והנקרב הוא בע\"ח שפחות מעלה מהמדבר, והאיך יתכפר המדבר ע\"י הקרבת הבע\"ח. אך הענין הוא דהנה החוטא באדם הוא נפשו הבהמי', שהוא בחי' כח המתאוה<sup data-n=\"1186\">13</sup> שבנפשו הבהמי' שהלביש וצייר ציור רע בנה\"ב, היינו בבחי' כח המתאוה שבו עד שעבר על איזהו דבר כו'. והנה נה\"ב שבאדם שרשה ג\"כ מבחי' פני שור אלא שהיא מבחי' פני אדם שבפני שור<sup data-n=\"1187\">14</sup> שהרי ד' פנים לארבעתן, ולכן כשרוח שטות מכסה על השכל כמאמר אין אדם עובר עבירה אא\"כ נכנס בו רוח שטות המכסה על האמת, ולכן גם בגשמיות עושה שטותי' נוראים עד שפועל הענין הרע והמר כו', ואז נדמה לו כבהמה להיות כי הכחות המעולים שבנפשו האלקי' מסתלקי' קודם החטא כמ\"ש בכהאריז\"ל ולא נשאר בו רק נה\"ב אשר צייר בה ציור רע ולבש אותה בלבוש צואה כמשנת\"ל, לכן התיקון שלו הוא אם זהו בשוגג להביא קרבן בהמה ע\"ג המזבח והיינו שע\"י הקרבת הבהמה גשמיות מתעלה גם נה\"ב, להיות כי דבר הרוחני א\"א להיות מתעלה כ\"א שיהי' דבר גשם שיתאחז ע\"י, כי כשם שא\"א להמשיך דבר הרוחני שיתפשט למטה כמשל האש או חיות הנפש בלתי הגוף, כן א\"א להעלות דבר הרוחני כ\"א ע\"י אחיזת איזה דבר גשמי שבה וע\"י יתעלה הכח הרוחני, אם לא בהסתלקות איזה [דבר] אז מסתלק מדבר הגשמי, אבל אין זה עלי' כ\"א הסתלקות מהעדר התפשטות כו'. ואי לזאת בכדי שיתעלה נה\"ב הי' צריך להביא קרבן בהמה ששורשה ג\"כ מבחי' פני שור, רק ששורשה הוא מבחי' פני שור שבפני שור, והנה\"ב שורשה מפני",[["1185","12","<b>ולהבין ביאור הענין. . שרש ענין הקרבנות</b>: בהבא לקמן ראה בדרושים שנסמנו לעיל בתחילת המאמר. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380421\" data-slug=\"likkutei-torah\" data-id=\"4001380421\">לקו\"ת נשא כח, ב</a> ואילך. סה\"מ תרכ\"ז ע' קלד ואילך. וש\"נ. תרכ\"ט ע' סט ואילך. וש\"נ. ועוד."],["1186","13","<b>נפשו הבהמית. . כח המתאוה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חוקת נו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380964\" data-slug=\"likkutei-torah\" data-id=\"4001380964\">דרושים לר\"ה סא, ב</a>. סה\"מ תרכ\"ט ע' קא-ב. לעיל ד\"ה והחרים."],["1187","14","<b>נה\"ב שבאדם שרשה. . מבחי' פני אדם שבפני שור</b>: ראה מאמרי אדה\"ז תקע\"א ע' קעח: שנה\"ב שבאדם שרשו כו' בבחי' פני אדם שבפני שור. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380423\" data-slug=\"likkutei-torah\" data-id=\"4001380423\">לקו\"ת נשא כח, רע\"ד</a>: ושרש וחיות נה\"ב שבאדם הוא מבחי' אדם שבחיות שבמרכבה. [וראה מ\"ש ע\"ז בהוספות ללקו\"ת יח, ג]. וראה גם אוה\"ת דרושים לחה\"פ (כרך ג) ע' תשסד. תבוא ע' תתרסז. דרושים לשמע\"צ ע' א'תשפא. סה\"מ תרל\"ב ח\"א ע' רפה. עטר\"ת (הוצאת תשמ\"ח) ע' תרסה. תרפ\"ז ע' מא. תרצ\"ט ע' 63. תש\"ה ס\"ע 76. וראה לעיל ע' רלג."]]],[2000510368,"אדם שבפני שור ולכן הרי הם קרובים לגבי הדדי, ועי\"ז מתעלית נפש החוטא ליכלל למעלה תחת אשר נפרדה מאלקי' חיים ע\"י פעולתה שפעלה לעשות הרע בעיני ה' כו', וע\"י הקרבת הבהמה מתעלית בבחי' פני שור ועי\"ז החיות נושאות את הכסא עם בחי' אדם שעל הכסא לבחי' כי לא אדם הוא כו'. וה\"ז כדוגמת המאכל שאנו רואים שע\"י המאכל יחי' האדם, כן הקרבנות נק' בשם לחם כמ\"ש את קרבני לחמי לאשי הם השרפי' שנק' אשי<sup data-n=\"1188\">15</sup> ע\"ש שכבר נשרפו בבחי' הביטול בבחי' אש שלמעלה כו', והקרבת הקרבן הוא לחם לבחי' האישים, שכמו הלחם מחזק את האדם שיוכל ללמוד ולהתפלל, כן לחם דקרבנות מחזק את חיות המרכבה שיוכלו להיות נושאות את הכסא. והגם כי החיות נושאות ומנושאות<sup data-n=\"1189\">16</sup> שהכסא עצמה נותנת כח בחיות הנושאות אותה, וכענין ארון נושאיו נשא, מ\"מ הנה תחלה הם צריכים להעלות את הכסא ואז הכסא נושא את נושאיו שבתחלה הם נושאות ואח\"כ מנושאות, וכענין שארז\"ל אע\"פ שאש יורד מלמעלה מצוה להביא מן ההדיוט שהוא בחי' הקרבת הכהן האש ע\"ג המזבח ואח\"כ אש שלמעלה יורד בחי' ארי' דאכיל קרבנין כו', וכמו\"כ יובן בענין חיות הנושאות את הכסא שמתחלה הם נושאות כענין להביא מן ההדיוט ואח\"כ הם מנושאות כענין אש שלמעלה ארי' דאכיל קרבנין ומעלה את הקרבן, כ\"ה בענין חיות הנושאות את הכסא, ובכדי שיוכלו להעלות את הכסא עם בחי' אדם שעה\"כ לבחי' כי לא אדם הוא, זהו ע\"י הקרבנות שנק' לחמי לאשי, שכמו הלחם מחזק את האדם שיוכל ללמוד ולהתפלל, כן הקרבנות הם לחם לחזק את החיות הנושאות את הכסא שיוכלו לשאת את הכסא כו'. אמנם בהיות נודע כי הבהמה היא גשמיות ונפלה בשבה\"כ למטה מטה מאד לכן צריך האדם להקדיש את הקרבן בפה וע\"י קידוש בפה ממשיך עליו או\"מ דקדושה<sup data-n=\"1190\">17</sup> שיוצא מהבל פה האדם. וגם ענין הסמיכה שהוא מה שסומך שתי ידיו עליו ז\"ע שנותן לו כח מבחי' מ\"ה, כי אדם בגימ' מ\"ה ובהמה בגמ' ב\"ן, ומ\"ה נותן כח בבחי' ב\"ן שתוכל להתעלות, ונת\"ל שענין בחי' הרוחני' א\"א להיות נמשך כ\"א ע\"י איזה דבר גשם דוקא זהו\"ע הסמיכה שסומך שתי ידיו עליו כו', וכמו ביהושע נא' כי סמך משה את ידיו עליו כו' כמשנ\"ת באורך בד\"ה וסמך את ידו<sup data-n=\"1191\">18</sup> על ראש העולה כו'.\n[כ)] <b>וע\"פ</b> הקדמה זו נבין ג\"כ בתפלה שכנגד תמידין תקנו שנמצא שגם בעבודה שבלב זו תפלה יש ג\"כ ענין ההקרבה והוא הקרבת הנה\"ב שבאדם שעז\"נ אדם כי יקריב מכם ולא נא' אדם מכם כי יקריב<sup data-n=\"1192\">19</sup>, דאם הי' נא' אדם מכם כי",[["1188","15","<b>לחמי לאשי הם השרפים שנק' אשי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380631\" data-slug=\"likkutei-torah\" data-id=\"4001380631\">לקו\"ת פנחס עז, ד</a>. סה\"מ תרכ\"ט שם ע' סט."],["1189","16","<b>החיות נושאות ומנושאות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370317\" data-slug=\"torah-or\" data-id=\"3901370317\">תו\"א יתרו עא, ב</a> ואילך. וראה בהנסמן ע\"ז בסה\"מ תרכ\"ט ע' קמח."],["1190","17","<b>להקדיש את הקרבן בפה. . ממשיך עליו או\"מ דקדושה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380651\" data-slug=\"likkutei-torah\" data-id=\"4001380651\">לקו\"ת מטות שם פב, סע\"ב</a>. פג, ב. מאמרי אדה\"ז תקס\"ז שם ס\"ע רצא-ב."],["1191","18","<b>כמשנ\"ת באורך בד\"ה וסמך את ידו</b>: תרל\"א (לעיל ע' רכח-ט. וע' רלג-ד). וראה גם אוה\"ת ויקרא ע' רכא ואילך."],["1192","19","<b>אדם כי יקריב מכם ולא נא' אדם מכם כי יקריב</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380083\" data-slug=\"likkutei-torah\" data-id=\"4001380083\">לקו\"ת ויקרא ב, ב</a> ואילך. סה\"מ תרל\"ב ח\"א ע' שט. וע' שיד. סה\"מ קונטרסים ח\"ב תנ, א ואילך. סה\"מ תש\"י ע' 112-13. סה\"מ מלוקט ח\"א ע' יט-כ. אג\"ק אדמו\"ר מהוריי\"צ ח\"ג ע' שנד. ועוד."]]],[2000510369,"יקריב הי' תיבת מכם מפריש את האדם המקריב הקרבן מכל האדם אשר איננו מקריב בעת זה קרבן, אבל כשנאמר אדם כי יקריב מכם הנה תיבת מכם מורה שההקרבה היא מכם, והו\"ע בחי' הקרבת נה\"ב שבאדם ששרשה ג\"כ מבחי' פני שור שבמרכבה רק הוא מבחי' פני אדם שבפני שור וכנ\"ל, ולכן זאת היא עבודת האדם להקריב נפשו הבהמית הוא בחי' הכח המתאוה שבו. ויש בזה חילוקי מדריגות כמו בקרבנות נא' מן הבקר ומן הצאן, ואם עז קרבנו, כן יש חילוקי מדריגות אלו בהקרבת נפשו הבהמי' ג\"כ, שענין הבקר הוא כמ\"ש כשור לעול, שאם מקבל עליו עומ\"ש ה\"ז טוב, ואם לא קיבל עליו עומ\"ש צריך להקריב קרבן מן הבקר היינו בחי' העול והוא לקבל עליו עומ\"ש ועול תורה, ואם יקבל עליו עומ\"ש אזי יפרוק מעליו עול דרך ארץ כמארז\"ל כל המקבל עליו עול תורה פורקין מעליו עול דרך ארץ. וצאן הוא קול רחמים, והיינו אם פגם בהעדר הרחמנות על מי שהי' צריך לרחם עליו צריך להקריב קרבן צאן הוא בחי' התעוררות רחמים רבים כו'. ואם עז קרבנו היינו אם פגם בזה שארז\"ל הוי עז כנמר וקל כנשר ורץ כצבי וגבור כארי לעשות רצון אביך שבשמים, ואם לא קיים צריך לעורר בנפשו בחי' העזות לעמוד נגד מונע מבית ומבחוץ בכדי לקיים כמארז\"ל הנ\"ל הוי עז (אבל עזות פנים זה א\"א להעלות כלל וצריך לדחותו לגמרי שזהו מקליפת עמלק וכמו כלי חרס ששבירתן זהו תקנתן כמ\"ש במ\"א<sup data-n=\"1193\">20</sup>). וענין הקרבת חלב ודם הוא בחי' התענוג<sup data-n=\"1194\">21</sup>, כמו החלב שמתרבה מתענוגים צריך להיות כל חלב לה', היינו להיות כל תענוגו מהתבוננו' [ב]אלקי' חיים ומלך עולם, ומזה יקבל תענוג מהשגת אלקותו ית'. ודם הוא בחי' גבורות וחיות קיום הנפש בגוף, ישים חפצו ולבו תמיד כל היום וכל הלילה לא יחשה מקיום רצונו ית', ויעורר א\"ע באהבה כרשפי אש התשוקה לאהבתו ית' ה\"ז בחי' הקרבת הדם. וענין הסמיכה בנפש האדם<sup data-n=\"1195\">22</sup> זהו ענין לימוד התורה שקודם התפלה שהתורה היא בחי' עוז ותושי' שנותנת כח בנה\"א ומתשת כח הנה\"ב כמ\"ש בתו\"א בד\"ה בחדש השלישי<sup data-n=\"1196\">23</sup>, וענין מה שמתשת כח הנה\"ב היינו בכדי שיוכל להתברר, וכענין משנ\"ת במ\"א בענין ויברך יעקב את פרעה<sup data-n=\"1197\">24</sup> שברכו שיוכל להתברר, כ\"ה ענין מה שתורה מתשת כח הנה\"ב היינו שיוכל להתברר ולהתעלות מגשמיותו ליכלל וליבטל באוא\"ס ב\"ה. ועוי\"ל שז\"ע סידור שבחו של מקום שקודם התפלה",[["1193","20","<b>עזות פנים. . מקליפת עמלק. . ששבירתן זהו תקנתן כמ\"ש במ\"א</b>: ראה לעיל ד\"ה זכור גו' עמלק וד\"ה זכרוניכם. וש\"נ."],["1194","21","<b>וענין הקרבת חלב ודם הוא בחי' התענוג</b>: בהבא לקמן ראה מאמרי אדה\"ז הקצרים ע' צב ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370137\" data-slug=\"torah-or\" data-id=\"3901370137\">תו\"א וישב כט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381178\" data-slug=\"likkutei-torah\" data-id=\"4001381178\">לקו\"ת שה\"ש יב, ב</a>. סה\"מ תרכ\"ט ע' קיד. המשך תרס\"ו ס\"ע קמא-ב. המשך תער\"ב ח\"א ע' תמא."],["1195","22","<b>וענין הסמיכה בנפש האדם</b>: ראה ד\"ה שאו ידיכם תרפ\"ז שם ע' רכ שהתחלת הסמיכה הוא בק\"ש שעל המטה. עיי\"ש."],["1196","23","<b>כמ\"ש בת\"א בד\"ה בחדש השלישי</b>: פ' יתרו דף סז, ב."],["1197","24","<b>משנ\"ת במ\"א בענין ויברך יעקב את פרעה</b>: ביאוה\"ז לאדהאמ\"צ קלז, ב-ג. ולהצ\"צ (כרך ב) ע' תשל ואילך. אוה\"ת ויגש (כרך ו) תתשיג, א. פנחס ע' א'ריג."]]]]});
